'use strict';
/* ====== Patch notes (shown by the 📜 button on the main menu) ======
   HOW TO ADD A RELEASE: put a new object at the TOP of PATCHES.
     id    unique string, normally the date ('2026-10-16'; for a second release on the same day '2026-10-16b'). When the id is not the one the
           player has already read, the 📜 button shows a red dot.
     date  'YYYY-MM-DD' - shown in the player's language.
     new   new features                (section "Novità / What's new",  hidden when empty)
     fix   bug fixes                   (section "Correzioni / Bug fixes", hidden when empty)
     bal   balance changes             (section "Bilanciamento / Balance", hidden when empty)
   name  (optional) T() title of the release, shown beside the date.
   sum   (optional) T() one or two sentences: what this release is about, for someone who reads nothing else.
   Inside each section an item is either a T() line or a group {g:T('Titolo','Title'),l:[T(),T(),...]}. Use groups as soon as a section has more than about
   five lines, with the same group names from one release to the next (Mappe, Combattimento, Cimeli e negozio, Ritmo della partita, Difficoltà, Economia, Armi...).
   Every entry is T('italiano','english'). One line per change, written for players, not for programmers.
   STYLE - be specific, never vague ("migliorato", "sistemato"): say WHAT changed and the numbers (from -> to, e.g. "30% della Salute (prima 7%)"), WHEN it applies
   (when it starts, what it never does) and WHERE to find it (e.g. "Impostazioni > Video"). Use the exact names the game shows: Zenny, Forziere, Sfera del Drago,
   Compagno, Kaioken, Esperienza (XP), Salute, Ricarica, Fortuna, Armatura, and the names of characters, companions, enemies and stages. */
const PATCHES=[
  {id:'2026-10-27b',date:'2026-10-27',
    name:T("Quantità, scrigni e cronologia","Amount, chests and event history"),
    sum:T("Quantità arriva tra le carte del level-up, gli scrigni danno potenziamenti del personaggio (i cimeli solo a build completa), le trappole scattano quando le calpesti e la pausa ha la Cronologia Eventi.","Amount joins the level-up cards, chests give character upgrades (trinkets only once your build is complete), traps fire when you step on them and the pause screen has an Event History."),
    new:[
      {g:T('Potenziamenti','Upgrades'),l:[
        T("Quantità (+1 proiettile per ogni arma) è anche un potenziamento del level-up, fino al livello 2; si somma a quella del negozio, delle trasformazioni e dei cimeli.","Amount (+1 projectile for every weapon) is also a level-up upgrade, up to level 2; it adds to the shop's, the forms' and the trinkets'."),
        T("Doppio Sunday ora evolve con Quantità (prima con Camera Gravitazionale) per la prima evoluzione; la seconda resta con Zenkai.","Double Sunday now evolves with Amount (was Gravity Chamber) for its first evolution; the second still needs Zenkai.")]},
      {g:T('Negozio','Shop'),l:[
        T("Ogni potenziamento comprato ha un interruttore ATTIVO / SPENTO: spento non conta nelle partite ma resta comprato. In alto c'è \"Disattiva tutti\" / \"Attiva tutti\".","Every upgrade you bought has an ON / OFF switch: OFF it does not count in your runs but stays bought. At the top there is \"Switch all off\" / \"Switch all on\"."),
        T("Tieni premuto Maiusc mentre clicchi sul prezzo per comprare il massimo dei livelli che ti puoi permettere (il tooltip del pulsante dice quanti e quanto costano).","Hold Shift while clicking the price to buy as many levels as you can afford (the button's tooltip says how many and how much).")]},
      {g:T('Interfaccia','Interface'),l:[
        T("Pausa: nuova scheda \"Cronologia Eventi\" accanto al Grimorio, con tutti i messaggi della partita e il minuto in cui sono apparsi.","Pause: new \"Event History\" tab next to the Grimoire, with every message of the run and the minute it appeared."),
        T("Pausa, scheda Mappa: passando sopra una statistica vedi da cosa è fatta (base del personaggio, potenziamenti, negozio, trasformazione, cimeli, Fagioli Senzu e il resto). Nuova riga Quantità.","Pause, Map tab: hover a stat to see what it is made of (character base, upgrades, shop, form, trinkets, Senzu beans and the rest). New Amount row."),
        T("Fine partita: due pulsanti \"Danni inflitti\" (per arma, anche le trappole) e \"Danni subiti\" (per nemico e boss, trappole, lava, altro).","End of run: two buttons \"Damage dealt\" (by weapon, traps too) and \"Damage taken\" (by enemy and boss, traps, lava, other)."),
        T("I messaggi in partita non si sovrappongono più: un annuncio resta almeno 2 secondi e sfuma prima del successivo; le scritte sopra il personaggio (cimelio venduto, Fortuna +3%...) si impilano una sopra l'altra.","In-game messages no longer overlap: an announcement stays at least 2 seconds and fades before the next one; the labels above the hero (trinket sold, Luck +3%...) stack on top of each other.")]}],
    bal:[
      {g:T('Forzieri e cimeli','Chests and trinkets'),l:[
        T("Forzieri Epici e superiori molto più rari: Epico 6% (prima 15%), Leggendario 1,6% (prima 5%), Mitico 0,4% (prima 1%); la Fortuna li fa salire come prima.","Epic and higher chests are much rarer: Epic 6% (was 15%), Legendary 1.6% (was 5%), Mythic 0.4% (was 1%); Luck raises them as before."),
        T("I forzieri danno potenziamenti del personaggio (livelli di armi e potenziamenti, anche nuovi) al posto dei cimeli: 1 / 3 / 4 / 5 / 6 dal Comune al Mitico. Lo stesso per le Capsule.","Chests give character upgrades (weapon and upgrade levels, new ones too) instead of trinkets: 1 / 3 / 4 / 5 / 6 from Common to Mythic. Capsules too."),
        T("I cimeli escono dai forzieri solo quando non resta niente da potenziare: Comune 1, Raro 2, Epico 3 (Perfezione da 35%), Leggendario 3 (prima 4, Perfezione da 50%), Mitico 3 (prima 5, Perfezione da 75%).","Trinkets only come out of chests once there is nothing left to upgrade: Common 1, Rare 2, Epic 3 (Perfection from 35%), Legendary 3 (was 4, Perfection from 50%), Mythic 3 (was 5, Perfection from 75%)."),
        T("Nessun limite ai cimeli in partita: tutti quelli che trovi contano (gli slot prima della partita restano 1-3).","No limit to the trinkets carried in a run: all the ones you find count (the slots before a run stay 1-3)."),
        T("Cimeli con effetto a tempo dimezzati: Sfera a 4 Stelle ogni 16 s (prima 8), Anello del Tempo ogni 40 s (prima 20), Specchio dei Kaioh ogni 30 s (prima 15).","Timed trinket effects halved: Four-Star Ball every 16 s (was 8), Ring of Time every 40 s (was 20), Kaioh Mirror every 30 s (was 15).")]},
      {g:T('Trasformazioni','Transformations'),l:[
        T("Per tutti i personaggi le forme arrivano ai livelli 5, 10, 20, 30, 50, 70, 90 e 120 (prima 14, 24, 36, 50, 66, 84, 104, 128). La prima forma dà il 15% in più: danno +25,3% (prima +22%), velocità +16,1% (prima +14%).","For every character the forms come at levels 5, 10, 20, 30, 50, 70, 90 and 120 (were 14, 24, 36, 50, 66, 84, 104, 128). The first form gives 15% more: damage +25.3% (was +22%), speed +16.1% (was +14%).")]},
      {g:T('Mappe','Maps'),l:[
        T("Trappole: scattano quando ci cammini sopra (tu o un nemico), avviso 0,22 s e spuntoni 0,38 s (prima un ciclo fisso di 4 s). Colpiscono una volta: 30% della tua Salute massima (prima 7%), 40% di quella di un nemico, 10% di quella di un boss (prima i boss erano immuni).","Traps: they fire when you (or an enemy) step on them, 0.22 s warning and 0.38 s of spikes (was a fixed 4 s cycle). They hit once: 30% of your max HP (was 7%), 40% of an enemy's, 10% of a boss's (bosses used to be immune).")]},
      {g:T('Economia','Economy'),l:[
        T("Tolto il moltiplicatore della ricompensa a fine partita (era ×0,75 in caso di sconfitta).","Removed the end-of-run payout multiplier (it was ×0.75 on a defeat).")]}],
    fix:[
      T("Scrigni e potenziamenti che cadono in acqua non saltano più a riva: galleggiano piano fino alla riva più vicina (con le increspature).","Chests and power-ups that land on the water no longer jump to the shore: they float slowly to the nearest shore (with ripples)."),
      T("I compagni, dopo aver raccolto i cristalli XP, tornano da te camminando invece di teletrasportarsi.","Companions walk back to you after collecting XP crystals instead of teleporting."),
      T("Il cumulo di ossa di Pianeta Vegeta poggia sul terreno; le ombre degli ostacoli dipinti sono calcolate sulla loro base (non sporgono più sotto gli oggetti bassi).","Planet Vegeta's bone pile sits on the ground; the shadows of painted obstacles follow their base (they no longer stick out under low props)."),
      T("Calo di FPS nei tunnel (e dopo): la causa erano le scariche elettriche delle trasformazioni sulle armi (nel tunnel si sale di livello in fretta e la forma resta anche fuori). Ora sono raggruppate e disegnate in un colpo solo per colore, e se il gioco scende sotto ~42 FPS si diradano da sole finché non torna fluido; bagliori e scintille non salvano più lo stato del disegno a ogni chiamata. Nelle prove il disegno dello schermo costa circa la metà (nel tunnel da ~51 a ~26 ms, dopo da ~95 a ~50 ms).","FPS drop in tunnels (and after them): the cause was the transformations' electric arcs on the weapons (in a tunnel you level up fast and the form stays on outside too). They are now grouped and drawn in one go per colour, and when the game falls under ~42 FPS they thin out by themselves until it is smooth again; glows and sparks no longer save the drawing state on every call. In tests a frame costs about half as much to draw (in the tunnel from ~51 to ~26 ms, after it from ~95 to ~50 ms).")]},
  {id:'2026-10-27',date:'2026-10-27',
    name:T("Tempo per il bottino","Loot time"),
    sum:T("Dopo il boss finale hai 30 secondi per raccogliere il bottino prima della schermata di vittoria; la Granata Infernale usa la Quantità per circondare più nemici.","After the final boss you get 30 seconds to collect the loot before the victory screen; the Hellzone Grenade uses Amount to surround more enemies."),
    new:[T("Sconfitto il boss finale, dopo l'esplosione hai 30 secondi per raccogliere scrigni, cristalli e oggetti (il conto alla rovescia è sotto il timer). I nemici non compaiono più finché non scegli la modalità Infinito. Se raccogli tutto prima, la schermata di vittoria si apre subito.","Once the final boss is defeated, after the blast you get 30 seconds to collect chests, gems and items (the countdown is under the timer). No enemies appear until you choose Endless mode. If you pick everything up sooner, the victory screen opens right away.")],
    bal:[T("Granata Infernale: la Quantità ora aggiunge un nemico circondato per punto (con Quantità 2 colpisce 3 gruppi invece di 1) invece di aggiungere una sfera per punto.","Hellzone Grenade: Amount now adds one more surrounded enemy per point (with Amount 2 it hits 3 groups instead of 1) instead of one more sphere per point.")],
    fix:[T("Continuando in modalità Infinito dopo la vittoria non resti più invulnerabile per molti minuti: l'invulnerabilità della scena di vittoria finisce quando riparti (2 secondi di protezione).","Continuing in Endless after the victory no longer leaves you invulnerable for many minutes: the victory-scene invulnerability ends when you resume (2 seconds of protection).")]},
  {id:'2026-10-22f',date:'2026-10-22',
    name:T("Ritmo della partita e late game","Run pacing and late game"),
    sum:T("Miniboss ogni 5 minuti, un élite ogni 4, il tempo extra dopo la fine del livello e un grosso nerf al late game del Torneo del Potere in Estremo.","A miniboss every 5 minutes, an elite every 4, overtime after the end of the stage and a heavy late-game nerf for the Tournament of Power on Extreme."),
    bal:[T("Torneo del Potere (Estremo), late game molto più morbido: dal 35% della partita in poi i nemici scendono in modo graduale fino, a fine partita, a −58% di danni (i colpi dei boss da 220 a 95 con 550 PV; i nemici normali da 112–143 a 31–56), −40% di salute, −45% di frequenza di comparsa e di nemici contemporanei (da 44 a 24 al secondo, da 580 a 319 al massimo). Vale anche per Jiren e il suo scontro finale. Le altre difficoltà non cambiano.","Tournament of Power (Extreme), a much softer late game: from 35% of the run on the enemies ease down gradually, by the end of the run, to −58% damage (boss shots from 220 to 95 with 550 HP; regular enemies from 112–143 to 31–56), −40% health, −45% spawn rate and crowd size (from 44 to 24 per second, from 580 to 319 at most). It applies to Jiren and the final fight too. The other difficulties are unchanged."),
      T("Negozio: Avidità +15% zenny per livello (prima +18%), Vitalità +20 salute massima (prima +15), Rigenerazione +0,5 salute/s (prima +0,6), Ritmo −5% ricarica (prima −4%), Magnetismo +5% raccolta (prima +20%).","Shop: Greed +15% zenny per level (was +18%), Vitality +20 max HP (was +15), Regeneration +0.5 HP/s (was +0.6), Tempo −5% cooldown (was −4%), Magnetism +5% pickup range (was +20%)."),
      T("Fortuna del negozio: +5% per livello invece di +9% (al massimo +30% invece di +54%).","Shop Luck: +5% per level instead of +9% (+30% at most instead of +54%)."),
      T("Nuovi prezzi nel negozio: Urlo di Broly! 500 Zenny il primo livello (prima 666; poi ×1,7 a livello: 850, 1445, 2456, 4176), Scanner Sfere del Drago 10000 (prima 3000; il secondo 30000), Quantità 3000 (prima 2000; il secondo 9000).","New shop prices: Broly's Roar! 500 Zenny for the first level (was 666; then ×1.7 per level: 850, 1445, 2456, 4176), Dragon Ball Scanner 10000 (was 3000; the second 30000), Amount 3000 (was 2000; the second 9000)."),
      T("Vendita dei cimeli ancora −20% (a fine partita in Estremo erano troppi soldi): ora rende il 24% di prima invece del 30%.","Trinket sales −20% again (the end-of-run payout on Extreme was too much money): they now pay 24% of the original value instead of 30%.")],
    new:[
      T("Miniboss: ogni 5 minuti compare un miniboss dove i boss normali lasciano un buco (non sostituisce mai un boss; nel Torneo del Potere, già pieno di boss, non compare quasi mai). È una versione piccola di un boss della mappa: 40% di salute, 80% dei danni, senza trasformazioni. Non conta come boss, ma lascia uno scrigno come un élite, un biglietto 1x, qualche zenny e un po' di esperienza. Sulla barra del tempo è un teschio arancione.","Minibosses: every 5 minutes a miniboss appears wherever the regular bosses leave a gap (it never replaces a boss; in the Tournament of Power, already full of bosses, it almost never shows up). It is a small version of a boss of the map: 40% health, 80% damage, no transformations. It does not count as a boss, but drops a chest like an elite, a 1x ticket, some zenny and a little experience. On the time bar it is an orange skull."),
      T("Élite ogni 4 minuti nelle partite lunghe (30 minuti): il primo a 2:30, poi uno ogni 4 minuti (prima erano 6 concentrati tra il 14% e l'80% della partita).","An elite every 4 minutes on long runs (30 minutes): the first at 2:30, then one every 4 minutes (before it was 6 packed between 14% and 80% of the run)."),
      T("Tempo extra: quando si raggiunge la durata del livello il timer si ferma e accanto compare in rosso il tempo in più (+0:00, +1:30...). Continua a contare anche in modalità Infinito.","Overtime: when the stage length is reached the timer stops and the extra time (+0:00, +1:30...) appears next to it in red. It keeps counting in Endless mode too."),
      T("Il Saibaman compagno ha i nuovi sprite dipinti, come gli altri compagni: fermo con battito di ciglia, camminata, presa del cristallo XP, consegna e Autodistruzione (si carica, si arroventa ed esplode con l'onda d'urto).","The Saibaman companion has new painted sprites, like the other companions: idle with blinks, walking, XP gem pickup, hand-over and Self-Destruct (it charges up, glows red-hot and explodes with the shockwave).")
    ],
    fix:[T("Negozio: tolte le due righe in cima (la descrizione dei potenziamenti permanenti e il costo per comprare tutto / ancora da comprare).","Shop: removed the two lines at the top (the permanent-upgrades description and the cost to buy everything / still to buy)."),
      T("La sfera Genkidama non resta più attiva mentre sei nel Negozio di Zeno: la bomba e le fiamme sono spente finché non esci.","The Genkidama sphere is no longer active while you are in Zeno's Shop: the bomb and the flames are off until you leave."),
      T("Ostacoli e tutto ciò che compare nello stage (casse, trappole, pozze di cura, altari, sfere, nemici e boss) non si sovrappongono più: vengono spostati di poco su un punto libero.","Obstacles and everything that appears on the stage (chests, traps, healing pools, altars, orbs, enemies and bosses) no longer overlap: they are nudged a little to a free spot.")]},
  {id:'2026-10-22e',date:'2026-10-22',
    name:T("Tunnel sotterranei","Underground tunnels"),
    sum:T("Il bunker, il portale e il cancello non compaiono più a caso sulla mappa: ne si apre uno ogni 15 minuti (10 in Infinito) e porta a un tunnel stretto a senso unico, con un boss in fondo e 3 casse.","The bunker, the portal and the gate no longer appear at random on the map: one opens every 15 minutes (10 in Endless) and leads to a narrow one-way tunnel with a boss at the end and 3 chests."),
    new:[
      T("Pianeta Vegeta (bunker), Inferno (portale demoniaco) e Regno degli Dei (cancello celeste) hanno un ingresso speciale: ne compare uno ogni 15 minuti di partita (ogni 10 in modalità Infinito), mai più a caso. Lo sprite è quello del bunker / portale / cancello di prima, con un bagliore e una freccia sul bordo dello schermo con la distanza. Si entra con [E]; non si entra mentre c'è un boss in giro.","Planet Vegeta (bunker), Hell (demon portal) and the Realm of the Gods (heavenly gate) have a special entrance: one appears every 15 minutes of play (every 10 in Endless mode), never at random any more. The sprite is the old bunker / portal / gate, with a glow and an arrow on the screen edge showing the distance. Enter with [E]; you cannot go in while a boss is around."),
      T("Dentro c'è un tunnel stretto (260 px di larghezza) che si percorre in una sola direzione, verso l'alto: il pavimento dietro di te crolla e non si torna indietro (al massimo 240 px). Il tempo della partita, la mappa e gli eventi restano in pausa.","Inside is a narrow tunnel (260 px wide) that goes one way only, upwards: the floor behind you crumbles and there is no way back (240 px at most). The run clock, the map and the events stay paused."),
      T("I nemici compaiono solo nel tunnel, da davanti a te (al massimo 48 vivi). Ogni nemico dà l'esperienza subito (niente cristalli); le monete e i potenziamenti cadono come al solito.","Enemies spawn only inside the tunnel, ahead of you (48 alive at most). Every enemy gives its experience at once (no gems); coins and pick-ups drop as usual."),
      T("In fondo c'è la stanza del boss (600 px di larghezza): un boss del tema della mappa, più forte quanto più sei avanti nella partita. La porta dietro di te si chiude. Il boss non lascia niente: quando cade compaiono 3 casse sui vertici di un triangolo al centro della stanza e un portello verde per tornare in superficie. Se muori nel tunnel la partita finisce come sempre.","At the end is the boss room (600 px wide): a boss of the map's theme, stronger the further you are in the run. The door behind you closes. The boss drops nothing: when it falls, 3 chests appear on the vertices of a triangle in the middle of the room, plus a green hatch back to the surface. If you die in the tunnel the run ends as usual."),
      T("La Stanza dello Spirito e del Tempo e il Negozio di Zeno non sono cambiati.","The Room of Spirit and Time and Zeno's Shop are unchanged.")
    ],
    fix:[T("Torneo del Potere: la torre al centro dell'arena ora sta davanti al personaggio; se ti trovi dietro la torre non ti si vede più attraverso di essa.","Tournament of Power: the tower in the middle of the arena is now in front of the character; if you stand behind it you can no longer be seen through it.")]},
  {id:'2026-10-22d',date:'2026-10-22',
    name:T("Compagni illustrati","Illustrated companions"),
    sum:T("Dende, Mini Shenron, Mini Droid, Bubbles e Mini Bu hanno nuovi sprite dipinti, con animazioni per riposo, camminata, raccolta degli XP, consegna, abilità e onda d'urto.","Dende, Mini Shenron, Mini Droid, Bubbles and Mini Bu have new painted sprites, with animations for idle, walking, XP pickup, hand-over, ability and shockwave."),
    bal:[T("Vendita dei cimeli −70%: ogni cimelio venduto (sostituito, rifiutato o a fine partita) rende il 30% di prima.","Trinket sales −70%: every trinket sold (replaced, refused or at the end of the run) now pays 30% of what it did."),
      T("Danni dei nemici in Difficile e Estremo −30% (moltiplicatore da 1,5 a 1,05 e da 1,8 a 1,26).","Enemy damage on Hard and Extreme −30% (multiplier from 1.5 to 1.05 and from 1.8 to 1.26).")],
    new:[
      T("Nuovi sprite per 5 compagni (il Saibaman resta quello di prima): fermo con battito di ciglia, camminata a 6 frame, presa del cristallo XP, consegna a te, abilità e onda d'urto (quando 5 nemici ti circondano). Anche le card di scelta del compagno usano i nuovi sprite.","New sprites for 5 companions (the Saibaman stays as before): idle with blinking, a 6-frame walk, grabbing the XP gem, handing it over to you, the ability and the shockwave (when 5 enemies surround you). The companion cards in the selection screen use the new sprites too.")
    ]},
  {id:'2026-10-22c',date:'2026-10-22',
    name:T("Mappa nel menu di pausa","Map in the pause menu"),
    sum:T("Premendo ESC trovi una scheda Mappa, grande e con zoom, che mostra dove sono i pickup; le statistiche del personaggio restano a sinistra.","Pressing ESC now has a big Map tab with zoom that shows where the pickups are; the character's stats stay on the left."),
    fix:[T("Le trappole e le pozze di cura non sembrano più appoggiate sopra il terreno: ora sono incassate nel pavimento (si vede solo il piano superiore, senza ombra; spuntoni e fiamme escono ancora verso l'alto).","Traps and healing pools no longer look like they sit on top of the ground: they are now sunk into the floor (only the top face shows, no shadow; spikes and flames still rise upward).")],
    new:[
      T("Nuova scheda «Mappa» nel menu di pausa, a sinistra di «Partita», aperta di default (puoi cambiarlo in Impostazioni > Gioco > «Scheda iniziale della pausa»: Mappa, Partita o Ultima usata).","New «Map» tab in the pause menu, left of «Run», open by default (you can change it in Settings > Gameplay > «Pause menu opens on»: Map, Run or Last used)."),
      T("La mappa è centrata su di te e mostra con le loro icone (le stesse del gioco, rimpicciolite) oggetti a terra, Sfere del Drago, forzieri colorati per rarità, altari, Totem, Stanza dello Spirito e del Tempo, bottone rosso, zone di cura e la gemma rossa. Il riquadro tratteggiato è ciò che vede lo schermo; anelli e griglia indicano le distanze (1 m = 10 px). Nei mondi chiusi si vedono i confini (arena del Torneo del Potere, corpo del Serpente).","The map is centred on you and shows, with the game's own icons shrunk, items on the ground, Dragon Balls, chests coloured by rarity, altars, Totems, the Room of Spirit and Time, the red button, healing zones and the red gem. The dashed box is what the screen shows; rings and grid mark distances (1 m = 10 px). Closed worlds show their limits (Tournament of Power arena, the Snake's body)."),
      T("Zoom con i bottoni + e − in basso a sinistra della mappa (7 livelli).","Zoom with the + and − buttons at the map's bottom-left (7 levels)."),
      T("La scheda Mappa occupa tutto lo schermo, subito in cima: una sola riga con le schede e i pulsanti, la mappa grande al centro e a sinistra solo un piccolo pannello con le statistiche.","The Map tab fills the screen, right at the top: a single row with the tabs and buttons, the big map in the middle and only a small stats panel on the left."),
      T("La scheda Partita ora sta tutta nello schermo, senza scorrimento: statistiche, abilità, potenziamenti, armi, cimeli e desideri si dispongono in colonne e l'insieme si rimpicciolisce da solo quanto serve (fino al 40%) per entrare sopra l'interfaccia di gioco. Con più o meno armi, cimeli o potenziamenti le finestre si riadattano; in alto c'è una sola riga con schede e pulsanti, come nella Mappa.","The Run tab now fits on the screen with no scrolling: stats, abilities, upgrades, weapons, trinkets and wishes flow into columns and the whole thing shrinks by itself as much as needed (down to 40%) to sit above the game interface. With more or fewer weapons, trinkets or upgrades the windows reshape; at the top there is a single row with tabs and buttons, like the Map.")
    ]},
  {id:'2026-10-22b',date:'2026-10-22',
    name:T("Serie più nervosa, orde, totem e altari con [E]","Tougher streak, hordes, totems and altars with [E]"),
    sum:T("La barra della serie si svuota sempre più in fretta, le orde accelerano le comparse, il Totem della Ricchezza dura 150 s, tutti gli altari si usano con [E] e spariscono con un'animazione; trappole e zone di cura sono molto più rare.","The streak bar empties faster and faster, hordes speed up spawns, the Totem of Wealth lasts 150 s, every altar is used with [E] and vanishes with an animation; traps and healing zones are much rarer."),
    new:[
      T("Stanza dello Spirito e del Tempo: lo sprite sulla mappa è ingrandito del 50%. Dentro, le card si scelgono anche con i tasti numerici 1-9 (il numero è sul fondo della card; se non hai abbastanza Zenny suona l'errore).","Room of Spirit and Time: its sprite on the map is 50% bigger. Inside, the cards can also be picked with the number keys 1-9 (the number is at the bottom of the card; with too little Zenny the error sound plays)."),
      T("Altare del Potere, Sorgente curativa, Fonte dell'esperienza, Altare del sacrificio, Totem, Stanza e portale di Zeno-sama: tutti si attivano premendo [E] vicino (prima Altare del Potere, Sorgente, Fonte e portale scattavano al tatto), con la scritta di richiamo. Dopo l'uso brillano e si scuotono, poi salgono un po' e si dissolvono in scintille (1,2 s).","Altar of Power, Healing spring, Experience font, Sacrifice altar, Totem, the Room and Zeno-sama's portal: all are used by pressing [E] close by (the Altar of Power, Spring, Font and portal used to trigger on touch), with the prompt text. After use they flash and shake, then rise a little and dissolve into sparkles (1.2 s).")
      ,T("Altare del Potere, Fonte dell'esperienza, Totem e Sorgente curativa hanno la loro animazione di sparizione disegnata (5-6 fotogrammi: lampo, picco di luce, dissolvenza in particelle). Gli altri elementi (altare del sacrificio, bottone rosso, portale) mantengono per ora l'effetto semplice.","Altar of Power, Experience font, Totem and Healing spring have their own painted vanishing animation (5-6 frames: flash, light peak, dissolve into particles). The other elements (sacrifice altar, red button, portal) keep the simple effect for now.")
      ,T("Altare del sacrificio e bottone rosso hanno i loro disegni: il cristallo si frantuma in schegge e il bottone si abbassa con un lampo e resta premuto. Nuovo effetto sonoro 8-bit di cristallo che si rompe quando consumi l'altare del sacrificio.","Sacrifice altar and red button have their own artwork: the crystal shatters into shards and the button goes down with a flash and stays pressed. New 8-bit crystal-breaking sound effect when you use the sacrifice altar.")
      ,T("Trappole e zone di cura hanno finalmente i loro disegni: la trappola passa da quiete a crepe incandescenti (avviso) a punte che escono, la pozza di cura brilla e, quando ci sei dentro e ti curi, sprigiona scintille verdi.","Traps and healing zones finally have their own artwork: the trap goes from resting to glowing cracks (warning) to spikes shooting up, and the healing pool glows and, while you stand in it and heal, bursts with green sparkles.")
    ],
    bal:[
      T("Serie di uccisioni: il tempo per mantenerla non è più fisso a 4 s ma scende con le uccisioni, in modo esponenziale: 4 s a 0, 3,4 s a 100, 1,7 s a 500, 0,7 s a 1000, 0,3 s da 1500 in poi. Ogni uccisione riempie di nuovo la barra, ma sulla durata del momento.","Kill streak: the time to keep it going is no longer a fixed 4 s but drops with the kills, exponentially: 4 s at 0, 3.4 s at 100, 1.7 s at 500, 0.7 s at 1000, 0.3 s from 1500 on. Every kill refills the bar, but to the length of the moment."),
      T("Altari e Totem: ogni 30 secondi ogni altare (Potere, Sorgente, sacrificio, Fonte) ha il 4% di comparire, se la situazione lo giustifica come prima (massimo 2 sulla mappa), quindi può uscirne più d'uno per partita. Il Totem non è più garantito una volta a partita: ogni 30 secondi ha l'1,5% (circa 0,3 in 10 minuti; trovarne due in 10 minuti capita nel 4% dei casi).","Altars and Totems: every 30 seconds each altar (Power, Spring, Sacrifice, Font) has a 4% chance to appear, under the same conditions as before (at most 2 on the map), so more than one can show up per run. The Totem is no longer guaranteed once per run: every 30 seconds it has a 1.5% chance (about 0.3 per 10 minutes; finding two in 10 minutes happens in 4% of runs)."),
      T("Orde: oltre al gruppo che arriva, per 20 secondi i nemici normali compaiono 2,5 volte più in fretta (nessun avviso).","Hordes: besides the group that arrives, for 20 seconds regular enemies spawn 2.5 times faster (no notice)."),
      T("Totem della Ricchezza: non è più permanente, dura 150 secondi (poi +35% Zenny e +25% raccolta svaniscono; il tempo residuo è accanto al nome del Totem).","Totem of Wealth: no longer permanent, it lasts 150 seconds (then +35% Zenny and +25% pickup range fade; the time left is next to the Totem's name)."),
      T("Trappole e zone di cura sul terreno molto più rare: le zone con una trappola o una pozza passano dal 20% al 4,5% delle celle; le zone di cura dal 6% allo 0,8% (7 volte più rare).","Traps and healing zones on the ground are much rarer: cells holding a trap or pool go from 20% to 4.5%; healing zones from 6% to 0.8% (7 times rarer).")
    ]},
  {id:'2026-10-22',date:'2026-10-22',
    name:T("Forzieri illustrati con animazione di apertura","Illustrated chests with an opening animation"),
    sum:T("I forzieri a terra ora sono disegni, uno stile per ogni rarità, e quando li tocchi si scuotono, aprono il coperchio e sprigionano luce prima della finestra dei premi.","Chests on the ground are now illustrated, one style per rarity, and when you touch one it shakes, lifts its lid and bursts with light before the reward window."),
    new:[
      T("Forzieri illustrati: Comune in legno e ferro, Raro blu, Epico viola, Leggendario dorato con ali, Mitico a cristalli rosa. Il Mitico e il Leggendario restano i più grandi, e quelli da élite (×1,2) e da boss finale (×1,5) sono più grossi.","Illustrated chests: Common in wood and iron, Rare blue, Epic purple, Legendary golden with wings, Mythic pink crystal. Mythic and Legendary stay the biggest, and elite (x1.2) and final boss (x1.5) chests are larger."),
      T("Animazione di apertura: appena li tocchi il forziere trema, il coperchio si alza e un fascio di raggi nel colore della rarità esce dall'interno (circa 0,85 s); poi si apre la finestra dei premi e il forziere sparisce. Il forziere che si sta aprendo non compare più nella freccia di ricerca.","Opening animation: as soon as you touch it the chest shakes, the lid lifts and a burst of rays in the rarity colour comes out (about 0.85 s); then the reward window opens and the chest disappears. A chest that is opening no longer shows in the pointer arrow.")
    ]},
  {id:'2026-10-21p',date:'2026-10-21',
    name:T("Estremo più giocabile all'inizio e meno duro alla fine","Extreme: gentler start, slightly softer endgame"),
    sum:T("In Estremo i nemici normali partono molto più deboli e tornano ai valori di prima a metà stage; a fine stage sono un po' più deboli di prima. Nell'x2 l'esperienza è più alta.","In Extreme regular enemies start much weaker and are back to the old values by mid-stage; at the end of the stage they are a little weaker than before. In x2 experience is higher."),
    bal:[
      T("Estremo (anche con x2), inizio: Salute dei nemici normali ×0,30 e danno ×0,55 a inizio stage, che risalgono a ×1 al 65% (Salute) e al 50% (danno) della durata. Esempio, Torneo del Potere in Estremo x2: il Guerriero Eliminato parte con 264 di Salute (prima 881) e colpisce per 33 (prima 59); al 15% dello stage ha 525 di Salute (prima 1.389). I boss non cambiano.","Extreme (x2 too), start: regular enemies' health x0.30 and damage x0.55 at the start of the stage, rising back to x1 at 65% (health) and 50% (damage) of its length. Example, Tournament of Power in Extreme x2: the Eliminated Fighter starts with 264 health (it was 881) and hits for 33 (it was 59); at 15% of the stage it has 525 health (it was 1,389). Bosses are unchanged."),
      T("Estremo, fine stage: dal 65% della durata i nemici normali calano piano piano fino a Salute −12% e danno −10% alla fine.","Extreme, end of the stage: from 65% of its length regular enemies ease down to −12% health and −10% damage at the end."),
      T("Modalità x2: l'esperienza passa da ×0,18 a ×0,30 (prima 5,6 volte meno del normale, ora 3,3).","x2 mode: experience goes from x0.18 to x0.30 (it was 5.6 times less than normal, now 3.3)."),
    ]},
  {id:'2026-10-21o',date:'2026-10-21',
    name:T("Modalità test riservata e Dati di gioco nascosti","Test mode restricted, Game data hidden"),
    sum:T("La modalità test esiste solo per l'account del proprietario e per quelli autorizzati; «Dati di gioco» compare solo con la modalità test accesa, ma la registrazione continua in background.","Test mode exists only for the owner's account and the allowed ones; \"Game data\" only shows with Test mode on, but recording goes on in the background."),
    new:[
      T("Modalità test (Impostazioni > Generale): compare solo se hai fatto il login con l'account del proprietario o con uno autorizzato. Per gli altri non c'è, e se era accesa si spegne (gli acquisti fatti in test vengono annullati come quando la spegni a mano).","Test mode (Settings > General): it only shows if you are signed in with the owner's account or an allowed one. For anybody else it is not there, and if it was on it switches off (purchases made in test are reverted like when you turn it off by hand)."),
      T("Giocatori autorizzati: con la modalità test accesa, il proprietario trova in Impostazioni > Generale un menu a tendina con l'elenco, il pulsante «Rimuovi» e un campo per aggiungere un giocatore dal suo indirizzo e-mail. L'indirizzo del proprietario e un elenco fisso stanno in tester.config.json, escluso dal repository (.gitignore); nella pagina ne resta solo un'impronta.","Allowed players: with Test mode on, the owner finds in Settings > General a drop-down with the list, a \"Remove\" button and a field to add a player by e-mail address. The owner's address and a fixed list live in tester.config.json, left out of the repository (.gitignore); the page only keeps a fingerprint of them."),
      T("Dati di gioco (Impostazioni > Gameplay): la voce compare solo con la modalità test accesa. Le partite si registrano comunque in background su questo dispositivo, a meno che tu non spenga l'interruttore mentre la modalità test è accesa.","Game data (Settings > Gameplay): the entry only shows with Test mode on. Runs are recorded in the background on this device anyway, unless you turn the switch off while Test mode is on."),
    ],
    fix:[
      T("Avvio rapido: i cimeli sotto il personaggio sono più piccoli (52 px invece di 70) e non escono più dalla scheda.","Quick Start: the trinkets under the character are smaller (52 px instead of 70) and no longer spill out of the card.")
    ]},
  {id:'2026-10-21n',date:'2026-10-21',
    name:T("Salire di livello non allarga più la raccolta","Levelling up no longer widens your pickup range"),
    sum:T("Lo Scouter non allarga più il raggio di raccolta: resta solo come requisito di evoluzione di alcune armi.","The Scouter no longer widens your pickup range: it stays only as an evolution requirement for some weapons."),
    bal:[
      T("Scouter (potenziamento al level-up): non dà più +35% di raccolta per livello. Il raggio di raccolta ora dipende solo da personaggio, Magnetismo (negozio), cimeli, Senzu, Totem e dall'oggetto Magnete. Lo Scouter resta tra i potenziamenti perché serve per far evolvere Disco Distruttore, Taiyoken, Colpi Eccentrici, Boomerang Ginyu e Fulmine Angelico.","Scouter (level-up upgrade): no longer gives +35% pickup range per level. Pickup range now depends only on the character, Magnetism (shop), trinkets, Senzu, Totems and the Magnet pickup. The Scouter stays among the upgrades because it is needed to evolve Destructo Disc, Solar Flare, Homing Orbs, Ginyu Boomerang and Angelic Bolt.")
    ]},
  {id:'2026-10-21m',date:'2026-10-21',
    name:T("Forzieri di cinque rarità e premio finale senza moltiplicatore","Five-rarity chests and no end-of-run multiplier"),
    sum:T("I forzieri di boss ed élite hanno una rarità che decide quanto contengono; il premio in zenny a fine partita non ha più moltiplicatori.","Boss and elite chests have a rarity that decides what is inside; the end-of-run zenny payout no longer has multipliers."),
    new:[
      {g:T("Forzieri","Chests"),l:[
        T("Ogni forziere ha una rarità, tirata quando compare: Comune 40%, Raro 39%, Epico 15%, Leggendario 5%, Mitico 1%. Il colore del forziere, il bagliore e le scintille sono quelli della rarità; da Leggendario in su parte anche una colonna di luce. La rarità si legge anche nel titolo della finestra di apertura.","Every chest has a rarity, rolled when it appears: Common 40%, Rare 39%, Epic 15%, Legendary 5%, Mythic 1%. The chest colour, glow and sparks are the rarity's; from Legendary up a pillar of light shows too. The rarity is also in the title of the opening window."),
        T("Contenuto, sempre lo stesso per rarità: +1 livello a un'arma (o l'evoluzione, se è pronta) e, dal Raro in su, dei cimeli. Comune: nessun cimelio. Raro: 2. Epico: 3. Leggendario: 4. Mitico: 5. Le scelte fra 4 cimeli e i potenziamenti dei forzieri non ci sono più.","Contents, always the same for a rarity: +1 level to a weapon (or the evolution, if it is ready) and, from Rare up, trinkets. Common: no trinket. Rare: 2. Epic: 3. Legendary: 4. Mythic: 5. The pick among 4 trinkets and the upgrades are no longer in chests."),
        T("Un cimelio garantito della rarità del forziere: il forziere Raro contiene sempre 1 cimelio Raro, l'Epico 1 Epico, il Leggendario 1 Leggendario e il Mitico 1 Mitico (gli altri sono casuali). Nel forziere Mitico le probabilità di un'alta Perfezione per i cimeli Mitici sono +20%.","One guaranteed trinket of the chest's rarity: the Rare chest always holds 1 Rare trinket, the Epic one 1 Epic, the Legendary one 1 Legendary and the Mythic one 1 Mythic (the others are random). In the Mythic chest the odds of a high Perfection for Mythic trinkets are +20%."),
        T("A fine corsa, con ogni arma al massimo e nessuna evoluzione pronta, il livello dell'arma è sostituito da un cimelio in più (prima: 40 zenny).","Once everything is maxed (every weapon at the top and no evolution ready), the weapon level is replaced by one more trinket (it was 40 zenny)."),
        T("La Fortuna sposta le probabilità verso le rarità alte (con il 50% di Fortuna: Comune 22%, Raro 44%, Epico 22%, Leggendario 10%, Mitico 3%).","Luck shifts the odds toward the high rarities (at 50% Luck: Common 22%, Rare 44%, Epic 22%, Legendary 10%, Mythic 3%)."),
        T("I forzieri compaiono quando sconfiggi un boss o un'élite (e restano quelli a tempo ogni 5 minuti).","Chests appear when you defeat a boss or an elite (and the timed one every 5 minutes stays)."),
      ]},
      {g:T("Economia","Economy"),l:[
        T("Premio finale: tolto il moltiplicatore (prima stage × difficoltà × buff Monete). Ora si incassa la somma delle voci; solo la sconfitta paga il 25% in meno. Dalla scheda dello stage è sparita la riga «Zenny ×».","End-of-run payout: the multiplier is gone (it was stage x difficulty x Coin buffs). You now get the sum of the lines; only a defeat pays 25% less. The \"Zenny x\" line is gone from the stage card."),
      ]}
    ]},
  {id:'2026-10-21l',date:'2026-10-21',
    name:T("Strutture di gioco ridisegnate","Redrawn in-game structures"),
    sum:T("Le 8 strutture che compaiono in partita hanno una grafica nuova, più grande e dettagliata.","The 8 structures that appear in a run have new, bigger and more detailed art."),
    fix:[
      T("Suono del level up: volume abbassato (da 0,9 a 0,4).","Level-up sound: volume lowered (from 0.9 to 0.4)."),
      T("Torneo del Potere: i cali di FPS sono risolti. Il pavimento dell'arena veniva ridisegnato a ogni fotogramma (circa 14 ms); ora è disegnato una volta in tessere e riusato (circa 0,4 ms).","Tournament of Power: the FPS drops are fixed. The arena floor was repainted every frame (about 14 ms); it is now painted once in tiles and reused (about 0.4 ms)."),
    ],
    new:[
      {g:T("Mappe","Maps"),l:[
        T("Nuova grafica per Altare del Potere, Fonte dell'esperienza, Totem, Sorgente curativa, Altare del sacrificio, Stanza dello Spirito e del Tempo, Altare con il pulsante rosso e Portale di Zeno-sama. Misurano 100-165 px di larghezza (prima circa 40-45).","New art for the Power Shrine, Experience Font, Totem, Healing Spring, Sacrifice Altar, Room of Spirit and Time, red-button Altar and Zeno-sama's Portal. They are 100-165 px wide (they were about 40-45)."),
        T("Il pulsante rosso, una volta premuto, perde il punto interrogativo e diventa più scuro; il portale di Zeno e la Stanza respirano piano; ogni struttura ha un leggero bagliore del suo colore.","Once pressed, the red button loses its question mark and turns darker; Zeno's portal and the Room breathe slowly; each structure has a soft glow in its colour."),
      ]}
    ]},
  {id:'2026-10-21k',date:'2026-10-21',
    name:T("Torneo del Potere: arena chiusa","Tournament of Power: a closed arena"),
    sum:T("Il Torneo del Potere si combatte ora su un'unica arena circolare con la torre al centro: niente compare fuori dal bordo.","The Tournament of Power is now fought on a single circular arena with a tower in the middle: nothing appears outside its edge."),
    new:[
      {g:T("Mappe","Maps"),l:[
        T("Torneo del Potere: nuova mappa, l'arena circolare a fasce concentriche (triangoli, blocchi blu e arancio, strisce) con il bordo spesso, un alone verde acqua e lo spazio con nebulose viola e verdi intorno. Misura 4800 × 4000 px (circa 5 schermate di larghezza).","Tournament of Power: new map, the circular arena of concentric bands (triangles, blue and orange blocks, stripes) with a thick rim, a teal halo and space with purple and green nebulae around it. It measures 4800 x 4000 px (about 5 screens wide)."),
        T("Torre al centro (alta 430 px, i piedi occupano 100 px): è solida, copre chi le sta dietro e proietta un'ombra lunga verso l'alto a destra, sempre visibile sul pavimento. Si parte davanti alla torre.","Tower in the centre (430 px tall, 100 px foot): it is solid, hides whoever stands behind it and casts a long shadow to the upper right, always visible on the floor. You start in front of the tower."),
        T("Selezione stage: la scheda del Torneo del Potere mostra l'anteprima animata della nuova arena, con la torre e la sua ombra.","Stage select: the Tournament of Power card shows an animated preview of the new arena, with the tower and its shadow."),
        T("Rimossi i 4 ostacoli sparsi (colonna, lastra, piedistallo, cristallo): l'arena è pulita, resta solo la torre al centro. Pozze di cura e trappole a terra ci sono ancora.","Removed the 4 scattered props (column, slab, pedestal, crystal): the arena is clean, only the tower in the middle remains. Healing pools and floor traps are still there."),
        T("Nulla esiste fuori dal cerchio: tu, i nemici (anche volanti e boss), le gemme, i premi, i forzieri e le trappole restano dentro il bordo. I nemici compaiono sul bordo dello schermo scegliendo la direzione più vicina che cade dentro l'arena.","Nothing exists outside the circle: you, enemies (flyers and bosses too), gems, drops, chests and traps all stay inside the edge. Enemies appear at the edge of the screen, picking the nearest direction that lands inside the arena."),
      ]}
    ]},
  {id:'2026-10-21j',date:'2026-10-21',
    name:T("Ostacoli nuovi sulle altre mappe e barili più bassi","New props on the other maps and shorter barrels"),
    sum:T("Pianura Saiyan, Regno degli Dei, Inferno e Pianeta Namek hanno la grafica degli ostacoli rifatta, più grande e meno fitta; i barili ora sono poco più bassi di Goku.","Saiyan Plains, Realm of the Gods, Hell and Planet Namek have redrawn, bigger and sparser props; barrels are now a little shorter than Goku."),
    new:[
      {g:T("Mappe","Maps"),l:[
        T("Pianura Saiyan: nuova grafica per tutti i 9 ostacoli (albero, scalini di pietra, santuario a piramide, casetta con il camino-antenna che fuma, muro di pietra, balla di fieno, recinto, cartello, cassa). Il gatto sulla balla, gli uccelli sul recinto e i ragni sulla cassa restano.","Saiyan Plains: new art for all 9 props (tree, stone steps, pyramid shrine, little house with a smoking antenna chimney, stone wall, haybale, fence, sign, crate). The cat on the haybale, the birds on the fence and the spiders on the crate are still there."),
        T("Regno degli Dei: nuova grafica per i 5 ostacoli e 3 in più (ora 8): pilastro di marmo con le venature verdi, trono su nuvola, piedistallo con il pianeta (brilla), tempio-portale (il portale brilla), lanterna cosmica, bastone della guardia, trono di Zeno e sfera cosmica; la sfera e la nuvola fluttuano.","Realm of the Gods: new art for the 5 props and 3 more (now 8): marble pillar with green veins, throne on a cloud, pedestal with a glowing planet, temple gate (the portal glows), cosmic lantern, guard staff, Zeno's throne and cosmic orb; the orb and the cloud float."),
        T("Inferno: nuova grafica per i 5 ostacoli e 5 in più (ora 10, più le 4 rocce che non cambiano): torre di ossa con le finestre accese, teschio gigante, cancello a punte, mucchio di teschi, lapide del demone, portale demoniaco (il vortice brilla), torcia infernale (fiamma viola con faville), radici spinose, statua del demone e cristallo rosso (brilla).","Hell: new art for the 5 props and 5 more (now 10, plus the 4 rocks that do not change): bone tower with lit windows, giant skull, spiked gate, skull pile, demon gravestone, demon portal (the swirl glows), infernal torch (purple flame with sparks), thorny roots, demon statue and red crystal (it glows)."),
        T("Pianeta Namek: nuova grafica per l'albero a spirale, l'astronave (grande come una casa: circa 440 px di larghezza, prima 155) e il cristallo azzurro; le tre rocce non cambiano. Il cristallo continua a luccicare.","Planet Namek: new art for the spiral tree, the ship (house-sized: about 440 px wide, it was 155) and the blue crystal; the three rocks do not change. The crystal still sparkles."),
        T("Barili ridotti su tutte le mappe che ne hanno (Isola di Muten, Pianeta Vegeta, Rovine degli Androidi, Arena dei Cell Game): ora alti 78 px, poco meno di Goku (87 px); prima 105-127 px.","Barrels shrunk on every map that has them (Roshi's Island, Planet Vegeta, Android Ruins, Cell Games Arena): now 78 px tall, a little less than Goku (87 px); they were 105-127 px."),
        T("Ostacoli meno fitti: Pianura Saiyan 12% delle zone (prima 17%), Regno degli Dei 10% (prima 15%), Inferno 12% (prima 18%), Pianeta Namek 12% (prima 15%).","Fewer props: Saiyan Plains fills 12% of the map cells (it was 17%), Realm of the Gods 10% (it was 15%), Hell 12% (it was 18%), Planet Namek 12% (it was 15%)."),
        T("Probabilità di comparsa (su 100 ostacoli). Pianura: albero 33, scalini 19, balla 11, recinto 9, muro 8, cassa 8, cartello 5, piramide 4, casetta 3. Regno degli Dei: pilastro 22, trono su nuvola 22, piedistallo 15, lanterna 11, bastone 11, sfera 11, tempio 4, trono di Zeno 4. Inferno: rocce 36 in tutto, torre 14, cancello 10, torcia 7, radici 7, teschi 7, cristallo 6, lapide 5, statua 4, teschio gigante 3, portale 2. Namek: albero 36, rocce 48 in tutto, cristallo 13, astronave 4.","Chance of appearing (out of 100 props). Plains: tree 33, steps 19, haybale 11, fence 9, wall 8, crate 8, sign 5, pyramid 4, house 3. Realm of the Gods: pillar 22, cloud throne 22, pedestal 15, lantern 11, staff 11, orb 11, gate 4, Zeno's throne 4. Hell: rocks 36 in all, tower 14, gate 10, torch 7, roots 7, skulls 7, crystal 6, gravestone 5, statue 4, giant skull 3, portal 2. Namek: tree 36, rocks 48 in all, crystal 13, ship 4."),
      ]},
    ],
  },
  {id:'2026-10-21i',date:'2026-10-21',
    name:T("Ostacoli nuovi su quattro mappe","New props on four maps"),
    sum:T("Pianeta Vegeta, Rovine degli Androidi, Dimensione di Bu e Arena dei Cell Game hanno la grafica degli ostacoli rifatta, più grande e meno fitta; la Kame House ora è una vera casa.","Planet Vegeta, Android Ruins, Buu's Dimension and the Cell Games Arena have redrawn, bigger and sparser props; the Kame House is now a proper house."),
    new:[
      {g:T("Mappe","Maps"),l:[
        T("Pianeta Vegeta: nuova grafica per tutti i 9 ostacoli (altipiano, guglia, capsula Saiyan con la finestra rossa che brilla, bunker, secondo altipiano, cactus, mucchio d'ossa, barile, cassa). Il bunker è una vera costruzione.","Planet Vegeta: new art for all 9 props (plateau, spire, Saiyan pod with a glowing red window, bunker, second plateau, cactus, bone pile, barrel, crate). The bunker is a real building."),
        T("Rovine degli Androidi: nuova grafica per tutti i 10 ostacoli (cassa, barile, lapide, teschi, cactus, auto arrugginita, colonna di cemento, rovina, palo, blocchi di cemento). La cassa non fuma più.","Android Ruins: new art for all 10 props (crate, barrel, gravestone, skulls, cactus, rusty car, concrete column, ruin, pole, concrete blocks). The crate no longer smokes."),
        T("Dimensione di Bu: nuova grafica e 6 ostacoli in più (ora 10): pilastro, palloncini, cupola grande come una casa, lanterna, goccia di melma, massa di melma, due grappoli di melma, pozza e geyser di melma (il geyser sbuffa bollicine).","Buu's Dimension: new art and 6 more props (now 10): pillar, balloons, a house-sized dome, lantern, slime drop, slime mass, two slime clusters, puddle and slime geyser (the geyser puffs bubbles)."),
        T("Arena dei Cell Game: nuova grafica per i 9 ostacoli e 2 nuovi (ora 11): il ring dei Cell Game, enorme (900 px di larghezza, un pavimento sotto a tutto: ci si cammina sopra, non blocca), e una cisterna. La torre è alta il doppio di prima.","Cell Games Arena: new art for the 9 props and 2 new ones (now 11): the Cell Games ring, huge (900 px wide, a floor under everything: you walk over it, it never blocks), and a tank. The tower is twice as tall as before."),
        T("Kame House (Isola di Muten): ora è alta 237 px e larga 313 (prima 107 × 142), quanto una vera casa accanto a Goku; la cupola di Bu, il bunker e la torre dell'Arena sono ingranditi allo stesso modo. Compare nel 2% degli ostacoli (prima 1%).","Kame House (Roshi's Island): it is now 237 px tall and 313 wide (it was 107 × 142), the size of a real house next to Goku; Buu's dome, the bunker and the Arena tower are enlarged the same way. It appears in 2% of the props (it was 1%)."),
        T("Ostacoli meno fitti: Pianeta Vegeta 12% delle zone (prima 19%), Rovine degli Androidi 12% (prima 20%), Dimensione di Bu 10% (prima 15%), Arena dei Cell Game 10% (prima 17%).","Fewer props: Planet Vegeta fills 12% of the map cells (it was 19%), Android Ruins 12% (it was 20%), Buu's Dimension 10% (it was 15%), Cell Games Arena 10% (it was 17%)."),
        T("Probabilità di comparsa (su 100 ostacoli). Vegeta: altipiano 29, guglia 22, cactus 16, ossa 7, barile 7, cassa 7, secondo altipiano 6, capsula 3, bunker 3. Androidi: cassa 14, barile 14, cactus 12, auto 10, lapide 10, teschi 10, colonna 8, rovina 8, palo 7, blocchi 7. Bu: pilastro 20, goccia 14, palloncini 14, massa 10, pozza 10, lanterna 8, grappoli 8+8, geyser 5, cupola 2. Arena: lastra 20, pilastro 13, seconda lastra 13, colonna 11, scalinata 8, barile 8, stendardo 8, cassa 8, torre 4, ring 4, cisterna 3.","Chance of appearing (out of 100 props). Vegeta: plateau 29, spire 22, cactus 16, bones 7, barrel 7, crate 7, second plateau 6, pod 3, bunker 3. Androids: crate 14, barrel 14, cactus 12, car 10, gravestone 10, skulls 10, column 8, ruin 8, pole 7, blocks 7. Buu: pillar 20, drop 14, balloons 14, mass 10, puddle 10, lantern 8, clusters 8+8, geyser 5, dome 2. Arena: slab 20, pillar 13, second slab 13, column 11, steps 8, barrel 8, banner 8, crate 8, tower 4, ring 4, tank 3."),
      ]},
    ],
  },
  {id:'2026-10-21h',date:'2026-10-21',
    name:T("Ostacoli nuovi all'Isola di Muten","New props on Roshi's Island"),
    sum:T("Gli ostacoli dell'Isola di Muten hanno la grafica rifatta e sono meno fitti; ognuno ha la sua probabilità di comparire.","Roshi's Island props have redrawn art and are less crowded; each one has its own chance to appear."),
    new:[
      {g:T("Mappe","Maps"),l:[
        T("Isola di Muten: nuova grafica per tutti i 12 ostacoli (palma, panchina, Kame House, cespuglio fiorito, scalinata, cassa, due casse impilate, barile, due lapidi, agave, mucchio di rocce). La palma continua a ondeggiare col vento; ragni, corvi, granchi e candele restano sugli oggetti.","Roshi's Island: new art for all 12 props (palm, bench, Kame House, flowering bush, stairs, crate, stacked crates, barrel, two gravestones, agave, rock pile). The palm still sways in the wind; spiders, crows, crabs and candles are still on the props."),
        T("Ostacoli meno fitti sull'Isola di Muten: occupano il 14% delle zone (prima 24%).","Fewer props on Roshi's Island: they fill 14% of the map cells (it was 24%)."),
        T("Probabilità di comparsa (su 100 ostacoli): palma 29, agave 15, cespuglio 15, cassa 7, barile 7, mucchio di rocce 7, panchina 6, scalinata 4, cassa doppia 4, lapide con croce 3, lapide «EROSO» 1,5, Kame House 1.","Chance of appearing (out of 100 props): palm 29, agave 15, bush 15, crate 7, barrel 7, rock pile 7, bench 6, stairs 4, stacked crates 4, cross gravestone 3, «EROSO» gravestone 1.5, Kame House 1."),
        T("La scritta della Kame House e della lapide «EROSO» non viene più specchiata.","The lettering on the Kame House and the «EROSO» gravestone is no longer mirrored."),
      ]},
    ],
  },
  {id:'2026-10-21g',date:'2026-10-21',
    name:T("Morte dei nemici, cimeli e musica dei boss","Enemy deaths, trinkets and boss music"),
    sum:T("I nemici uccisi si dissolvono e i boss lasciano un'onda d'urto; i cimeli che porti fino alla fine finiscono nella Borsa (e la perfezione al 100% è più rara); i power-up a terra vengono attirati dal raggio di raccolta; i boss non finali hanno la loro musica.","Killed enemies dissolve and bosses leave a shock wave; the trinkets you carry to the end go into the Bag (and a perfect 100% is rarer); ground power-ups are pulled in by your pick-up range; non-final bosses have their own music."),
    new:[
      {g:T("Combattimento","Combat"),l:[
        T("Ogni nemico ucciso si dissolve: lampo bianco, poi i pixel svaniscono con il bordo che brucia di bianco e il corpo che sale e si allontana dal colpo, con scintille del suo colore. Non c'è con «Riduci effetti» attivo.","Every killed enemy dissolves: a white flash, then its pixels vanish with a white-hot edge while the body drifts up and away from the blow, with sparks of its colour. Not shown with «Reduce effects» on."),
        T("Quando un boss muore parte un'onda d'urto (tre anelli di luce, lampo bianco, scossa forte); il boss finale mantiene la sua sequenza di vittoria e aggiunge gli anelli.","When a boss dies a shock wave goes off (three rings of light, a white flash, a strong shake); the final boss keeps its victory sequence and adds the rings."),
      ]},
      {g:T("Cimeli","Trinkets"),l:[
        T("I cimeli trovati in partita e portati fino alla fine non vengono più venduti: entrano nella Borsa come ricompensa (e compaiono nella schermata finale). Quelli equipaggiati dalla Borsa non si duplicano. Se la Borsa ha già lo stesso cimelio con la stessa rarità, il nuovo viene venduto come prima, oppure ne migliora la perfezione se è più alta.","Trinkets found during the run and still carried at the end are no longer sold: they go into the Bag as a reward (and show on the end screen). The ones equipped from the Bag are not duplicated. If the Bag already holds the same trinket at the same rarity, the new one is sold as before, or it improves that copy's perfection when higher."),
        T("Perfezione dei cimeli più rara: la perfezione al 100% esce 1 volta su 1000 (prima circa 1 su 330); 90% o più circa 1 su 600, 80% o più circa 1 su 330, 50% o più circa 1 su 30; il valore tipico è intorno al 25%. La Fortuna alza la curva.","Rarer trinket perfection: a perfect 100% now comes up 1 time in 1000 (it was about 1 in 330); 90% or more about 1 in 600, 80% or more about 1 in 330, 50% or more about 1 in 30; the typical value is around 25%. Luck lifts the curve."),
      ]},
      {g:T("Musica dei boss","Boss music"),l:[
        T("Tutti i boss che non sono il boss finale della mappa (per esempio Mercenario Tao) ora hanno una musica da boss battle generica.","Every boss that is not the stage's final boss (for example Mercenary Tao) now has a generic boss-battle track."),
      ]},
    ],
    fix:[
      {g:T("Raccolta","Pick-up"),l:[
        T("Tutti gli oggetti a terra (zenny, cuori, Fortuna, Calamita, capsule, power-up a tempo) vengono attirati dal raggio di raccolta, come l'esperienza. Le Sfere del Drago restano da raccogliere a piedi.","All pick-ups on the ground (zenny, hearts, Fortune, Magnet, capsules, timed power-ups) are pulled in by your pick-up range, like experience. Dragon Balls still have to be picked up on foot."),
        T("Niente più oggetti, power-up o Sfere del Drago generati sull'acqua.","Nothing — items, power-ups or Dragon Balls — is generated on water any more."),
      ]},
      {g:T("Interfaccia","Interface"),l:[
        T("Finestra del forziere: lo Spazio preme «Raccogli».","Chest window: Space presses «Collect»."),
        T("Sostituzione dei cimeli: il bottone della carta centrale è allineato in fondo alla carta come gli altri.","Trinket swap: the middle card's button sits at the bottom of the card like the others."),
      ]},
    ],
  },
  {id:'2026-10-21f',date:'2026-10-21',
    name:T("Nuova musica per le mappe","New stage music"),
    sum:T("Sei mappe ricevono il loro brano e Freezer ha il suo tema da boss: ora tutte le mappe hanno la loro musica; i boss, tranne Cell e Freezer, usano ancora quella sintetizzata.","Six stages get their own track and Freezer gets a boss theme: every stage now has its own music; bosses other than Cell and Freezer still use the synthesized music."),
    new:[
      {g:T("Musica delle mappe","Stage music"),l:[
        T("Pianura Saiyan: ora ha un brano suo.","Saiyan Plains: now has a track of its own."),
        T("Pianeta Vegeta: ora ha un brano suo.","Planet Vegeta: now has a track of its own."),
        T("Arena dei Cell Game: ora ha un brano suo (durante lo scontro con Cell suona sempre «Perfect Cell's Theme»).","Cell Games Arena: now has a track of its own («Perfect Cell's Theme» still plays during the fight with Cell)."),
        T("Regno degli Dei: ora ha un brano suo.","Realm of the Gods: now has a track of its own."),
        T("Via del Serpente: ora ha un brano suo.","Snake Way: now has a track of its own."),
        T("Inferno: ora ha un brano suo.","Hell: now has a track of its own."),
      ]},
      {g:T("Musica dei boss","Boss music"),l:[
        T("Pianeta Namek: durante lo scontro con Freezer, il boss finale, suona il suo tema (rifacimento in stile arcade). Finito il boss riparte la musica della mappa.","Planet Namek: Freezer, the final boss, has his own theme (an arcade-style remix) while you fight him. When the boss falls the stage music comes back."),
      ]},
    ],
    fix:[
      {g:T("Interfaccia","Interface"),l:[
        T("Barra EXP: tolta anche la targhetta «LIVELLO n» sotto la medaglia (il livello è già scritto grande sulla barra) e le parti grafiche rimaste vuote: i profili dorati sopra e sotto la barra e la base della targhetta.","EXP bar: the «LEVEL n» plate under the medallion is gone too (the level is already written big on the bar), along with the graphics it left empty: the gold trims above and below the bar and the base of the plate."),
      ]},
    ],
  },
  {id:'2026-10-21e',date:'2026-10-21',
    name:T("Dati di gioco e musica di Cell","Game data and Cell's music"),
    sum:T("Ogni partita può registrare statistiche dettagliate (tempo di uccisione dei boss, livelli, nemici e danni minuto per minuto) da esportare per bilanciare il gioco; il boss finale di Cell ha il suo brano.","Every run can record detailed stats (boss kill times, levels, enemies and damage minute by minute) to export for balancing; Cell's final boss has its own theme."),
    new:[
      {g:T("Dati di gioco","Game data"),l:[
        T("Nuovo: Impostazioni > Partita > «Dati di gioco». Con l'interruttore acceso (di base lo è) ogni partita registra, solo su questo dispositivo e senza inviare nulla: un punto ogni minuto (livello, XP, uccisioni, nemici vivi in media e al massimo, danni inflitti e subiti al secondo, Salute media e minima, cure, monete, gemme, oggetti raccolti, distanza percorsa, armi e potenziamenti con i livelli, tutte le statistiche del personaggio) e uno ogni 10 secondi (nemici, Salute, danni).","New: Settings > Gameplay > «Game data». With the switch on (it is by default) every run records, on this device only and without sending anything: a point every minute (level, XP, kills, enemies alive on average and at the peak, damage dealt and taken per second, average and lowest Health, healing, coins, gems, pick-ups, distance walked, weapons and upgrades with their levels, all the character stats) and one every 10 seconds (enemies, Health, damage)."),
        T("Per ogni level-up: a che secondo, quanti secondi dal precedente, nemici vivi, Salute, le tre carte offerte, quella scelta (a mano o in automatico), se hai seguito la carta consigliata e quanto hai impiegato a scegliere.","For every level-up: at what second, seconds since the previous one, enemies alive, Health, the three cards offered, the one picked (by hand or automatic), whether you followed the advised card and how long you took to choose."),
        T("Per ogni boss: quando compare, tempo di uccisione (dalla comparsa e dal primo colpo), i tuoi danni al secondo contro di lui, i danni che subisci nello scontro, il tuo livello e, se perdi, la Salute che gli resta.","For every boss: when it shows up, kill time (from the spawn and from the first hit), your damage per second against it, the damage you take during the fight, your level and, if you lose, the Health it has left."),
        T("Per tipo di nemico (quanti ne compaiono, quanti ne uccidi, Salute media, vita media, danni che ti fa), per arma (danni, colpi, critici, uccisioni, quando l'hai presa), danni subiti per fonte, causa di morte, oggetti raccolti e usi di abilità, scatto, Senzu, compagno, rilancio, salto e esclusione, forziere, forme, prove e resurrezioni.","Per enemy type (how many appear, how many you kill, average Health, average lifetime, damage they deal to you), per weapon (damage, hits, crits, kills, when you got it), damage taken by source, cause of death, pick-ups and uses of ability, dash, Senzu, companion, reroll, skip and ban, chests, forms, trials and revivals."),
      ]},
      {g:T("Esportazione","Export"),l:[
        T("Esporta da quella schermata: tutto in JSON o a tabelle CSV (partite, minuto per minuto, livelli, boss, armi, nemici), oppure copia il JSON; «Cancella i dati» li elimina (serve premere due volte). Si tengono le ultime 40 partite. Le partite in modalità test non vengono registrate. Per leggere i dati c'è tools/analyze_telemetry.py (tassi di vittoria, ritmo dei livelli, tempi dei boss, cause di morte, armi, carte scelte).","Export from that screen: everything as JSON or as CSV tables (runs, minute by minute, levels, bosses, weapons, enemies), or copy the JSON; «Delete the data» removes it (press twice). The last 40 runs are kept. Test-mode runs are not recorded. tools/analyze_telemetry.py reads the data (win rates, level pacing, boss times, causes of death, weapons, cards picked)."),
      ]},
      {g:T("Musica","Music"),l:[
        T("Arena dei Cell Game: durante lo scontro con Cell, il boss finale, suona «Perfect Cell's Theme». Finito il boss riparte la musica della mappa. Gli altri boss restano con la musica sintetizzata.","Cell Games Arena: «Perfect Cell's Theme» plays during the fight with Cell, the final boss. When the boss falls the stage music comes back. Other bosses keep the synthesized music."),
      ]},
    ],
    fix:[
      {g:T("Suoni","Sound"),l:[
        T("Via del Serpente: un brano chiamato «snake way» (o «via del serpente») messo in assets viene ora riconosciuto come musica di quella mappa; prima non veniva abbinato a nessuna.","Snake Way: a track named «snake way» (or «via del serpente») placed in assets is now recognised as that stage's music; before it was matched to no stage."),
      ]},
    ],
  },
  {id:'2026-10-21d',date:'2026-10-21',
    name:T("Level-up automatico in ogni modalità","Auto level-up in every mode"),
    sum:T("Il level-up automatico, prima solo dell'Infinita, funziona in tutte le partite: si accende da Impostazioni > Partita > «Priorità», dove ordini anche quali armi e potenziamenti prendere per primi.","The auto level-up, which used to exist only in Endless, now works in every run: turn it on from Settings > Gameplay > «Priorities», where you also order which weapons and upgrades to take first."),
    new:[
      {g:T("Level-up automatico","Auto level-up"),l:[
        T("Il level-up automatico non è più solo dell'Infinita: vale in ogni modalità e per ogni personaggio. Quando è acceso, a ogni level-up il gioco sceglie da solo la carta (appare «▲ nome Lv n» sopra il personaggio) e il menu non si apre; con meno del 45% di Salute preferisce un Senzu. Finché è acceso non puoi usare Reroll, Salta e Ban.","The auto level-up is no longer Endless-only: it works in every mode and with every character. When it is on, the game picks the card by itself on every level-up («▲ name Lv n» shows over the character) and the menu does not open; below 45% Health it prefers a Senzu. While it is on you cannot use Reroll, Skip and Ban."),
        T("Dove si accende: solo da Impostazioni > Partita > «Priorità» (anche durante la partita, dal menu ESC > Impostazioni), con l'interruttore «Level-up automatico» che mostra una spiegazione al passaggio del mouse. Il menu ESC e la schermata di level-up non cambiano.","Where to turn it on: only from Settings > Gameplay > «Priorities» (also during a run, from the ESC menu > Settings), with the «Auto level-up» switch that explains itself on hover. The ESC menu and the level-up window do not change."),
        T("Il menu «Priorità» (Impostazioni > Partita) mostra, durante una partita, le armi e i potenziamenti che hai (fino a 10: 5 armi + 5 potenziamenti) e con ▲ ▼ ne cambi l'ordine; quello in cima viene scelto per primo quando compare tra le carte. Poi vengono i potenziamenti che servono a un'evoluzione, le armi che hai già e le nuove.","The «Priorities» menu (Settings > Gameplay) lists, during a run, the weapons and upgrades you own (up to 10: 5 weapons + 5 upgrades) and ▲ ▼ change their order; the one on top is taken first when it shows up among the cards. Then come the upgrades an evolution needs, the weapons you already have and the new ones."),
        T("Chi aveva acceso la «Selezione automatica» dell'Infinita la ritrova accesa, con le stesse priorità.","If you had turned on Endless «Auto-select», it is still on, with the same priorities."),
      ]},
    ],
    bal:[
      {g:T("Economia","Economy"),l:[
        T("Serie di uccisioni (+50 monete ogni 50 di fila): la barra nascosta ora cala del 3% al secondo, cioè 1,5% ogni 0,5 secondi (prima 2% al secondo, 1% ogni 0,5 secondi). Senza uccisioni la serie finisce dopo circa 33 secondi invece di 50. La serie di 4 secondi dell'Esperienza non cambia.","Kill streak (+50 coins every 50 in a row): the hidden bar now drops 3% per second, that is 1.5% every 0.5 seconds (before: 2% per second, 1% every 0.5 seconds). With no kills the streak ends after about 33 seconds instead of 50. The 4-second XP streak is unchanged."),
      ]},
    ],
    fix:[
      {g:T("Ricompense","Pickups"),l:[
        T("I potenziamenti a tempo, Fuoco rapido (il fulmine) e Danni +15% (la freccia rossa), vengono attirati verso di te da tutta l'area di raccolta del personaggio, alla stessa velocità delle gemme di Esperienza (prima solo dal 70% dell'area, più piano, e il Fuoco rapido per niente). Il potenziamento Calamita li attira da qualsiasi distanza, come le borse di zenny.","The timed power-ups, Rapid fire (the lightning bolt) and Damage +15% (the red arrow), are pulled toward you from the character's whole pickup range, at the speed of the Experience gems (before: only the inner 70% of the range, slower, and Rapid fire not at all). The Magnet power-up pulls them from any distance, like the zenny bags."),
      ]},
      {g:T("Interfaccia","Interface"),l:[
        T("Barra EXP: tolta la targhetta «LV» in alto a sinistra (il livello è già scritto grande sulla barra) e la scritta «NEXT» in alto a destra.","EXP bar: removed the small «LV» plate at the top left (the level is already written big on the bar) and the «NEXT» label at the top right."),
      ]},
      {g:T("Suoni","Sounds"),l:[
        T("Nuovo suono per il level-up (assets/level_up_sound.mp3), riprodotto a velocità doppia: dura meno di 1 secondo. Il suono della scelta della carta resta quello di prima.","New level-up sound (assets/level_up_sound.mp3), played at double speed: it lasts under 1 second. The sound of picking a card stays as before."),
      ]},
      {g:T("Codice","Code"),l:[
        T("L'impostazione si chiama ora lvAuto / lvPrio (prima endAuto / endPrio); i salvataggi vecchi vengono convertiti da soli.","The setting is now called lvAuto / lvPrio (it was endAuto / endPrio); old saves are converted automatically."),
        T("Sprite riordinati in assets/sprites: quelli usati, le sorgenti (_sorgenti) e quelli non più usati (_inutilizzati) sono in cartelle separate; il gioco non cambia.","Sprites reorganized in assets/sprites: the ones in use, the sources (_sorgenti) and the ones no longer used (_inutilizzati) now live in separate folders; the game does not change."),
        T("Nuovo test automatico del level-up automatico (modalità normale, priorità, menu in Impostazioni).","New automatic test for the auto level-up (normal mode, priorities, Settings menu)."),
      ]},
    ]},
  {id:'2026-10-21c',date:'2026-10-21',
    name:T("Rocce nuove su Namek e Inferno","New rocks on Namek and Inferno"),
    sum:T("Pianeta Namek e Inferno hanno rocce nuove disegnate a mano, appoggiate a terra, senza ombra; su Inferno sono di lava e molte si muovono in loop (vulcani che fumano, lava che cola, crateri che ribollono).","Planet Namek and Hell have new hand-drawn rocks standing on the ground, without a shadow; in Hell they are lava rocks and many loop-animate (smoking volcanoes, dripping lava, bubbling craters)."),
    new:[
      {g:T("Mappe","Maps"),l:[
        T("Pianeta Namek: 20 rocce grigie nuove (massi, lastre, guglie) al posto delle vecchie pietre disegnate; ogni roccia poggia sul terreno con la base piatta a filo del suolo, senza ombra, e non viene mai piazzata, nemmeno in parte, nell'acqua o sulla riva.","Planet Namek: 20 new grey rocks (boulders, slabs, spires) replace the old drawn stones; every rock rests on the ground with a flat base flush with the floor, no shadow, and is never placed, not even partly, in the water or on the shore."),
        T("Inferno: 30 rocce vulcaniche nuove con lava al posto delle vecchie rocce e dei sassi di lava; quelle con la lava illuminano il terreno attorno e lanciano scintille.","Hell: 30 new volcanic rocks with lava replace the old rocks and lava stones; the ones with lava light the ground around them and throw sparks."),
        T("Inferno: 7 rocce sono animate in loop, vulcano grande, lastra che cola, doppio cratere, masso, masso medio che cola, guglia e piccolo vulcano; ognuna parte in un momento diverso, così non si muovono tutte insieme.","Hell: 7 rocks are animated in a loop, big volcano, dripping slab, twin crater, boulder, mid boulder, spire and small volcano; each starts at a different moment so they do not all move together."),
      ]},
    ],
    fix:[
      {g:T("Mappe","Maps"),l:[
        T("Namek: tolti i sassi piccoli disegnati dal terreno e dagli oggetti; Inferno: tolta la vecchia roccia di lava con le braci. Gli altri pianeti non cambiano.","Namek: the small drawn pebbles are gone from the ground and the props; Hell: the old lava rock with embers is gone. The other planets do not change."),
      ]},
      {g:T("Codice","Code"),l:[
        T("Il collegamento alle rocce usa un atlas per pianeta (tools/make_rocks.py) e un nuovo test automatico controlla base a terra, acqua, animazioni e che gli altri pianeti restino come prima.","Rocks now come from one atlas per planet (tools/make_rocks.py) and a new automatic test checks the base on the ground, water, animations and that the other planets stay as they were."),
      ]},
    ]},
  {id:'2026-10-21b',date:'2026-10-21',
    name:T("Sicurezza e pulizia","Security and cleanup"),
    sum:T("Account e salvataggi più protetti (password più robuste, blocco dopo troppi tentativi, login Google a prova di link truccati, salvataggi manomessi ripuliti) e codice ripulito da parti inutilizzate.","Safer accounts and saves (stronger passwords, a pause after too many attempts, Google sign-in that ignores forged links, tampered saves cleaned up) and the code tidied of unused parts."),
    new:[
      {g:T("Sicurezza","Security"),l:[
        T("Password dell'account: servono almeno 8 caratteri, non un solo carattere ripetuto, non la tua email e non una password famosa (password, 12345678...).","Account password: at least 8 characters, not one repeated character, not your e-mail and not a famous password (password, 12345678...)."),
        T("Dopo 5 password sbagliate in 5 minuti l'accesso si ferma per un minuto, con il conto alla rovescia.","After 5 wrong passwords within 5 minutes the sign-in pauses for a minute, with a countdown."),
        T("Accesso con Google: il ritorno dalla pagina di Google vale solo se hai premuto il pulsante Google su questo dispositivo, così un link truccato non può collegarti all'account di un altro.","Google sign-in: the return from Google only counts if you pressed the Google button on this device, so a forged link cannot sign you into somebody else's account."),
        T("Salvataggi (sul dispositivo, nel cloud o incollati): numeri fuori scala, testi enormi e chiavi pericolose vengono ripuliti prima dell'uso, e un salvataggio rovinato non blocca più il gioco.","Saves (on the device, in the cloud or pasted): out-of-range numbers, huge texts and dangerous keys are cleaned before use, and a damaged save no longer stops the game."),
        T("Il sito non esegue script iniettati (Content-Security-Policy), non manda l'indirizzo di provenienza ad altri siti e usa il server cloud solo via https.","The site refuses injected scripts (Content-Security-Policy), does not send the referring address to other sites and only talks to the cloud server over https."),
      ]},
      {g:T("Account","Account"),l:[
        T("«Password dimenticata?» ora mostra un avviso (al passaggio del mouse o toccandolo): il recupero della password non è disponibile, si crea un nuovo account o si entra con Google; il modulo di registrazione lo ricorda. Il recupero via email si riaccende con SUPABASE_RESET=1 (serve un SMTP tuo su Supabase).","«Forgot password?» now shows a notice (on hover or when tapped): password recovery is not available, create a new account or sign in with Google; the sign-up form says so too. E-mail recovery comes back with SUPABASE_RESET=1 (needs your own SMTP on Supabase)."),
        T("Il pulsante «Continua con Google» è sempre visibile nella schermata Account (se Google non è ancora attivo sul progetto, lo spiega).","The «Continue with Google» button is always visible on the Account screen (if Google is not enabled on the project yet, it says so)."),
      ]},
    ],
    fix:[
      {g:T("Codice","Code"),l:[
        T("Pulizia del codice: rimossi gli sprite vecchi dei nemici e alcune funzioni mai usate; aggiunti test automatici per sicurezza e per il controllo delle traduzioni.","Code cleanup: removed the old enemy sprites and a few functions that were never used; added automatic tests for security and for the translation check."),
      ]},
    ]},
  {id:'2026-10-21',date:'2026-10-21',
    name:T("Quantità, Scanner e 128 nuovi cimeli","Amount, Scanner and 128 new trinkets"),
    sum:T("Nuovi potenziamenti del negozio (Quantità, Scanner Sfere del Drago e Urlo di Broly!), Armatura Saiyan più forte, 128 nuovi cimeli con combinazioni di statistiche diverse e la barra del roll da 0 a 100 su ogni cimelio.","New shop upgrades (Amount, Dragon Ball Scanner and Broly's Roar!), a stronger Saiyan Armor, 128 new trinkets with different stat combinations and the 0 to 100 roll bar on every trinket."),
    new:[
      {g:T("Negozio","Shop"),l:[
        T("Quantità: ogni arma lancia +1 proiettile per livello (massimo 2 acquisti, 2000 Zenny il primo, poi 6000). Si somma ai proiettili delle trasformazioni e dei cimeli.","Amount: every weapon fires +1 projectile per level (2 purchases max, 2000 Zenny for the first, then 6000). It adds to the projectiles from transformations and trinkets."),
        T("Scanner Sfere del Drago (con l'icona del radar): +5% frequenza di comparsa delle Sfere del Drago per livello, valido per le sfere normali, le Super Sfere e quelle lasciate dai nemici (massimo 2 acquisti, 3000 Zenny il primo, poi 9000).","Dragon Ball Scanner (with the radar icon): +5% Dragon Ball spawn rate per level, for normal balls, Super Dragon Balls and enemy drops (2 purchases max, 3000 Zenny for the first, then 9000).")
      ]},
      {g:T("Grafica","Graphics"),l:[
        T("Quantità: i colpi extra non partono più tutti insieme sovrapposti, ma uno dopo l'altro (ogni 0,16 secondi) e rimirati sul nemico più vicino, così si vedono come colpi separati: Colpo di Ki, Colpi Eccentrici, Lancia Ribelle, Doppio Sunday (un colpo in più dopo l'altro), Spada (un fendente in più), Kamehameha (raggi extra uno dopo l'altro, in direzioni diverse). Disco Distruttore e Raggio Perforante aggiungono un disco o un raggio in più. Prima Quantità non contava per Colpo di Ki, Kamehameha, Disco Distruttore, Spada e Raggio Perforante.","Amount: the extra hits no longer leave all together on top of each other, but one after the other (every 0.16 seconds) and re-aimed at the nearest enemy, so they read as separate hits: Ki Blast, Homing Orbs, Rebel Javelin, Double Sunday (one more blast after another), Sword (one more swing), Kamehameha (extra beams one after the other, in different directions). Destructo Disc and Piercing Beam add one more disc or beam. Before, Amount did not count for Ki Blast, Kamehameha, Destructo Disc, Sword and Piercing Beam."),
        T("Ogni potenziamento del negozio ha il suo colore di scritta (Vitalità rosso, Agilità blu, Armatura azzurro, Danno arancione, Studio ambra, Occhio Critico rosa, Magnetismo viola, Fortuna lime...).","Every shop upgrade has its own text colour (Vitality red, Agility blue, Saiyan Armor light blue, Damage orange, Study amber, Keen Eye pink, Magnetism violet, Luck lime...)."),
        T("Ogni potenziamento del negozio (20 su 20) ha la sua icona pixel art in stile Dragon Ball e il suo colore del testo. Le stesse icone compaiono in partita: sulle carte di level-up e nella pausa per Vigore, Armatura da Battaglia, Volo veloce, Zenkai, Meditazione, Fagioli Senzu, Scouter e Camera Gravitazionale, e nella barra dei potenziamenti in alto a sinistra.","Every shop upgrade (20 of 20) now has its own Dragon Ball style pixel-art icon and text colour. The same icons show in the game: on the level-up cards and in the pause list for Vigor, Battle Armor, Swift Flight, Zenkai, Meditation, Senzu Beans, Scouter and Gravity Chamber, and in the upgrade bar at the top left.")
      ]},
      {g:T("Gacha","Gacha"),l:[
        T("Estraendo 100 ticket insieme ora vedi tutte e 100 le estrazioni a schermo, una per una (non più raggruppate): le tessere si ridimensionano da sole per entrare nella finestra senza scorrere. Passando il mouse su un cimelio (o toccandolo, o selezionandolo con la tastiera) compare la scheda con nome, rarità, Perfezione e statistiche, e se è nuovo o un doppione.","Pulling 100 tickets at once now shows all 100 results on screen, one by one (no longer grouped): the tiles resize themselves to fit the window without scrolling. Hovering a trinket (or tapping it, or selecting it with the keyboard) shows a card with its name, rarity, Perfection and stats, and whether it is new or a duplicate.")
      ]},
      {g:T("Borsa e menu","Bag and menus"),l:[
        T("Borsa dei cimeli: le opzioni di ordinamento sono ora icone in colonna a sinistra (più recenti, meno recenti, rarità, perfezione, nome), con il suggerimento al passaggio del mouse; i filtri di rarità sono spostati a destra, sopra la scheda del cimelio.","Trinket bag: the sort options are now a column of icons on the left (newest, oldest, rarity, perfection, name), with a tooltip on hover; the rarity filters moved to the right, above the trinket card."),
        T("Il menu «Ordina» nella selezione del personaggio (e tutte le altre tendine) ora si legge: sfondo scuro e testo chiaro, prima era bianco su bianco e il testo compariva solo passandoci sopra.","The «Sort» menu in the character select (and every other drop-down) is now readable: dark background and light text; it used to be white on white and the text only showed on hover."),
        T("I numeri dei danni sono molto più leggibili: carattere pulito e meno spesso, dritto, bianco (rosso per i critici) con un contorno sottile, ridisegnato a doppia risoluzione.","Damage numbers are much easier to read: a clean, lighter and upright font, white (red for critical hits) with a thin outline, drawn at double resolution.")
      ]},
      {g:T("Difficoltà","Difficulty"),l:[
        T("Urlo di Broly! (nuovo potenziamento del negozio, con l'immagine di Broly): +5% frequenza di comparsa dei nemici per livello, fino a +25% al massimo (5 acquisti, 666 Zenny il primo, poi 1132, 1925, 3272 e 5563). Più nemici significa più esperienza e bottino, ma anche più pericolo.","Broly's Roar! (new shop upgrade, with Broly's picture): +5% enemy spawn rate per level, up to +25% (5 purchases, 666 Zenny for the first, then 1132, 1925, 3272 and 5563). More enemies means more experience and loot, but also more danger.")
      ]},
      {g:T("Cimeli e negozio","Trinkets and shop"),l:[
        T("128 nuovi cimeli, ognuno con una combinazione diversa di 2 o 3 statistiche (78 coppie e 40 terne, per esempio Anello del Guerriero: danno e velocità). Come gli altri cimeli con statistiche esistono a tutte le rarità, da Comune a Mitico: ogni rarità ha ora più di 100 combinazioni diverse nel Gacha, nel negozio di Zeno e nei forzieri.","128 new trinkets, each with a different combination of 2 or 3 stats (78 pairs and 40 triples, for example Ring of the Warrior: damage and speed). Like the other stat trinkets they exist at every rarity, Common to Mythic: each rarity now has over 100 different combinations in the Gacha, Zeno's shop and chests."),
        T("10 di questi cimeli danno anche Quantità (+proiettili per ogni arma) e compaiono solo a Leggendario e Mitico: Leggendario +2 (+3 con roll 100), Mitico +3 (+4 da roll 50, +5 con roll 100).","10 of these trinkets also give Amount (+projectiles for every weapon) and only come out at Legendary and Mythic: Legendary +2 (+3 with a 100 roll), Mythic +3 (+4 from a 50 roll, +5 with a 100 roll)."),
        T("Barra del roll da 0 a 100 su ogni cimelio: nella Borsa, negli slot della schermata del personaggio (con il numero a destra), nelle carte dei forzieri e delle scelte in partita, nell'elenco della pausa, nei risultati del Gacha e nella nuvoletta del negozio di Zeno. Tacche a 25, 50 e 75; a 100 la barra brilla come l'aura Ultra Istinto.","0 to 100 roll bar on every trinket: in the Bag, in the slots of the character screen (with the number on the right), on chest and in-run choice cards, in the pause list, in the Gacha results and in Zeno's shop bubble. Ticks at 25, 50 and 75; at 100 the bar shimmers like the Ultra Instinct aura."),
        T("I cimeli con soli effetti (Cuore di Kaioh, Aureola, ...) restano ben rappresentati: pesano 12 volte un cimelio con statistiche nell'estrazione.","Effect-only trinkets (Kaioh's Heart, Halo, ...) stay well represented: they weigh 12 times a stat trinket in the draw."),
        T("Nelle partite i cimeli con statistiche escono ora a qualsiasi rarità (come nel Gacha e da Zeno), non solo a quella di base.","In runs, stat trinkets now come out at any rarity (like in the Gacha and from Zeno), not just their base one.")
      ]}
    ],
    bal:[
      T("Fulmine Angelico indebolito: danno dimezzato (da 10-22 a 5-11 per salto) e cadenza più lenta (un fulmine ogni 2,2-1,45 secondi invece di 1,4-0,9). Vale per tutti i personaggi che lo usano (Whis, Zamasu, Mr. Popo, Frost...).","Angelic Bolt nerfed: half the damage (from 10-22 to 5-11 per jump) and a slower rhythm (one bolt every 2.2-1.45 seconds instead of 1.4-0.9). It applies to every character that uses it (Whis, Zamasu, Mr. Popo, Frost...)."),
      T("Cimeli con Perfezione 100%: molto più rari (circa 0,3% invece del 4%, fino a circa 0,7% con la Fortuna al massimo). Gli altri valori vanno da 0 a 99 come prima.","Trinkets with 100% Perfection: much rarer (about 0.3% instead of 4%, up to about 0.7% with maximum Luck). Other values still go from 0 to 99."),
      T("Armatura Saiyan: +2 armatura per livello (prima +1,25), cioè +12 al massimo (prima +7,5).","Saiyan Armor: +2 armor per level (was +1.25), +12 at the maximum (was +7.5).")
    ]
  },
  {id:'2026-10-20f',date:'2026-10-20',
    name:T("Cooler su Namek, cimeli extra e password","Cooler on Namek, extra trinkets and password"),
    sum:T("Cooler arriva su Pianeta Namek con le sue trasformazioni, gli slot extra dei cimeli si vedono davvero, il Maestro della Stanza dello Spirito e del Tempo imita le tue armi, la password si reimposta con un codice e c'è il login con Google.","Cooler arrives on Planet Namek with his transformations, the extra trinket slots are finally visible, the Master of the Room of Spirit and Time copies your weapons, the password is reset with a code and Google login is here."),
    new:[
      {g:T("Boss","Bosses"),l:[
        T("Cooler è un boss del tardo Pianeta Namek (minuto 500, dopo Zarbon e prima di Freezer): ha tre forme (Cooler, Cooler Metal e Cooler Finale) e usa la Supernova.","Cooler is a late Planet Namek boss (minute 500, after Zarbon and before Freezer): he has three forms (Cooler, Metal Cooler and Final Cooler) and uses the Supernova."),
        T("Il Maestro della Stanza dello Spirito e del Tempo imita le armi che hai equipaggiate: le sue sfere, i raggi, le lance, le zone (Bomba Spirituale, Meteora, Granata Infernale, Hakai) hanno lo stesso aspetto dei tuoi, ma fanno il 60% del danno.","The Master of the Room of Spirit and Time copies the weapons you carry: his orbs, beams, spears and zones (Spirit Bomb, Meteor, Hellzone, Hakai) look like yours but deal 60% of the damage.")
      ]},
      {g:T("Cimeli e negozio","Trinkets and shop"),l:[
        T("Gli slot extra dei cimeli comprati nel negozio compaiono nella schermata del personaggio e nella Borsa (fino a 3): tocca uno slot per scegliere dove mettere il cimelio; lo stesso cimelio non può stare in due slot.","The extra trinket slots bought in the shop now show on the character screen and in the Bag (up to 3): pick a slot to choose where the trinket goes; the same trinket cannot sit in two slots.")
      ]},
      {g:T("Account","Account"),l:[
        T("Password dimenticata: scrivi l'email, ricevi un codice a 6 cifre, inseriscilo nel gioco e scegli la nuova password (il link nell'email funziona ancora, ma può scadere se il programma di posta lo apre prima di te).","Forgotten password: enter your email, get a 6-digit code, type it in the game and choose a new password (the link in the email still works, but may expire if your mail program opens it before you).")
        ,T("Accedi con Google: il pulsante compare da solo quando il provider è attivo su Supabase; l'immagine di sfondo della schermata di accesso è stata tolta.","Sign in with Google: the button shows up by itself when the provider is enabled on Supabase; the background picture of the login screen is gone.")
      ]}
    ],
    fix:[
      T("Tamagami: se i fogli grafici non erano ancora caricati quando il boss compariva, restava con lo sprite base per tutta la partita; ora passa allo sprite giusto appena sono pronti. La statua di riserva (senza i fogli) ora si vede sopra la luce della Super Sfera, e il Glossario mostra la grafica vera di boss e nemici.","Tamagami: if the art sheets had not finished loading when the boss appeared, it kept the basic sprite for the whole run; it now switches to the right sprite as soon as they are ready. The fallback statue (without the sheets) is now drawn above the Super Dragon Ball light, and the Glossary shows the real art of bosses and enemies.")
    ]
  },
  {id:'2026-10-20e',date:'2026-10-20',
    name:T("Ragni, ombre e numeri di danno","Spiders, shadows and damage numbers"),
    sum:T("I ragni sui barili si muovono in modo naturale, i gabbiani lasciano il posto alle loro ombre sul terreno, i numeri di danno diventano arcade (rossi per i colpi critici) e restano 0,3 secondi in più, e Dyspo ha finalmente il suo aspetto.","The spiders on the barrels move naturally, the gulls give way to their shadows on the ground, damage numbers turn arcade-style (red for critical hits) and stay 0.3 seconds longer, and Dyspo finally looks like himself."),
    new:[
      {g:T("Mappe","Maps"),l:[
        T("Gabbiani rimossi: né gli stormi a V che attraversavano il cielo (Pianura Saiyan, Pianeta Namek, Rovine degli Androidi, Isola di Muten, Pianeta Vegeta, Regno degli Dei, Via del Serpente) né gli uccelli singoli (anche all'Inferno) si vedono più. Resta solo la loro ombra sul terreno, piccola (circa 20-30 px di apertura alare) e leggera (10% di opacità, svanisce di notte): lo stormo è un gruppo di 6-7 ombre che planano in formazione a V a 36-50 px/s e ogni tanto battono le ali. Le ombre sono ancorate alla mappa, quindi scorrono con il terreno mentre ti muovi; compaiono solo ogni tanto.","Gulls removed: neither the V-shaped flocks that crossed the sky (Saiyan Plains, Planet Namek, Android Ruins, Roshi's Island, Planet Vegeta, Realm of the Gods, Snake Way) nor single birds (Hell included) are drawn any more. Only their shadow remains on the ground, small (about 20-30 px of wingspan) and light (10% opacity, fading at night): a flock is a group of 6-7 shadows gliding in a V at 36-50 px/s, flapping now and then. The shadows are anchored to the map, so they slide with the ground as you move; they only show up from time to time."),
        T("Anche i gabbiani posati sono spariti: quelli su casse e barili di Isola di Muten, Pianura Saiyan e Arena dei Cell Game e quelli sulle lapidi di Isola di Muten (i corvi, sulle recinzioni, sulle lapidi delle altre mappe e su casse e barili delle altre mappe, restano).","Perched gulls are gone too: those on crates and barrels in Roshi's Island, Saiyan Plains and the Cell Games Arena, and those on gravestones in Roshi's Island (crows on fences, on gravestones in the other maps and on crates and barrels in the other maps stay)."),
        T("Ragni sui barili: ora si comportano da ragni. Quello che cammina sulla faccia del barile sceglie un punto a caso, ci va (le zampe si muovono in base alla strada fatta, con partenza e frenata morbide), poi si ferma 3-5 secondi e fa qualcosa a caso: si solleva alzando la testa e le zampe anteriori, si pulisce le zampe anteriori, si guarda intorno o scuote una zampa; poi riparte, in cicli di 6,5 secondi. Quello appeso al filo si cala fino a circa 12 px, dondola e ruota piano, risale a scatti con la testa in su e riposa vicino al coperchio, in cicli di 14 secondi.","Spiders on barrels now act like spiders. The one on the barrel face picks a random spot and walks to it (its legs follow the distance covered, with a soft start and stop), then stops for 3-5 seconds and does something at random: rears up raising its head and front legs, grooms its front legs, looks around or twitches a leg; then it sets off again, in 6.5-second cycles. The one hanging from a thread lets itself down as far as about 12 px, sways and turns slowly, climbs back up in jerks head-up and rests near the lid, in 14-second cycles."),
        T("Nuovo disegno del ragno: corpo in due parti (addome e testa) e otto zampe snodate con andatura alternata.","New spider drawing: a two-part body (abdomen and head) and eight jointed legs with an alternating gait.")
      ]},
      {g:T("Combattimento","Combat"),l:[
        T("Numeri di danno sui nemici in stile arcade alla Dragon Ball: carattere pesante, stretto e inclinato (Anton, vicino a quello del logo), sfumatura bianco-giallo, contorno scuro con bordo 3D e bordi netti a pixel. Compaiono con un piccolo «pop» e salgono lentamente.","Damage numbers on enemies in a Dragon Ball arcade style: heavy, narrow, slanted lettering (Anton, close to the logo's type), white-to-yellow gradient, dark outline with a 3-D edge and crisp pixel edges. They pop in and drift upwards slowly."),
        T("Colpi critici rossi: il numero è rosso con sfumatura dal salmone al rosso scuro, più grande di un colpo normale e con un breve tremolio all'inizio (prima era dorato e distinguibile solo per la dimensione).","Critical hits are red: the number is red with a salmon-to-dark-red gradient, bigger than a normal hit and with a brief shake when it appears (before, it was gold and set apart only by its size)."),
        T("Il carattere si scarica da Google Fonts: senza connessione i numeri usano Impact, Arial Black o un carattere di sistema pesante. I testi di altro tipo (+Z, «Senzu!», «Schivata!», i danni che subisci) restano come prima.","The font is downloaded from Google Fonts: offline the numbers use Impact, Arial Black or a heavy system font. Other texts (+Z, \"Senzu!\", \"Dodge!\", the damage you take) stay as before.")
      ]},
      {g:T("Personaggi","Characters"),l:[
        T("Dyspo rifatto sull'anime: pelle viola come Beerus (stessa razza), occhi gialli, nessun capello, due lunghe orecchie dritte da coniglio, tuta rossa e grigia con guanti e stivali bianchi. Vale per il personaggio giocabile e per il boss (Dyspo e Dyspo Velocità Suprema, con il viola più chiaro).","Dyspo redone after the anime: purple skin like Beerus (same race), yellow eyes, no hair, two long upright rabbit ears, a red and grey suit with white gloves and boots. It applies to the playable character and to the boss (Dyspo and Dyspo Supreme Speed, with a lighter purple)."),
        T("Beerus ha la pelle più viola (era grigio-azzurra), sia come personaggio sia come boss (anche nella forma Ira Divina).","Beerus has more purple skin (it was grey-blue), both as a character and as a boss (Divine Wrath form included).")
      ]}
    ],
    fix:[
      T("I ragni dei barili non vanno più in loop: prima giravano senza mai fermarsi lungo lo stesso bordo a velocità costante, oppure restavano appesi a dondolare quasi senza muovere le zampe; ora camminano, si fermano e fanno cose diverse ogni volta.","Barrel spiders no longer loop: they used to run round the same rim without ever stopping at a constant speed, or hang there swaying with their legs barely moving; now they walk, stop and do something different each time.")
    ],
    bal:[
      T("I numeri di danno e dei colpi critici restano a schermo 1,1 secondi (prima 0,8). Al massimo 46 numeri di danno insieme (prima 50 testi in tutto); gli altri testi (+Z, avvisi, bonus) restano 0,8 secondi e hanno sempre almeno 24 posti liberi.","Damage and critical-hit numbers stay on screen 1.1 seconds (before 0.8). At most 46 damage numbers at once (before 50 texts in all); other texts (+Z, notices, bonuses) stay 0.8 seconds and always have at least 24 free slots.")
    ]
  },
  {id:'2026-10-20d',date:'2026-10-20',
    name:T("Boss, nemici e personaggi","Bosses, enemies and characters"),
    sum:T("I boss si trasformano curandosi, Freezer e Cell passano per tutte le forme, Dodoria, Dr. Gero e Super Buu hanno mosse nuove, le Rovine degli Androidi diventano la sfida degli androidi canonici (uno ogni 5 minuti), il Regno degli Dei ha i Kaioshin e Champa, e Piccolo, Toppo e Gotenks cambiano mentre arriva Zeno-sama come personaggio giocabile.","Bosses transform and heal, Frieza and Cell go through every form, Dodoria, Dr. Gero and Super Buu have new moves, the Android Ruins become a gauntlet of canonical androids (one every 5 minutes), the Realm of the Gods has the Kaioshin and Champa, and Piccolo, Toppo and Gotenks change while Zeno-sama arrives as a playable character."),
    new:[
      {g:T("Boss e nemici","Bosses and enemies"),l:[
        T("Trasformazioni: quando un nemico si trasforma (boss compresi: Beerus, Janemba, Cooler, Kale, Toppo, Hit, Dyspo, Androide 13, Androide 21...) recupera il 50% della Salute massima e Salute massima, danno, velocità e armatura salgono del 20% a ogni trasformazione. Compare «+50% HP» sopra il boss e il banner dice cosa è successo.","Transformations: when an enemy transforms (bosses included: Beerus, Janemba, Cooler, Kale, Toppo, Hit, Dyspo, Android 13, Android 21...) it recovers 50% of its maximum health, and maximum health, damage, speed and armor grow by 20% with every transformation. «+50% HP» appears above the boss and the banner says what happened."),
        T("Freezer, boss finale di Namek, non si trasforma più una volta sola: passa per tutte le forme (Prima, Seconda, Terza, Forma Finale, 100% Potenza), una ogni volta che la Salute scende al 60%. Ogni forma ha il proprio aspetto, le proprie mosse e il proprio ritmo; la velocità sale solo del 2,5% a ogni forma (le altre statistiche del 20%).","Frieza, final boss of Namek, no longer transforms just once: he goes through every form (First, Second, Third, Final Form, 100% Power), one each time his health drops to 60%. Every form has its own look, moves and rhythm; speed grows only 2.5% per form (the other stats 20%)."),
        T("Cell, boss finale dell'Arena dei Cell Game, riceve lo stesso trattamento: Cell (Imperfetto) → Semi-Perfetto → Cell Perfetto, una forma ogni volta che la Salute scende al 60%, velocità +2,5% a forma. Nelle Rovine degli Androidi Cell non compare più.","Cell, final boss of the Cell Games Arena, gets the same treatment: Cell (Imperfect) → Semi-Perfect → Perfect Cell, one form each time health drops to 60%, speed +2.5% per form. Cell no longer appears in the Android Ruins."),
        T("Morte del boss finale: prima del menu «Stage completato» parte un'animazione di 4,2 secondi al rallentatore (40% di velocità): il boss resta fermo mentre esplosioni, scariche e anelli di energia crescono per 2,6 secondi e lo schermo trema sempre di più, poi un'enorme esplosione bianca, il banner «VITTORIA!» e solo dopo si apre il menu. Durante la sequenza i proiettili nemici spariscono, gli altri nemici svaniscono e non puoi essere colpito.","Final boss death: before the «Stage complete» menu a 4.2-second slow-motion animation plays (40% speed): the boss stands still while explosions, sparks and energy rings build for 2.6 seconds and the screen shakes harder and harder, then a huge white blast, the «VICTORY!» banner, and only then the menu opens. During the sequence enemy bullets vanish, the other enemies fade away and you cannot be hit."),
        T("Barra della vita dei nemici: ora sta sopra la testa (in cima allo sprite) e non più in mezzo al corpo; vale per i nemici normali e per gli Élite.","Enemy health bars: they now sit above the head (at the top of the sprite) instead of in the middle of the body; for normal enemies and Elites alike.")
      ]},
      {g:T("Mosse speciali dei boss","Boss signature moves"),l:[
        T("Dodoria (Namek) - Lancio di corpo: ogni 12 secondi, se sei a meno di 640 px, si ferma, trema e si accovaccia per 3 secondi (il bersaglio segue i tuoi movimenti per 2 secondi, poi si blocca per l'ultimo) mentre a terra compare la traiettoria rossa, larga quanto il suo corpo e lunga 560-900 px. Poi si lancia rotolando: chi sta sulla traiettoria subisce 2,2 volte il danno del boss e viene sbalzato; lo schianto finale crea un'onda d'urto e lo lascia stordito 1,5 secondi. Uscire dalla traiettoria prima dello scatto evita tutto.","Dodoria (Namek) - Body hurl: every 12 seconds, when you are within 640 px, he stops, shakes and crouches for 3 seconds (the aim follows you for 2 seconds, then locks for the last one) while the red path, as wide as his body and 560-900 px long, appears on the ground. Then he hurls himself rolling: anyone on the path takes 2.2 times the boss damage and is thrown back; the final slam makes a shockwave and leaves him stunned for 1.5 seconds. Leaving the path before the dash avoids everything."),
        T("Dr. Gero (Rovine degli Androidi) - Presa: ogni 14 secondi si carica per 1,15 secondi (aloni verdi) e scatta su di te per 330 px; se ti raggiunge ti afferra e ti risucchia la vita per 3 secondi in 6 colpi: 5% della tua Salute massima in Facile, 15% in Normale, 25% in Difficile, 35% in Estremo, e si cura dello 0,4% della sua vita a colpo. Ti liberi con uno scatto, stordendolo o togliendogli più del 6% della sua Salute massima mentre ti tiene; l'armatura non riduce il drenaggio.","Dr. Gero (Android Ruins) - Hold: every 14 seconds he charges for 1.15 seconds (green glow) and lunges at you for 330 px; if he reaches you he grabs you and drains your life for 3 seconds in 6 ticks: 5% of your maximum health on Easy, 15% on Normal, 25% on Hard, 35% on Extreme, healing 0.4% of his own health per tick. You break free with a dash, by stunning him or by taking more than 6% of his maximum health off him while he holds you; armor does not reduce the drain."),
        T("Super Buu (Dimensione di Bu) - Pioggia di ki: ogni 10 secondi alza il braccio e spara verso l'alto una palla ogni 0,1 secondi: 50 in Facile, 55 in Normale, 60 in Difficile, 70 in Estremo. Dopo 3 secondi dallo sparo ogni palla ricade intorno a te (un bersaglio rosa a terra compare 1 secondo prima). Ogni palla che ti colpisce toglie il 2% della tua Salute massima, anche con armatura,. Con suoni di carica, sparo e impatto.","Super Buu (Buu's Dimension) - Rain of ki: every 10 seconds he raises his arm and fires a ball straight up every 0.1 seconds: 50 on Easy, 55 on Normal, 60 on Hard, 70 on Extreme. 3 seconds after being fired each ball falls around you (a pink marker appears on the ground 1 second before). Every ball that hits you takes 2% of your maximum health, even with armor. With charge, fire and impact sounds.")
      ]},
      {g:T("Rovine degli Androidi","Android Ruins"),l:[
        T("Boss canonici ogni 5 minuti di partita, in tempo reale: Androide 13 al minuto 5 (a metà scontro assorbe i dati e diventa Super C-13, come nel film: pelle blu e capelli arancioni), Androide 14 al 10, Androide 15 al 15, C-16 al 20, C-17 al 25, C-18 al 30. Dr. Gero resta il primo boss, a 2:30. Il boss finale è il primo androide a fine partita: C-13 in Facile (5 minuti), C-14 in Normale (10), C-15 in Difficile (15), C-18 in Estremo (30).","Canonical bosses every 5 minutes of play, in real time: Android 13 at minute 5 (mid-fight he absorbs data and becomes Super 13, as in the movie: blue skin and orange hair), Android 14 at 10, Android 15 at 15, Android 16 at 20, Android 17 at 25, Android 18 at 30. Dr. Gero stays the first boss, at 2:30. The final boss is the first android at the end of the run: Android 13 on Easy (5 minutes), 14 on Normal (10), 15 on Hard (15), 18 on Extreme (30)."),
        T("Modalità Infinita: la serie continua con Androide 19 al minuto 35 (ti afferra e ti assorbe l'energia con i palmi, come la presa di Gero) e Androide 21 al minuto 40 (a metà scontro diventa la Forma Majin), poi ricomincia da C-13 ogni 5 minuti con il 35% di Salute in più a ogni giro. Quando continui dopo una vittoria, la serie prosegue con l'androide successivo (14 al minuto 10 dopo la Facile, ecc.). Nel pulsante e nella descrizione di Infinito di questo solo stage compare in rosso «Appaiono boss mai visti prima».","Endless mode: the series goes on with Android 19 at minute 35 (he grabs you and absorbs your energy with his palms, like Gero's hold) and Android 21 at minute 40 (mid-fight she becomes her Majin form), then starts over from Android 13 every 5 minutes with 35% more health each lap. When you continue after a win, the series goes on with the next android (14 at minute 10 after Easy, etc.). The Endless button and description of this stage alone show, in red, «Bosses you have never seen before appear»."),
        T("Mosse canoniche. C-13: Bomba Mortale S.S. (sfera rossa che ti insegue) e Martello Mortale S.S. (due zone d'impatto); Super C-13 aggiunge la Super Onda Esplosiva. C-14: Carica Androide 14, Attacco a Fendente (5 zone in fila), Tempesta di Energia (10 colpi a raggiera) e Palla Assassina. C-15: Colpo di Ki Multiplo (3 ondate), Cannone Scintilla FF (raggio dopo 0,95 s di carica), Palla Assassina e Barriera Androide. C-16: Pugno Razzo, Raggio Oculare, Lampo Infernale (raggio largo) e Autodistruzione. C-17 e C-18: Raffica di Colpi, Barriera Perfetta / Energetica e Dischi Distruttori. C-19: onde d'energia, Pugno Pesante e la presa. C-21: Raggio Famelico, Kamehameha, Taglio del Buongustaio, Teletrasporto e Taiyoken; in Forma Majin: Majin Kamehameha e Sfera della Distruzione Totale.","Canonical moves. Android 13: Deadly Bomber (a red homing ball) and Deadly Hammer (two impact zones); Super 13 adds the Super Explosive Wave. Android 14: Android Charge 14, Slicing Attack (5 zones in a row), Energy Squall (10 shots in a spread) and Murder Ball. Android 15: Multi-step Ki Blast (3 waves), F.F. Spark Cannon (beam after 0.95 s of charge), Murder Ball and Android Barrier. Android 16: Rocket Punch, Eye Beam, Hell's Flash (wide beam) and Self-Destruct. Android 17 and 18: Power Blitz, Perfect / Energy Barrier and Destructo Discs. Android 19: energy waves, Heavy Fist and the hold. Android 21: Hungry Beam, Kamehameha, Connoisseur Cut, Instant Transmission and Solar Flare; in Majin form: Majin Kamehameha and Total Detonation Ball."),
        T("Barriera (C-15, C-17, C-18, Kaioshin e Dai Kaioshin): il boss si protegge per 2,4 secondi assorbendo l'88% dei danni che subisce (cupola azzurra attorno a lui), al massimo una volta ogni 11 secondi. Autodistruzione di C-16: solo sotto il 45% di Salute e non più di una volta ogni 40 secondi; 3,4 secondi di avviso con una zona enorme (raggio 340 px) e lui resta fermo e stordito; stare lontano evita tutto il danno. C-16 e C-17 hanno qui il 150% e il 200% della loro Salute normale.","Barrier (Android 15, 17, 18, Supreme Kai and Grand Supreme Kai): the boss shields himself for 2.4 seconds, absorbing 88% of the damage he takes (a blue dome around him), at most once every 11 seconds. Android 16's Self-Destruct: only below 45% health and no more than once every 40 seconds; 3.4 seconds of warning with a huge zone (340 px radius) while he stands still and stunned; staying away avoids all damage. Android 16 and 17 have 150% and 200% of their normal health here."),
        T("Sprite: Androide 13, Super C-13, 14, 15, 18, 19, 21, la sua Forma Majin, i Kaioshin e Champa usano grafiche provvisorie fatte dal gioco (C-16 e C-17 mantengono la loro).","Sprites: Android 13, Super 13, 14, 15, 18, 19, 21, her Majin form, the Kaioshin and Champa use temporary art made by the game (Android 16 and 17 keep theirs).")
      ]},
      {g:T("Regno degli Dei","Realm of the Gods"),l:[
        T("Zarbon (e con lui Cooler e Janemba) non è più un boss di questo stage: i boss sono ora il Kaioshin (Shin: Kiai, Raggio Invisibile, Scudo di Energia), il Dai Kaioshin (psicocinesi, Onde Sacre, Sfere Sacre, Scudo Divino), Champa, Dio della Distruzione dell'Universo 6 (Mazzata, Minaccia con sfere a ricerca, Sfera Caotica della Distruzione, Ruggito) e infine Beerus come boss finale. Zarbon resta su Namek.","Zarbon (and with him Cooler and Janemba) is no longer a boss of this stage: the bosses are now the Supreme Kai (Shin: Kiai, Invisible Eye Blast, Energy Shield), the Grand Supreme Kai (psychokinesis, Sacred Waves, Sacred Orbs, Divine Shield), Champa, God of Destruction of Universe 6 (Sledgehammer, Menace with seeking spheres, Chaotic Sphere of Destruction, Roar) and finally Beerus as the final boss. Zarbon stays on Namek.")
      ]},
      {g:T("Stanza dello Spirito e del Tempo","Room of Spirit and Time"),l:[
        T("Il Maestro dello Spirito imita le tue abilità: un attacco su due è la copia della tua abilità unica (Raggio, Nova, Barriera, Cloni...) o di una delle armi che hai equipaggiato (spari, raggi, catene di fulmini, esplosioni), con il nome dell'attacco sopra la testa e il colore dell'arma. Gli attacchi copiati infliggono il 60% del danno normale del Maestro, cioè il 40% in meno.","The Spirit Master imitates your abilities: one attack in two is a copy of your unique ability (Beam, Nova, Barrier, Clones...) or of one of the weapons you have equipped (shots, beams, chain lightning, blasts), with the name of the attack above his head and the weapon's color. Copied attacks deal 60% of the Master's normal damage, that is 40% less.")
      ]},
      {g:T("Personaggi e armi","Characters and weapons"),l:[
        T("Zeno-sama è ora un personaggio giocabile (non è più un boss): forte almeno quanto la Regina Sigma di Vampire Survivors, con tutti i numeri un po' più alti: 360 di Salute (gli altri arrivano a 150), armatura 4, danno ×1,65 più 1,5% per ogni livello, ricarica -30%, rigenerazione 2, velocità ×1,4, Esperienza ×1,35 e raggio di raccolta ×2. Parte con Sfera della Distruzione e Genkidama, la sua abilità unica è la Cancellazione (ricarica 36 s) e ha 4 forme (Sorriso Innocente, Capriccio Reale, Decreto di Cancellazione, Re di Tutto). Non si compra: si sblocca completando ogni stage in modalità Estrema e sbloccando tutte le armi del gioco. Il suo sprite è l'immagine che vedi nel suo negozio.","Zeno-sama is now a playable character (no longer a boss): at least as strong as Queen Sigma from Vampire Survivors, with every number a bit higher: 360 health (the others top out at 150), armor 4, damage ×1.65 plus 1.5% per level, cooldown -30%, regeneration 2, speed ×1.4, Experience ×1.35 and pickup range ×2. He starts with Sphere of Destruction and Spirit Bomb, his unique ability is Erase (36 s cooldown) and he has 4 forms (Innocent Smile, Royal Whim, Decree of Erasure, King of Everything). He cannot be bought: you unlock him by clearing every stage on Extreme and unlocking every weapon in the game. His sprite is the picture you see in his shop."),
        T("Piccolo: la sua abilità unica è il Cannone Speciale (Special Beam Cannon), non più la Rigenerazione: due dita sulla fronte per 1,15 secondi (0,95 nella forma finale), poi un raggio a spirale sottilissimo lungo 880 px e largo 32 che trafigge tutti i nemici in linea per (60 + 5 per livello) danni e li stordisce (0,5 s; 0,15 s i boss). Ricarica 50 secondi. Passivo +7% danno e +4% critico; nella forma finale Doppio Cannone: due raggi, +40% danno, 1.180 px × 46.","Piccolo: his unique ability is the Special Beam Cannon, no longer Regeneration: two fingers on the forehead for 1.15 seconds (0.95 in the final form), then an ultra-thin spiral beam 880 px long and 32 wide that pierces every enemy in line for (60 + 5 per level) damage and stuns them (0.5 s; 0.15 s bosses). 50 seconds cooldown. Passive +7% damage and +4% crit; in the final form Twin Cannon: two beams, +40% damage, 1,180 px × 46."),
        T("Nuova arma: Granata Infernale (Hellzone Grenade), l'arma di partenza di Piccolo (al posto del Kaioken): decine di sfere di ki si formano attorno al nemico più affollato per 1,5 secondi, restano in attesa 0,45 secondi (l'ordine) e poi colpiscono tutte insieme in 0,3 secondi. Attacco lentissimo ed esplosione devastante: Lv1 ricarica 7 s, 16 sfere da 3 danni, raggio 90 px; Lv6 ricarica 4,4 s, 40 sfere da 5,8 danni, raggio 140 px. Evoluzione Granata Infernale Suprema: 2 bersagli alla volta. Seconda evoluzione Granata Infernale Divina (si sblocca come le altre: completa tutti gli stage a Normale o più con l'arma): 3 bersagli, +8 sfere ciascuno e un'esplosione più ampia.","New weapon: Hellzone Grenade, Piccolo's starting weapon (in place of Kaioken): dozens of ki spheres form around the most crowded enemy for 1.5 seconds, wait 0.45 seconds (the command) and then strike all together in 0.3 seconds. Very slow attack and devastating burst: Lv1 7 s recharge, 16 spheres of 3 damage, 90 px radius; Lv6 4.4 s recharge, 40 spheres of 5.8 damage, 140 px radius. Evolution Supreme Hellzone Grenade: 2 targets at once. Second evolution Divine Hellzone Grenade (unlocked like the others: clear every stage on Normal or higher with the weapon): 3 targets, +8 spheres each and a wider blast."),
        T("L'arma Kaioken si chiama ora Aura. Piccolo non la usa più: ora la porta Jiren, che parte con Impatto Potente e Aura (la sua pressione di guerriero più forte dell'universo).","The Kaioken weapon is now called Aura. Piccolo no longer uses it: Jiren now carries it, starting with Power Impact and Aura (the pressure of the strongest warrior of the universe)."),
        T("Toppo: la Sfera della Giustizia lancia ora una sfera oscura sul nemico più vicino (simile alla sua abilità di boss): cresce, attira i nemici vicini e dopo 1,5 secondi esplode in un raggio di 170 px per (46 + 3,4 per livello) danni; nella forma finale la sfera è gigante (raggio ×1,6, danno ×1,7, 1,8 secondi). Ricarica 44 secondi. Passivo +6% danno e +8% area.","Toppo: the Sphere of Justice now hurls a dark sphere at the nearest enemy (like his boss ability): it grows, pulls nearby enemies in and after 1.5 seconds explodes in a 170 px radius for (46 + 3.4 per level) damage; in the final form the sphere is giant (radius ×1.6, damage ×1.7, 1.8 seconds). 44 seconds cooldown. Passive +6% damage and +8% area."),
        T("Gotenks: la sua linea di trasformazioni non è più Furia Saiyan ma Super Saiyan → Super Saiyan 2 → Super Saiyan 3 → Super Saiyan God → Super Saiyan Blue (5 forme). I Fantasmi Kamikaze (ricarica 60 s) ora sono 3 fantasmi per 26 secondi (5 per 40 secondi nella forma finale) che volano contro il nemico più vicino e copiano le armi che hai attive: attaccano ogni 10 secondi al livello 1 e ogni volta 0,2 secondi prima per livello fino a 4 secondi (livello 31), con il danno delle armi ×1,5 (×2,25 nella forma finale); quando il tempo finisce esplodono sul bersaglio.","Gotenks: his transformation line is no longer Saiyan Fury but Super Saiyan → Super Saiyan 2 → Super Saiyan 3 → Super Saiyan God → Super Saiyan Blue (5 forms). Super Ghost Kamikaze (60 s cooldown) is now 3 ghosts for 26 seconds (5 for 40 seconds in the final form) that fly at the nearest enemy and copy the weapons you have active: they attack every 10 seconds at level 1 and 0.2 seconds sooner per level down to 4 seconds (level 31), with the weapons' damage ×1.5 (×2.25 in the final form); when the time is up they explode on the target.")
      ]}
    ],
    bal:[
      {g:T("Difficoltà","Difficulty"),l:[
        T("Aumento di Salute dei nemici: in Normale, Difficile ed Estremo il rinforzo che scatta a intervalli avviene ora ogni 10 minuti (prima ogni 1:30). I valori di ogni scatto non cambiano: +10% Salute, +2% danno e +5% Esperienza in Normale e Difficile; +15% Salute, +5% danno, +15% armatura e +8% Esperienza in Estremo. In pratica: la Normale da 10 minuti non ne vede nessuno, la Difficile da 15 uno (al minuto 10) e l'Estremo da 30 due (ai minuti 10 e 20; il terzo scatta esattamente alla fine). La Facile resta ogni minuto (+1% Salute, +1% danno, +5% Esperienza). La descrizione dell'Infinito dice ora «col tempo» invece di «ogni minuto».","Enemy health growth: on Normal, Hard and Extreme the stepped reinforcement now happens every 10 minutes (it used to be every 1:30). The value of each step does not change: +10% health, +2% damage and +5% Experience on Normal and Hard; +15% health, +5% damage, +15% armor and +8% Experience on Extreme. In practice: the 10-minute Normal run sees none, the 15-minute Hard run one (at minute 10) and the 30-minute Extreme run two (at minutes 10 and 20; the third lands exactly at the end). Easy stays every minute (+1% health, +1% damage, +5% Experience). The Endless description now says «with time» instead of «every minute».")
      ]},
      {g:T("Boss","Bosses"),l:[
        T("Le trasformazioni dei boss recuperano il 50% della Salute massima e aumentano le statistiche del 20%: i combattimenti con boss che si trasformano durano più a lungo. Freezer e Cell hanno ora più forme, ma solo +2,5% di velocità per forma.","Boss transformations recover 50% of maximum health and raise the stats by 20%: fights against transforming bosses last longer. Frieza and Cell now have more forms, but only +2.5% speed per form.")
      ]}
    ]
  },
  {id:'2026-10-20c',date:'2026-10-20',
    name:T("Perfezione dei cimeli, compagni più utili e forzieri a 4 cimeli","Trinket perfection, more useful companions and 4-trinket chests"),
    sum:T("Ogni cimelio ha una Perfezione da 0% a 100% che ne muove le statistiche (100% = aura Ultra Istinto), i Mitici sono sempre più forti dei Leggendari, la schermata di scambio confronta tutto, i forzieri dei boss offrono 4 cimeli e il Compagno porta l'esperienza lontana fino a te e libera un'onda d'urto quando sei circondato.","Every trinket has a Perfection from 0% to 100% that moves its stats (100% = Ultra Instinct aura), Mythics are always stronger than Legendaries, the swap window compares everything, boss chests offer 4 trinkets and the Companion carries far-off experience to you and releases a shockwave when you are surrounded."),
    new:[
      {g:T("Compagni","Companions"),l:[
        T("Il Compagno va a prendere le gemme di Esperienza che non puoi raggiungere: quelle entro 340 px da te ma fuori dal tuo raggio di raccolta. Ne porta fino a 3 alla volta, in volo sopra la testa, e quando torna al tuo fianco te le consegna (prima attirava solo le gemme entro 140 px da sé, senza che si vedesse nulla). Se ti allontani più di 500 px smette di cercare per 1,5 secondi.","The Companion goes for the Experience gems you cannot reach: those within 340 px of you but outside your pick-up range. It carries up to 3 at once, floating above its head, and hands them over when it is back at your side (before, it only pulled in gems within 140 px of itself, and you could not see it happen). If you get more than 500 px away it stops looking for 1.5 seconds."),
        T("Onda d'urto del Compagno: quando almeno 5 nemici sono entro 165 px da te e ti circondano da almeno 3 lati, il Compagno rilascia un'onda d'urto di 210 px che infligge 12 danni più 1,1 per livello, respinge i nemici e li stordisce per 0,6 secondi (0,25 sui boss). Ricarica 5 secondi, a parte rispetto all'abilità attiva del Compagno.","Companion shockwave: when at least 5 enemies are within 165 px of you and surround you from at least 3 sides, the Companion releases a 210 px shockwave that deals 12 damage plus 1.1 per level, knocks enemies back and stuns them for 0.6 seconds (0.25 on bosses). 5 second cooldown, separate from the Companion's active ability."),
        T("La descrizione del passivo nella scelta del Compagno è stata riscritta e mostra tutte e due le funzioni.","The passive description in the Companion choice has been rewritten and covers both functions.")
      ]},
      {g:T("Cimeli e negozio","Trinkets and shop"),l:[
        T("Perfezione: ogni cimelio che trovi, compri o estrai ha un tiro da 0% a 100% che sposta le sue statistiche da -12% (0%) a +12% (100%) rispetto al valore della sua rarità. Al 50% le statistiche sono quelle di prima, quindi i cimeli che hai già non cambiano. Esempio: l'Orecchino Potara Raro dà +6% danno e +11% salute allo 0%, +7% e +12% al 50%, +8% e +13% al 100% (valori arrotondati come in gioco). I cimeli con solo un effetto (Stivali del Vento, Capsula Hoi-Poi, Cuore di Kaioh, Aureola dell'Angelo, Sfera a 4 Stelle, Anello del Tempo, Specchio dei Kaioh) non hanno Perfezione.","Perfection: every trinket you find, buy or pull comes with a roll from 0% to 100% that moves its stats from -12% (0%) to +12% (100%) around the value of its rarity. At 50% the stats are the old ones, so the trinkets you already own do not change. Example: the Rare Potara Earring gives +6% damage and +11% HP at 0%, +7% and +12% at 50%, +8% and +13% at 100% (rounded as in game). Trinkets that only have an effect (Wind Boots, Hoi-Poi Capsule, Kaioh's Heart, Angel Halo, Four-Star Ball, Ring of Time, Kaioh Mirror) have no Perfection."),
        T("Come si tira la Perfezione: valore casuale da 0 a 100, il 100% è rarissimo (circa 3 cimeli su 1000). La Fortuna alza la media (da 50% a 63% con il 60% di Fortuna) e un po' anche la probabilità del 100% e i Ticket 10× Fortunati tirano come se avessi 50% di Fortuna. Si vede come barra con la percentuale nella borsa, nella scheda personaggio, nello scambio, nel forziere, nel negozio di Zeno-sama, nella pausa e nel suggerimento degli slot in partita.","How Perfection is rolled: a random value from 0 to 100, 100% is very rare (about 3 trinkets in 1000). Luck raises the average (from 50% to 63% with 60% Luck) and slightly the chance of a 100% too and Lucky 10× Tickets roll as if you had 50% Luck. It shows as a bar with the percentage in the bag, the character screen, the swap window, the chest, Zeno-sama's shop, the pause screen and the in-run slot tooltip."),
        T("Aura Ultra Istinto: un cimelio al 100% fa brillare di bianco-argento il personaggio in partita e mette una cornice pulsante nello slot, nella borsa, nel forziere e nello scambio.","Ultra Instinct aura: a trinket at 100% makes your character glow silver-white in the run and puts a pulsing frame on the slot, the bag, the chest and the swap window."),
        T("Mitici coerenti: le fasce di statistiche di due rarità vicine non si sovrappongono più. Il miglior Comune è sempre sotto il peggior Raro e così via fino al peggior Mitico, che supera il miglior Leggendario (il Mitico vale ×1,33 del Leggendario, il tiro sposta solo del ±12%). Solo i cimeli con statistiche possono diventare Mitici (1% dei cimeli trovati in partita): prima anche Aureola, Specchio dei Kaioh e gli altri cimeli con solo un effetto potevano uscire «Mitici» senza essere migliori.","Consistent Mythics: the stat ranges of neighbouring rarities no longer overlap. The best Common is always below the worst Rare and so on up to the worst Mythic, which beats the best Legendary (Mythic is ×1.33 of Legendary, the roll only moves it by ±12%). Only trinkets with stats can turn Mythic (1% of those found in a run): before, Angel Halo, Kaioh Mirror and the other effect-only trinkets could come out \"Mythic\" without being any better."),
        T("Gacha dei Cimeli: ogni estrazione ha la sua Perfezione. Un doppione con Perfezione più alta migliora quello che possiedi (e paga comunque gli zenny di sempre), e lo vedi come «↑ Perfezione migliorata: 41% → 77%». I cimeli già nella borsa partono al 50%. Il cimelio equipaggiato entra in partita con la sua Perfezione.","Trinket Gacha: every pull has its own Perfection. A duplicate with a higher Perfection upgrades the one you own (and still pays the usual zenny), shown as \"↑ Perfection improved: 41% → 77%\". Trinkets already in the bag start at 50%. The equipped trinket enters the run with its Perfection."),
        T("In partita, trovare di nuovo un cimelio che porti già lo sostituisce se ha più Rarità o, a pari Rarità, più Perfezione; altrimenti il nuovo viene venduto.","In a run, finding a trinket you already carry replaces it if it has a higher Rarity or, at the same Rarity, more Perfection; otherwise the new one is sold."),
        T("Borsa dei cimeli: nuovo ordinamento «Perfezione» (poi Rarità e nome); l'ordinamento per Rarità, a parità, mette prima la Perfezione più alta.","Trinket bag: new sort «Perfection» (then Rarity and name); sorting by Rarity now puts the higher Perfection first when tied."),
        T("Schermata di scambio cimelio: barra di Perfezione di tutti e due i cimeli, la differenza («Perfezione 20% → 75% ▲ +55»), un verdetto Migliore / Peggiore / Pari (conta prima la Rarità, poi la Perfezione) e quanti zenny incassi se sostituisci il cimelio trovato in partita o se scarti quello nuovo.","Trinket swap window: a Perfection bar for both trinkets, the difference (\"Perfection 20% → 75% ▲ +55\"), a Better / Worse / Equal verdict (Rarity counts first, then Perfection) and how many zenny you get if you replace the trinket found in the run or drop the new one."),
        T("Slot dei cimeli in partita: più grandi (30 px, prima 26), con cornice del colore della Rarità, barra di Perfezione sotto l'icona e gli slot liberi tratteggiati fino al numero di slot che hai (1-3, vedi il negozio).","In-run trinket slots: bigger (30 px, before 26), with a frame in the Rarity colour, a Perfection bar under the icon and the free slots dashed up to the number of slots you own (1-3, see the shop)."),
        T("Impostazione «Salta i cimeli inferiori» (prima «Rifiuta cimeli di rarità inferiore»): con gli slot pieni vende subito anche un cimelio della stessa Rarità ma con meno Perfezione di tutti quelli che porti. La finestra di scambio compare solo se ne batte almeno uno. Le offerte di Zeno-sama non vengono mai saltate.","Setting «Skip lower trinkets» (before «Refuse lower-rarity trinkets»): with every slot taken it now also sells at once a trinket of the same Rarity but with less Perfection than everything you carry. The swap window only opens if it beats at least one of them. Zeno-sama's offers are never skipped.")
      ]}
    ],
    bal:[
      {g:T("Cimeli e negozio","Trinkets and shop"),l:[
        T("Forziere del boss: 4 cimeli tra cui scegliere, sempre (prima 4 più fino a 6 con la Fortuna, 10 al massimo). La Fortuna ora migliora la rarità dei cimeli offerti (già lo faceva) e, con la Perfezione, anche i tiri: il testo della scelta dice «Più fortuna, cimeli più rari».","Boss chest: 4 trinkets to choose from, always (before 4 plus up to 6 with Luck, 10 at most). Luck now improves the rarity of the offered trinkets (it already did) and, with Perfection, their rolls too: the choice text reads \"More luck, rarer trinkets\".")
      ]}
    ]
  },
  {id:'2026-10-20b',date:'2026-10-20',
    name:T("Armi a scelta, bersaglio con TAB, Tamagami e un mondo più severo","Weapon slots, TAB targeting, Tamagami and a harsher world"),
    sum:T("Da 1 a 5 armi per partita, il tasto TAB per scegliere chi colpire, le 3 Super Sfere del Drago custodite dai Tamagami, niente più camminate sull'acqua e lava che brucia, passivi dei personaggi molto più forti con il livello, ricariche delle abilità ridotte del 35%, Ki Blast al posto di Ki Barrage e un giro di nerf a Zenkai, Volo veloce, Camera Gravitazionale e Meditazione.","From 1 to 5 weapons per run, the TAB key to choose what you hit, the 3 Super Dragon Balls guarded by the Tamagami, no more walking on water and burning lava, much stronger character passives with level, ability cooldowns cut by 35%, Ki Blast instead of Ki Barrage and a round of nerfs to Zenkai, Swift Flight, Gravity Chamber and Meditation."),
    new:[
      {g:T("Armi e bersaglio","Weapons and targeting"),l:[
        T("Armi per partita: nuova impostazione da 1 a 5 (prima fisse a 5). Si cambia sotto la Selezione personaggio, vicino al cimelio, con 5 sfere del Drago: clicca la sfera del numero che vuoi (la scelta resta salvata). Il personaggio parte con le sue armi di partenza fino a quel limite, e al level-up non vengono proposte armi nuove quando gli slot sono pieni. Nella modalità libera (Sandbox) gli slot restano 5.","Weapons per run: a new setting from 1 to 5 (it used to be fixed at 5). Change it under the character screen, next to the trinket, with 5 Dragon Balls: click the ball with the number you want (the choice is saved). The character starts with its starting weapons up to that limit, and no new weapon is offered at level-up while the slots are full. In free mode (Sandbox) the slots stay at 5."),
        T("TAB cambia il bersaglio di armi e abilità: Più vicino (come prima) → Più Salute → Meno Salute → Boss (se non c'è un boss colpisce il più vicino). Il testo compare sopra il personaggio e un pannello illustrato (Vicino, HP+, HP−, Boss) a sinistra nell'HUD, sotto l'etichetta della trasformazione, mostra la modalità attiva e ha un piccolo effetto quando cambia. TAB funziona solo durante la partita (nei menu mantiene il comportamento normale); su controller è il tasto 10. Il tasto si può cambiare in Impostazioni > Controlli («Bersaglio armi»).","TAB changes the target of weapons and abilities: Closest (as before) → Most HP → Least HP → Boss (with no boss it hits the closest). The name shows above the character and an illustrated panel (Closest, HP+, HP−, Boss) on the left of the HUD, under the form label, shows the active mode and pops briefly when it changes. TAB only works during a run (menus keep their normal behaviour); on a controller it is button 10. You can rebind it in Settings > Controls («Weapon target»)."),
      ]},
      {g:T("Super Sfere del Drago e Tamagami","Super Dragon Balls and Tamagami"),l:[
        T("Le Super Sfere del Drago passano da 7 a 3 (stelle 1, 2 e 3); i salvataggi con più di 3 sfere vengono riportati a 3 automaticamente. In basso a destra compare l'indicatore delle 3 sfere, visibile dopo aver trovato la prima.","Super Dragon Balls go from 7 to 3 (stars 1, 2 and 3); saves holding more than 3 balls are brought back to 3 automatically. An indicator of the 3 balls appears at the bottom right once you have found the first one."),
        T("Ogni Super Sfera è sorvegliata da un Tamagami: una statua di pietra che si risveglia quando ti avvicini a meno di 340 pixel e diventa un boss (N°1 la Spada: onde di spada, cariche e raggi a croce; N°2 la Lancia: cariche con il tridente e raffiche di energia; N°3 il Martello: colpi a terra e onde dai palmi). La sfera resta bloccata finché non lo sconfiggi; sotto metà salute il Tamagami entra in Furia (forma più veloce e più forte). La Salute del Tamagami cresce con i minuti della partita (da ×0,7 a ×1,6 della base: 14000 / 11000 / 9500).","Every Super Dragon Ball is guarded by a Tamagami: a stone statue that wakes up when you come within 340 pixels and becomes a boss (No. 1 the Sword: sword waves, dashes and cross beams; No. 2 the Spear: trident charges and energy barrages; No. 3 the Hammer: ground slams and palm waves). The ball stays locked until you defeat it; below half health the Tamagami enters its Fury form (faster and stronger). The Tamagami's HP grows with the minutes of the run (from ×0.7 to ×1.6 of its base: 14000 / 11000 / 9500)."),
        T("Grafica definitiva dei Tamagami: ognuno ha il proprio foglio di sprite a 9 frame (fermo, camminata a 4 frame, carica, colpo, speciale, colpito) e un foglio separato per la Furia (N°1 nero con venature rosse, N°2 viola con occhi gialli, N°3 di lava arancione). Il frame cambia con l'attacco: Spada, Lancia e Martello usano carica + colpo; le onde dai palmi, i raggi a croce e le raffiche usano la posa speciale; da storditi mostrano il frame «colpito»; durante la trasformazione in Furia assumono la posa di potenziamento.","Final Tamagami art: each one has its own 9-frame sprite sheet (idle, 4-frame walk, wind-up, strike, special, hit) and a separate Fury sheet (No. 1 black with red veins, No. 2 purple with yellow eyes, No. 3 orange lava). The frame follows the attack: Sword, Spear and Hammer use wind-up + strike; palm waves, cross beams and barrages use the special pose; stunned they show the hit frame; while changing into Fury they hold the power-up pose."),
        T("Le tre statue di pietra (con il loro piedistallo) compaiono sulla mappa al posto delle sagome grigie: la Super Sfera ora fluttua sopra la testa della statua, così non la copre, e scende quando il guardiano si risveglia.","The three stone statues (on their pedestals) now stand on the map instead of the grey silhouettes: the Super Dragon Ball floats above the statue's head so it no longer hides it, and glides down when the guardian wakes up."),
      ]},
      {g:T("Mondo","World"),l:[
        T("L'acqua non si attraversa più: nelle mappe con mare e laghi il personaggio scivola lungo la riva invece di camminare sull'acqua.","Water can no longer be crossed: on maps with sea and lakes the character slides along the shore instead of walking on water."),
        T("Lava (stage Inferno): brucia il 10% della Salute massima al secondo mentre ci stai sopra.","Lava (Hell stage): burns 10% of your maximum HP per second while you stand on it."),
        T("Selezione stage: ogni scheda riporta le statistiche dei nemici dello stage: Salute (×), danno (×), velocità (% rispetto al massimo) e numero di nemici (×).","Stage select: every card lists the stage's enemy stats: Health (×), damage (×), speed (% of the maximum) and number of enemies (×)."),
      ]},
      {g:T("Level-up e Senzu","Level-ups and Senzu"),l:[
        T("Quando armi e potenziamenti sono tutti al massimo, il level-up offre 3 sacchi di Zenny (×3, ×4,5 e ×6 del valore di una moneta) invece di una Senzu. Il pulsante «⚡ Scelta automatica» sceglie da solo il sacco più grande e resta attivo finché non torna una scelta di arma o potenziamento. Si può tenere sempre attiva da Impostazioni > Partita («Scelta automatica a potenziamenti al massimo»).","When weapons and upgrades are all maxed, a level-up offers 3 bags of Zenny (×3, ×4.5 and ×6 the value of a coin) instead of a Senzu. The «⚡ Auto-choose» button picks the biggest bag by itself and stays on until a weapon or upgrade choice comes back. You can keep it always on from Settings > Gameplay («Auto-choose when everything is maxed»)."),
        T("Senzu: ora cura il 50% della Salute (prima 40%) e alza di una piccola quantità una statistica a caso (Danno +3%, Velocità +2%, Ricarica −1,2%, Salute +8, rigenerazione +0,12/s o raccolta +6%) fino a fine partita.","Senzu: now heals 50% of your HP (it was 40%) and raises one random stat by a small amount (Damage +3%, Speed +2%, Cooldown −1.2%, HP +8, regeneration +0.12/s or pickup range +6%) for the rest of the run."),
        T("La freccia rossa (+15% danno) viene attirata come monete e cuori.","The red arrow (+15% damage) is now attracted like coins and hearts."),
        T("Le capsule Hoi-Poi a terra, che davano un cimelio, sono state rimosse dai ritrovamenti (anche dalle isole del Serpente: al loro posto c'è un cuore).","The Hoi-Poi capsules on the ground, which gave a trinket, were removed from the pickups (also from the Snake Way isles, where a heart takes their place)."),
      ]},
      {g:T("Abilità","Abilities"),l:[
        T("Le abilità dei personaggi si possono usare anche nella Stanza dello Spirito e del Tempo (prima bloccate); restano bloccate solo nel negozio di Zeno.","Character abilities can now be used in the Room of Spirit and Time too (they were blocked); they stay blocked only in Zeno's shop."),
      ]},
    ],
    bal:[
      {g:T("Difficoltà e nemici","Difficulty and enemies"),l:[
        T("Facile: Salute di nemici e boss ×0,72 (prima ×0,9, cioè −20%).","Easy: enemy and boss Health ×0.72 (it was ×0.9, i.e. −20%)."),
        T("I nemici compaiono più lontano dal bordo superiore dello schermo: +50% di distanza verso l'alto (500 → 750 pixel), invariata negli altri lati.","Enemies now appear farther from the top edge of the screen: +50% distance upward (500 → 750 pixels), unchanged on the other sides."),
        T("Velocità dei nemici in base alla difficoltà dello stage: ×0,8 nel primo stage fino a ×1,1 al massimo (+0,07 per ogni punto di difficoltà); prima tutti ×1,1.","Enemy speed by stage difficulty: ×0.8 on the first stage up to ×1.1 at most (+0.07 per difficulty point); it used to be ×1.1 everywhere."),
      ]},
      {g:T("Personaggi e abilità","Characters and abilities"),l:[
        T("Passivo del personaggio (forma intermedia in poi): il bonus è moltiplicato per 1,5 al Lv 1 e cresce di +0,05 a ogni livello fino a ×6,45 al Lv 100 (prima ×1 fisso). Il tooltip dell'abilità mostra il moltiplicatore attuale.","Character passive (middle form onward): the bonus is multiplied by 1.5 at Lv 1 and grows by +0.05 every level up to ×6.45 at Lv 100 (it was a fixed ×1). The ability tooltip shows the current multiplier."),
        T("Ricarica delle abilità dei personaggi −35% (per esempio 60 s base: da 42 s a 27,3 s).","Character ability cooldowns −35% (for example 60 s base: from 42 s to 27.3 s)."),
      ]},
      {g:T("Potenziamenti passivi","Passive upgrades"),l:[
        T("Zenkai: +10% danno per livello (prima +15%).","Zenkai: +10% damage per level (it was +15%)."),
        T("Volo veloce: +6% velocità per livello (prima +8%).","Swift Flight: +6% speed per level (it was +8%)."),
        T("Camera Gravitazionale: −5% ricarica per livello (prima −8%).","Gravity Chamber: −5% cooldown per level (it was −8%)."),
        T("Meditazione: +8% esperienza per livello (prima +12%).","Meditation: +8% experience per level (it was +12%)."),
      ]},
      {g:T("Totem","Totems"),l:[
        T("Totem della Tempesta: un fulmine ogni 20 s (prima 22 s), −20% di attesa per ogni trasformazione (8,2 s con quattro trasformazioni).","Storm Totem: lightning every 20 s (it was 22 s), −20% wait for every transformation (8.2 s with four transformations)."),
        T("Totem dello Spirito: un impulso ogni 20 s (prima 35 s), −20% per trasformazione; cura il 6% + 1,5% per trasformazione fino a un massimo del 12% (prima 6% fisso).","Spirit Totem: a pulse every 20 s (it was 35 s), −20% per transformation; it heals 6% + 1.5% per transformation up to a maximum of 12% (it was a flat 6%)."),
        T("Totem del Rischio: dura 3 minuti (prima 150 secondi).","Totem of Risk: lasts 3 minutes (it was 150 seconds)."),
      ]},
      {g:T("Armi","Weapons"),l:[
        T("Ki Barrage rimosso. Tutti i personaggi che lo avevano di partenza (Cell, Gotenks, Caulifla, C-21, Saiyaman) ora partono con Ki Blast.","Ki Barrage removed. Every character that started with it (Cell, Gotenks, Caulifla, C-21, Saiyaman) now starts with Ki Blast."),
        T("Ki Blast: danno −15% a ogni livello (Lv 1–6: 8,5 / 10 / 12 / 13,5 / 16 / 19,5; prima 10 / 12 / 14 / 16 / 19 / 23).","Ki Blast: damage −15% at every level (Lv 1–6: 8.5 / 10 / 12 / 13.5 / 16 / 19.5; it was 10 / 12 / 14 / 16 / 19 / 23)."),
      ]},
    ],
  },
  {id:'2026-10-20',date:'2026-10-20',
    name:T("Menu rinnovati, negozio potenziato, Achievement e missioni giornaliere","Revamped menus, stronger shop, Achievements and daily quests"),
    sum:T("Ricerca e ordinamento dei personaggi, Avvio rapido, statistiche numeriche delle armi in pausa, Reroll / Salta / Ban al level-up, un negozio più forte (e più caro), la nuova schermata Achievement per sapere cosa fare per sbloccare personaggi e armi, Obiettivi con 36 nuovi traguardi e le missioni giornaliere.","Character search and sorting, Quick Start, numeric weapon stats in the pause menu, Reroll / Skip / Ban on level-up, a stronger (and pricier) shop, the new Achievement screen that tells you how to unlock characters and weapons, Objectives with 36 new goals and daily quests."),
    new:[
      {g:T("Menu e interfaccia","Menus and interface"),l:[
        T("Ingranaggio ⚙ (Impostazioni) in alto a destra nella Selezione stage e nella Selezione personaggio.","A ⚙ gear button (Settings) at the top right of the stage and character screens."),
        T("Selezione personaggio: barra di ricerca (nome, razza, universo, serie, arma di partenza) e menu «Ordina» (Predefinito, Nome, Razza, Universo, Serie, Salute, Danno, Velocità, Sbloccati) con il tasto ↑/↓ per invertire l'ordine. La scelta resta salvata.","Character screen: a search box (name, race, universe, series, starting weapon) and a «Sort» menu (Default, Name, Race, Universe, Series, Health, Damage, Speed, Unlocked) with an ↑/↓ button to reverse the order. Your choice is remembered."),
        T("⚡ Avvio rapido (menu principale e Selezione personaggio): una schermata con il personaggio scelto (con lo slot del cimelio per cambiarlo), lo stage consigliato e cosa ti manca da sbloccare (personaggio, arma o stage successivo). «Un altro suggerimento» passa al prossimo obiettivo; «Scegli a mano» torna al menu normale.","⚡ Quick Start (main menu and character screen): one screen with the chosen character (with the trinket slot to change it), the suggested stage and what is still missing to unlock (a character, a weapon or the next stage). «Another suggestion» moves to the next goal; «Choose manually» goes back to the normal menu."),
        T("Pausa: accanto a ogni arma c'è una «i» con le statistiche numeriche: danno per colpo, proiettili, ricarica, attacchi al secondo, perforazione, raggio / spessore / gittata, stordimento, velocità del proiettile, probabilità e danno critico. Quando un bonus (potenziamenti, trasformazioni, cimeli) aumenta un valore, accanto compare tra parentesi il valore base e un «+» verde con la quantità aggiunta (per esempio «9,5 (7 +2,5)»).","Pause: every weapon has an «i» with numeric stats: damage per hit, projectiles, cooldown, attacks per second, pierce, radius / width / range, stun, projectile speed, crit chance and crit damage. When a bonus (upgrades, forms, trinkets) raises a value, the base value and a green «+» with the amount added appear beside it in brackets (for example «9.5 (7 +2.5)»)."),
        T("La statistica «Potenza» ora si chiama «Danno» (pausa, negozio e potenziamento passivo).","The «Power» stat is now called «Damage» (pause, shop and passive upgrade)."),
        T("Il livello nella barra Esperienza è più grande (scritta «LV» + numero) e il nome sulla targhetta della Salute è più leggibile.","The level on the Experience bar is bigger («LV» + number) and the name on the Health plate is easier to read."),
        T("Le finestre (level-up, forzieri, cimeli, totem, Zeno...) entrano con una dissolvenza e un leggero ingrandimento (0,24 s) e le carte compaiono una dopo l'altra a distanza di 0,1 secondi; quando una finestra si ricostruisce (per esempio dopo un acquisto) non si rianima.","Windows (level-up, chests, trinkets, totems, Zeno...) fade in with a slight zoom (0.24 s) and the cards appear one after the other 0.1 s apart; when a window is rebuilt (for example after a purchase) it does not replay the intro."),
        T("Le notifiche di sblocco e obiettivo in alto a destra restano 3,5 secondi, poi risalgono verso l'alto sfumando in 3 secondi.","Unlock and objective notifications at the top right stay for 3.5 seconds, then slide back up and fade out over 3 seconds."),
        T("Modalità Infinita: la descrizione compare passando il mouse sul pulsante (non più in fondo alla schermata); se è bloccato spiega come sbloccarla.","Endless mode: the description now shows when you hover the button (no longer at the bottom of the screen); when it is locked it says how to unlock it."),
        T("Impostazioni: nuova scheda «Partita» con Tremolio schermo, Numeri dei danni, «Rifiuta cimeli di rarità inferiore» e «Apertura automatica ticket» (le prime tre erano nella scheda Generale).","Settings: a new «Gameplay» tab with Screen shake, Damage numbers, «Refuse lower-rarity trinkets» and «Auto-open tickets» (the first three used to be in the General tab)."),
        T("Pausa e Selezione personaggio: pulsanti per aprire Achievement e Obiettivi (anche dal menu principale).","Pause and character screens: buttons to open Achievement and Objectives (the main menu has them too).")]},
      {g:T("Negozio ed economia","Shop and economy"),l:[
        T("Reroll, Salta e Ban al level-up (nuovi potenziamenti del Negozio, fino a 5 acquisti ciascuno, cariche per partita): «Reroll» ripesca tutte e 3 le carte, «Salta» chiude la scelta senza prendere nulla, «Ban» ti fa scegliere un'arma o un potenziamento da non vedere più per il resto della partita (se sei in modalità Ban i tasti 1-3 bandiscono la carta). Prezzi base: Reroll 500, Salta 400, Ban 700 (a ogni acquisto ×1,6 / ×1,6 / ×1,7).","Reroll, Skip and Ban on level-up (new Shop upgrades, up to 5 purchases each, charges per run): «Reroll» redraws all 3 cards, «Skip» closes the choice taking nothing, «Ban» lets you pick a weapon or upgrade you will not see again for the rest of the run (in Ban mode the 1-3 keys ban that card). Base prices: Reroll 500, Skip 400, Ban 700 (×1.6 / ×1.6 / ×1.7 for every purchase)."),
        T("Costo totale del Negozio: 115.166 zenny per comprare tutto (prima 73.115); la schermata Negozio mostra il costo totale e quello ancora da comprare.","Total Shop cost: 115,166 zenny to buy everything (before: 73,115); the Shop screen shows the total cost and what is still left to buy."),
        T("Biglietti: il boss lascia sempre un ticket 10× (prima 20%) e ogni nemico Élite un ticket 1× (come prima, 100%).","Tickets: every boss now always drops a 10× ticket (before: 20%) and every Elite enemy a 1× ticket (as before, 100%)."),
        T("Puoi comprare ticket con gli zenny nel Gacha: 1× a 1.000 zenny, 10× a 10.000 (−20% il sabato e la domenica: 8.000, con la spiegazione nella descrizione del pulsante). Il ticket Lucky non è in vendita.","You can buy tickets with zenny in the Gacha: 1× for 1,000 zenny, 10× for 10,000 (−20% on Saturday and Sunday: 8,000, explained in the button tooltip). The Lucky ticket is not for sale."),
        T("Impostazioni > Partita > «Apertura automatica ticket»: dopo aver aperto un ticket 1× o 10× apre da solo il successivo, uno alla volta (prima quelli dello stesso tipo), ogni 2,4 secondi. Il pulsante «Ferma apertura automatica» o la chiusura della finestra lo interrompe.","Settings > Gameplay > «Auto-open tickets»: after opening a 1× or 10× ticket the next one opens by itself, one at a time (same kind first), every 2.4 seconds. The «Stop auto-open» button or closing the window interrupts it."),
        T("Serie di uccisioni: ogni 50 nemici sconfitti di fila ricevi +50 monete. Una barra nascosta si riempie a ogni uccisione e cala dell'1% ogni 0,5 secondi (2% al secondo): se si svuota la serie riparte da zero. La serie di 4 secondi dell'Esperienza (in alto a destra) non cambia.","Kill streak: every 50 enemies defeated in a row pays +50 coins. A hidden bar is refilled by every kill and drops 1% every 0.5 seconds (2% per second): if it empties the streak starts over. The 4-second XP streak (top right) is unchanged."),
        T("La modalità x2 non dà più il moltiplicatore di zenny finale (prima ×2): rende solo la partita due volte più veloce.","x2 mode no longer gives the final zenny multiplier (before: ×2): it only makes the run twice as fast.")]},
      {g:T("Cimeli e Zeno-sama","Trinkets and Zeno-sama"),l:[
        T("Negozio di Zeno-sama: i cimeli Epici, Leggendari e Mitici costano il 30% in meno (segnalato dalla scritta «−30%» nel fumetto) e in ogni visita un oggetto a caso è GRATIS.","Zeno-sama's shop: Epic, Legendary and Mythic trinkets cost 30% less (shown as «−30%» in the speech bubble) and in every visit one random item is FREE."),
        T("Zeno-sama rimbalza con un salto più alto (da 20 a 42 pixel) con schiacciamento all'atterraggio e una leggera oscillazione.","Zeno-sama bounces with a higher jump (from 20 to 42 pixels) with a squash on landing and a slight sway.")]},
      {g:T("Obiettivi e Achievement","Objectives and Achievements"),l:[
        T("Nuova schermata «Achievement» (menu principale, Selezione personaggio e pausa): elenca cosa fare per sbloccare ogni personaggio, ogni arma (vinci uno stage con chi la usa, per esempio Zarbon per Danza Elegante), ogni seconda evoluzione (completa tutti gli stage con l'arma) e 14 sfide per difficoltà (Facile, Medio, Difficile, Estremo) che danno ticket (1×, 3 × 1×, 10×, Lucky 10×) e zenny.","New «Achievement» screen (main menu, character screen and pause): it lists what to do to unlock every character, every weapon (win a stage with someone who starts with it, for example Zarbon for Elegant Dance), every second evolution (clear every stage with the weapon) and 14 challenges by difficulty (Easy, Medium, Hard, Extreme) that give tickets (1×, 3 × 1×, 10×, Lucky 10×) and zenny."),
        T("Gli Achievement di armi mostrano l'icona dell'arma; passando il mouse sopra si legge «???» finché non l'hai sbloccata, poi la spiegazione dell'arma e una «i» con le sue statistiche (livello 1 → 5, senza bonus).","Weapon Achievements show the weapon icon; hovering shows «???» until you unlock it, then the weapon description and an «i» with its stats (level 1 → 5, no bonuses)."),
        T("Gli Obiettivi ora contengono solo traguardi che danno zenny: i traguardi di sblocco delle armi sono passati agli Achievement. 36 nuovi obiettivi (boss fino a 500, nemici fino a 500.000, élite, vittorie, ore di gioco, evoluzioni, forzieri, partite, zenny guadagnati, Zeno-sama, Sfere del Drago, desideri) da 200 a 12.000 zenny ciascuno.","Objectives now hold only goals that pay zenny: the weapon-unlock goals moved to Achievements. 36 new objectives (bosses up to 500, enemies up to 500,000, elites, wins, hours played, evolutions, chests, runs, zenny earned, Zeno-sama, Dragon Balls, wishes) paying 200 to 12,000 zenny each."),
        T("Missioni giornaliere: 5 missioni (per esempio «Sconfiggi 500 mostri» +200 zenny) che cambiano ogni 6 ore e sono uguali su tutti i dispositivi; completate tutte ricevi un bonus di 1.200 zenny. Il conto alla rovescia è sopra la lista.","Daily quests: 5 quests (for example «Defeat 500 monsters» +200 zenny) that change every 6 hours and are the same on every device; finishing all of them pays a 1,200 zenny bonus. The countdown is above the list."),
        T("Achievement e Obiettivi hanno ricerca (nome, arma, descrizione), «Nascondi completati» e «Più vicini al completamento»: le scelte restano salvate.","Achievements and Objectives have a search (name, weapon, description), «Hide completed» and «Closest to completion»: your choices are remembered.")]}
    ],
    fix:[
      T("Le note di aggiornamento aperte dal menu contano come lette: l'icona rossa non riappare più, anche dopo la sincronizzazione cloud (il segno di lettura è salvato nell'account e non viene più sovrascritto da una versione più vecchia).","Patch notes opened from the menu now count as read: the red dot no longer comes back, even after a cloud sync (the read mark is saved to the account and is no longer overwritten by an older copy)."),
      T("La musica del negozio di Zeno-sama non viene più rallentata; un file di musica avviato mentre il brano è rallentato parte alla stessa velocità.","The music in Zeno-sama's shop is no longer slowed down; a music file started while the track is slowed starts at the same speed.")
    ],
    bal:[
      {g:T("Negozio","Shop"),l:[
        T("Potenziamenti potenziati (per livello, prima → ora): Avidità +15% → +18% zenny; Studio +8% → +10% esperienza; Vitalità +12 → +15 salute; Rigenerazione +0,5 → +0,6 salute/s; Danno +5% → +6%; Agilità +3% → +4% velocità; Magnetismo +15% → +20% raccolta; Armatura Saiyan +1 → +1,25; Ritmo −3% → −4% ricarica; Fortuna +7% → +9%; Occhio Critico +3% → +4% critico.","Stronger upgrades (per level, before → now): Greed +15% → +18% zenny; Study +8% → +10% experience; Vitality +12 → +15 HP; Regeneration +0.5 → +0.6 HP/s; Damage +5% → +6%; Agility +3% → +4% speed; Magnetism +15% → +20% pickup range; Saiyan Armor +1 → +1.25; Tempo −3% → −4% cooldown; Luck +7% → +9%; Keen Eye +3% → +4% crit chance."),
        T("Prezzi base +20%: Avidità 90 → 108, Studio 100 → 120, Vitalità 80 → 96, Rigenerazione 110 → 132, Danno 130 → 156, Agilità 100 → 120, Magnetismo 70 → 84, Armatura Saiyan 160 → 192, Ritmo 150 → 180, Fortuna 140 → 168, Occhio Critico 150 → 180, Seconda Vita 2.400 → 2.880, Cimelio Extra 3.000 → 3.600, Lista Nera Armi 350 → 420. A ogni acquisto il prezzo sale ancora del 50% (×1,5).","Base prices +20%: Greed 90 → 108, Study 100 → 120, Vitality 80 → 96, Regeneration 110 → 132, Damage 130 → 156, Agility 100 → 120, Magnetism 70 → 84, Saiyan Armor 160 → 192, Tempo 150 → 180, Luck 140 → 168, Keen Eye 150 → 180, Second Life 2,400 → 2,880, Extra Trinket 3,000 → 3,600, Weapon Blacklist 350 → 420. Every purchase still raises the price by 50% (×1.5).")]}
    ]
  },
  {id:'2026-10-17b',date:'2026-10-17',
    name:T("Modalità Infinita, eventi di mappa e animazioni delle armi","Endless mode, map events and weapon animations"),
    sum:T("La modalità Infinita è completa (armi fino al Lv 100, negozio di Zeno-sama ogni 5 minuti, scelta automatica dei potenziamenti), ogni mappa ha un evento a tema in cui i nemici si trasformano, il personaggio carica il Kamehameha e lancia il Colpo di Ki con le braccia e le barre Esperienza e Salute hanno la nuova grafica con il ritratto del personaggio.","Endless mode is complete (weapons up to Lv 100, Zeno-sama's shop every 5 minutes, automatic upgrade choice), every map has a themed event in which enemies transform, the character charges the Kamehameha and throws the Ki Blast with his arms, and the Experience and Health bars have the new artwork with the character's portrait."),
    new:[
      {g:T("Modalità Infinita","Endless mode"),l:[
        T("«Continua» a fine stage avvia la modalità Infinita: la partita non finisce più e i nemici non crescono più col tempo (prima ogni minuto) ma con il tuo livello. Il pulsante resta bloccato finché lo stage non è stato completato in Estrema, come prima.","'Continue' at the end of a stage starts Endless mode: the run no longer ends and enemies no longer grow with time (before: every minute) but with your level. The button stays locked until the stage has been cleared on Extreme, as before."),
        T("Armi fino al Lv 100: un'arma arrivata al Lv 5 dell'ultima evoluzione che puoi usare continua a salire per altri 95 livelli. Ogni livello extra dà +4% di danno, +1,2% di dimensione e −0,5% di tempo di ricarica; il livello mostrato è la somma (per esempio Lv 9). La ricarica totale (statistiche × arma) non scende mai sotto 0,2 secondi.","Weapons up to Lv 100: a weapon that has reached Lv 5 of the last evolution you can use keeps levelling for 95 more levels. Every extra level gives +4% damage, +1.2% size and −0.5% cooldown; the level shown is the sum (for example Lv 9). The total cooldown (stats × weapon) never goes below 0.2 seconds."),
        T("Ogni 50 livelli del personaggio: +100 monete (il bonus non è toccato dal calo delle monete) e i nemici ricevono in un colpo solo 4 scatti di crescita. A Normale e Difficile: +40% Salute e +8% Danni; a Facile: +4% e +4%; a Estrema: +60% Salute, +20% Danni e +60% Armatura. Un messaggio a schermo riporta monete e percentuali.","Every 50 character levels: +100 coins (the bonus is not affected by the coin decay) and enemies receive 4 growth steps at once. On Normal and Hard: +40% HP and +8% damage; on Easy: +4% and +4%; on Extreme: +60% HP, +20% damage and +60% armor. An on-screen message shows the coins and the percentages."),
        T("Il guadagno di monete cala del 10% ogni 15 secondi (a catena: ×0,9, dopo 150 secondi ×0,35). Non compare nessun avviso in partita: è scritto solo nella descrizione del pulsante Infinita (in 6 lingue).","Coin income drops by 10% every 15 seconds (compounded: ×0.9, ×0.35 after 150 seconds). No warning appears in game: it is only written in the description of the Endless button (in 6 languages)."),
        T("Il negozio di Zeno-sama (il pulsante rosso) ritorna ogni 5 minuti e resta aperto 4 minuti; la qualità dei cimeli dipende dalla Fortuna.","Zeno-sama's shop (the red button) comes back every 5 minutes and stays open for 4 minutes; the quality of the trinkets depends on Luck."),
        T("Esperienza: la curva è dolce e calibrata sul tuo ritmo. Parte da circa 12 secondi a livello e aumenta di 0,1 secondi a ogni livello (circa 12 minuti ogni 50 livelli).","Experience: the curve is gentle and calibrated on your own pace. It starts at about 12 seconds per level and grows by 0.1 seconds with every level (about 12 minutes per 50 levels)."),
        T("Nel menu ESC compaiono le impostazioni dell'Infinita: «Selezione automatica» (al level-up il gioco sceglie da solo il potenziamento, senza aprire il menu; con meno del 45% di Salute preferisce un Senzu) e «Priorità dei potenziamenti» (ordina fino a 10 voci, 5 armi + 5 potenziamenti: la più in alto viene scelta per prima). L'ordine resta salvato tra una partita e l'altra.","The ESC menu has the Endless settings: 'Auto-select' (on level-up the game picks the upgrade by itself without opening the menu; below 45% HP it prefers a Senzu) and 'Upgrade priorities' (order up to 10 entries, 5 weapons + 5 upgrades: the one on top is picked first). The order is saved between runs."),
      ]},
      {g:T("Eventi di mappa","Map events"),l:[
        T("Ogni mappa ha un evento a tema, annunciato con un titolo e un sottotitolo, della durata di 34-38 secondi: la prima volta arriva tra i 170 e i 250 secondi (Pianura Saiyan: 260-330 s), poi dopo 260-400 secondi di calma. I punti dove arriveranno i nemici sono segnati a terra con un cerchio che si carica, e durante l'evento alcuni nemici si trasformano in una versione più forte con un'etichetta sopra la testa.","Every map has a themed event, announced with a title and a subtitle and lasting 34-38 seconds: the first one comes between 170 and 250 seconds (Saiyan Plains: 260-330 s), then after 260-400 seconds of calm. The spots where enemies will arrive are marked on the ground with a charging circle, and during the event some enemies transform into a stronger version with a label above their head."),
        T("Pianura Saiyan, «Semi di Saibaman!»: i semi germogliano intorno a te e maturano in Saibaman kamikaze. Pianeta Namek, «Navicelle di Freezer!»: le navicelle cadono dal cielo (l'impatto fa danno: non restare sotto) e ne escono soldati e reclute Ginyu, che a metà evento si potenziano («Squadra Ginyu!»). Rovine degli Androidi, «Androidi risvegliati!»: le capsule del laboratorio si aprono e i ciborg si sovraccaricano.","Saiyan Plains, 'Saibaman Seeds!': the seeds sprout all around you and ripen into kamikaze Saibamen. Planet Namek, 'Frieza's Attack Pods!': the pods fall from the sky (the impact deals damage: do not stand under them) and soldiers and Ginyu recruits step out, powered up halfway through ('Ginyu Force!'). Android Ruins, 'Androids Activated!': the lab capsules open and the cyborgs overload."),
        T("Dimensione di Bu, «Portali di Majin Bu!»: i soldati di Bu escono dai portali e si gonfiano. Torneo del Potere, «Assalto dei Pride Troopers!»: avanzano in formazione compatta e ascendono. Isola di Muten, «Paracadutisti Red Ribbon!»: atterrano da ogni parte e i pirati diventano capitani.","Buu's Dimension, 'Majin Buu's Portals!': Buu's soldiers come out of the portals and swell up. Tournament of Power, 'Pride Troopers Assault!': they advance in tight formation and ascend. Roshi's Island, 'Red Ribbon Paratroopers!': they land from every side and the pirates become captains."),
        T("Pianeta Vegeta, «Luna piena!»: piovono meteore e i Saiyan si trasformano in Oozaru. Arena dei Cell Game, «Schiusa dei Cell Jr.!»: le uova si crepano sul ring e i Cell Jr. si corazzano. Regno degli Dei, «Discesa dei Celestiali!»: colonne di luce e sfere della distruzione, i guerrieri ascendono.","Planet Vegeta, 'Full Moon!': meteors rain down and the Saiyans turn into Great Apes. Cell Games Arena, 'Cell Jr. Hatching!': the eggs crack open on the ring and the Cell Jrs. harden their armor. Realm of the Gods, 'The Celestials Descend!': pillars of light and spheres of destruction, the warriors ascend."),
        T("Inferno, «Le porte dell'Inferno!»: il suolo si spacca e i demoni si infuriano. Via del Serpente, «Marcia dei Guardiani!»: il sentiero trema sotto i passi dei guardiani, che diventano campioni.","Hell, 'The Gates of Hell!': the ground splits and the demons fly into a rage. Snake Way, 'March of the Guardians!': the path trembles under the guardians' steps and they become champions."),
        T("Gabbiani e Nuvola Speciale non sono più solo della Via del Serpente: come effetto visivo passano anche su Pianura Saiyan, Pianeta Namek, Rovine degli Androidi, Isola di Muten, Pianeta Vegeta e Regno degli Dei (gabbiani) e su Pianura Saiyan, Dimensione di Bu, Isola di Muten e Regno degli Dei (Nuvola Speciale).","Gulls and the Flying Nimbus are no longer exclusive to Snake Way: as a visual effect they also fly over Saiyan Plains, Planet Namek, Android Ruins, Roshi's Island, Planet Vegeta and the Realm of the Gods (gulls) and over Saiyan Plains, Buu's Dimension, Roshi's Island and the Realm of the Gods (Nimbus)."),
        T("Tolti i messaggi «Respiro, raccogli le gemme!», «Tiratori in arrivo!» e «Ondata di kamikaze!»: l'ondata di tiratori continua ad arrivare ma senza annuncio, e i nemici kamikaze compaiono ora solo durante gli eventi di mappa.","Removed the messages 'Breather, collect the gems!', 'Shooters incoming!' and 'Kamikaze wave!': the shooter wave still arrives but without an announcement, and kamikaze enemies now only appear during map events."),
      ]},
      {g:T("Animazioni del personaggio","Character animation"),l:[
        T("Kamehameha: mentre carica, il personaggio tiene le due mani a coppa davanti al petto con la sfera che cresce tra le mani, e continua a camminare con le gambe (prima si fermava in posa); quando parte il raggio le due braccia si tendono verso il bersaglio. Vale anche per il Big Bang Kamehameha. Il personaggio si gira verso il bersaglio durante il gesto.","Kamehameha: while charging, the character holds both hands cupped in front of the chest with the ball growing between them, and keeps walking with his legs (before he froze in a pose); when the beam fires both arms stretch toward the target. It also applies to the Big Bang Kamehameha. The character turns toward the target during the gesture."),
        T("Colpo di Ki: la sfera si carica sul palmo (cresce fino alla dimensione del colpo mentre finisce la ricarica, quindi la cadenza di fuoco non cambia) e viene lanciata col braccio teso: i colpi partono dalla mano e non più dal petto. Mentre si muove il personaggio continua a camminare.","Ki Blast: the ball gathers on the palm (it grows to the size of the shot while the cooldown runs out, so the rate of fire is unchanged) and is thrown with the arm extended: the shots leave the hand instead of the chest. The character keeps walking while he moves."),
        T("Le altre armi hanno la loro posa quando sparano: braccio teso per Colpi Eccentrici, Raggio Perforante, Lancia Ribelle, Danza Elegante, Boomerang Ginyu, Granata Infernale e Sfera della Distruzione; le braccia si alternano nella Raffica di Ki; due mani per Doppio Sunday e Cannone Distruttore; braccio al cielo per Fulmine Angelico e Meteora di Fusione; pugni in avanti per Impatto Potente; mani davanti al viso per il Taiyoken; braccia alzate con la sfera sopra la testa (0,42 s) per la Genkidama.","The other weapons have their own pose when they fire: arm extended for Homing Orbs, Piercing Beam, Rebel Javelin, Elegant Dance, Ginyu Boomerang, Hellzone Grenade and Sphere of Destruction; the arms alternate with the Ki Barrage; two hands for Double Sunday and Break Cannon; an arm to the sky for Angelic Bolt and Fusion Meteor; fists forward for Power Impact; hands in front of the face for the Solar Flare; arms raised with the ball above the head (0.42 s) for the Spirit Bomb."),
        T("Per chi usa sprite propri: i fogli accettano i frame facoltativi 10-15 (carica e sparo del Kamehameha, sfera e lancio del Colpo di Ki, braccia alzate, braccio al cielo) con i punti della mano in sprites.json. Guida con i prompt per un generatore AI (docs/SPRITES_AI.md) e strumento tools/sheet_from_frames.py per assemblare il foglio.","For those who use their own sprites: sheets accept the optional frames 10-15 (Kamehameha charge and fire, Ki Blast ball and throw, raised arms, arm to the sky) with the hand points in sprites.json. Guide with prompts for an AI image generator (docs/SPRITES_AI.md) and the tools/sheet_from_frames.py tool to assemble the sheet."),
      ]},
      {g:T("Interfaccia","Interface"),l:[
        T("Barra Esperienza con la nuova grafica: medaglione con il livello, raggio luminoso che si riempie e pannello a destra con «XP attuale / necessaria» e la percentuale. Sugli schermi stretti (verticale) resta la barra sottile di prima.","Experience bar with the new artwork: medallion with the level, a glowing beam that fills up and a panel on the right with 'current / needed XP' and the percentage. On narrow (portrait) screens the thin bar of before stays."),
        T("Barra della Salute con la nuova grafica sotto la barra Esperienza: nel medaglione c'è il ritratto del personaggio in gioco, che cambia a ogni trasformazione (sprite della forma, sfondo e raggi di luce del suo colore) e fa la faccia di dolore sotto il 25% di Salute; il livello è sulla targhetta, «Salute attuale / massima» sopra la barra, una striscia grigia mostra la vita appena persa, e sotto il 30% la barra pulsa di rosso.","Health bar with the new artwork under the Experience bar: the medallion shows the portrait of the character in play, which changes with every transformation (the form's sprite, backdrop and light rays in its colour) and makes a pained face below 25% HP; the level is on the plate, 'current / max HP' sits above the bar, a grey strip shows the life just lost, and below 30% the bar pulses red."),
        T("Il negozio «Gacha» si chiama ora «Gacha dei Cimeli» (Trinket Gacha in inglese, e il corrispondente nelle altre 4 lingue), in tutti i pulsanti, titoli e descrizioni.","The 'Gacha' shop is now called 'Trinket Gacha' (and the equivalent in the other 4 languages), in every button, title and description."),
      ]},
    ],
    fix:[
      T("Dopo «Continua» nella modalità Infinita le monete già incassate con la vittoria potevano essere pagate di nuovo: ora a fine partita si pagano solo gli zenny guadagnati dopo, con la penalità del 25% della sconfitta, e quello che spendi nel negozio di Zeno-sama consuma prima le monete vecchie (il pagamento non è mai negativo né doppio).","After 'Continue' in Endless mode the coins already banked with the win could be paid again: at the end of the run only the zenny earned afterwards are paid, with the 25% defeat penalty, and what you spend in Zeno-sama's shop uses the old coins first (the payout is never negative or doubled)."),
    ],
    bal:[
      {g:T("Difficoltà","Difficulty"),l:[
        T("I nemici nuovi crescono ogni 60 secondi (prima ogni 90). Facile: Salute +1%, Danni +1%. Normale e Difficile: Salute +10% (v50: +1%), Danni +2% (v50: +1%). Estrema: Salute +15% (v50: +2%), Danni +5% (v50: +1%), Armatura +15% (v50: +5%). L'XP (+5%, Estrema +8%) non cambia.","New enemies grow every 60 seconds (before: every 90). Easy: HP +1%, damage +1%. Normal and Hard: HP +10% (v50: +1%), damage +2% (v50: +1%). Extreme: HP +15% (v50: +2%), damage +5% (v50: +1%), armor +15% (v50: +5%). XP (+5%, Extreme +8%) does not change."),
        T("Estrema: ogni 30 secondi la frequenza di comparsa dei nemici sale del 2% e il tetto di nemici sullo schermo dell'1%, fino a 60 scatti (a 30 minuti: +120% frequenza, +60% tetto).","Extreme: every 30 seconds the enemy spawn rate rises by 2% and the on-screen enemy cap by 1%, up to 60 steps (at 30 minutes: +120% rate, +60% cap)."),
        T("Broly, Berserk: dura 6 secondi (prima 10), 8 nella forma finale (prima 13). Durante il Berserk la mira di tutte le armi è imprecisa: ogni colpo ha un errore casuale fino a ±0,5 radianti (circa 29°).","Broly, Berserk: it lasts 6 seconds (before 10), 8 in the final form (before 13). While it lasts the aim of all weapons is off: every shot has a random error of up to ±0.5 radians (about 29°)."),
      ]},
      {g:T("Mappe","Maps"),l:[
        T("Via del Serpente: le isole fluttuanti sono più rare, una ogni 3.800 px di percorso (prima 1.900), circa la metà.","Snake Way: floating islands are rarer, one every 3,800 px of path (before 1,900), about half as many."),
        T("La Calamita (potenziamento a terra) ora attira anche le Borse di zenny e le monete a terra, non solo le sfere di Esperienza (restano escluse quelle sulle isole del Serpente).","The Magnet (ground power-up) now also pulls Zenny bags and coins on the ground, not only Experience orbs (the ones on the Snake Way islands are still excluded)."),
      ]},
    ]},
  {id:'2026-10-17',date:'2026-10-17',
    name:T("Mappe vive, nemici più calmi, nuove scelte","Living maps, calmer enemies, new choices"),
    sum:T("Ogni partita ha una mappa diversa e animata, il primo stage è molto meno caotico, i proiettili nemici si possono distruggere, arrivano la Lista Nera Armi e lo slot Cimelio Extra e la schermata di fine stage è tutta nuova.","Every run now has a different, animated map, the first stage is far less chaotic, enemy bullets can be destroyed, the Weapon Blacklist and the Extra Trinket slot arrive, and the end-of-stage screen is brand new."),
    new:[
      {g:T("Mappe","Maps"),l:[
        T("Ogni partita ha una mappa diversa: la disposizione di ostacoli, laghi, tonalità del terreno, decorazioni, trappole e pozze di cura (e, sulla Via del Serpente, l'andamento del corpo e le isole) viene estratta a ogni partita. L'area di partenza (250 px attorno a te) è sempre libera e all'asciutto.","Every run has a different map: the layout of obstacles, lakes, ground tones, decorations, traps and healing pools (and, on Snake Way, the winding of the body and its islands) is rolled anew each run. The start area (250 px around you) is always clear and dry."),
        T("Isola di Muten ridisegnata: sabbia arancione con increspature, mare a pixel con schiuma e battigia bagnata, rocce grandi, casse, barili, lapidi, agavi, palme, tane, conchiglie e stelle marine. Le altre mappe usano gli stessi miglioramenti nel loro tema (ostacoli, terreno e decorazioni propri).","Roshi's Island redesigned: orange sand with ripples, a pixel-art sea with foam and a wet shoreline, big rocks, crates, barrels, gravestones, agaves, palms, burrows, shells and starfish. The other maps get the same upgrade in their own theme (their own obstacles, ground and decorations)."),
        T("Acqua che si muove: i laghi della Pianura Saiyan, del Pianeta Namek e dell'Isola di Muten e la lava dell'Inferno sono animati. La schiuma avanza e si ritira in 8 fasi (cambia ogni 0,2 s; ogni 0,5 s sulla lava), le creste delle onde scorrono verso riva e i riflessi brillano. Di tanto in tanto un pesce salta fuori dall'acqua con uno spruzzo; sulla lava le bolle si gonfiano e scoppiano in scintille. L'acqua è solo scenografia: ci si cammina sopra e ostacoli, trappole e pozze di cura non compaiono nei laghi.","Moving water: the lakes of Saiyan Plains, Planet Namek and Roshi's Island and the lava of Hell are animated. The foam creeps in and out in 8 steps (it changes every 0.2 s; every 0.5 s on lava), wave crests slide toward the shore and the glints sparkle. Every now and then a fish leaps out of the water with a splash; on lava, bubbles swell and burst into sparks. Water is scenery only: you can walk over it, and obstacles, traps and healing pools never appear in lakes."),
        T("Gli oggetti sulla mappa hanno vita: ragni che camminano sul bordo di botti e casse (o penzolano dal filo), gabbiani e corvi posati, granchi che sgusciano ai piedi di casse e agavi, candele con le falene sulle lapidi, gatti che dormono sulle balle di fieno, mosche sulle pile di ossa, cristalli che brillano, lanterne che tremolano e rocce di lava che sputano braci.","Props on the map are alive: spiders crawling along the rim of barrels and crates (or hanging from a thread), perched gulls and crows, crabs scuttling at the foot of crates and agaves, candles with moths on gravestones, cats asleep on hay bales, flies over bone piles, glittering crystals, flickering lanterns and lava rocks spitting embers."),
        T("Nuove particelle d'ambiente a tema in ogni mappa: petali, sterpaglie rotolanti, anime, schegge, nuvolette e aloni.","New themed ambient particles on every map: petals, tumbleweeds, souls, shards, little clouds and halos."),
      ]},
      {g:T("Via del Serpente","Snake Way"),l:[
        T("Il corpo del serpente continua molto più a lungo: 22.000 px per lato (prima 12.000), con uccelli, nebbia e la Nuvola Speciale tra le nuvole.","The snake's body now runs much further: 22,000 px on each side (it was 12,000), with birds, mist and the Flying Nimbus among the clouds."),
        T("Isole fluttuanti lungo tutto il percorso, di 9 tipi: Pianeta di Re Kaioh, Santuario di Dio, Kame House, Torre di Karin, Capsule Corp, Pianeta del Grande Kaioh, Altare di Shenron, Nuvola Speciale e Mondo Sacro dei Kaioh. Si possono percorrere a piedi e custodiscono 3 potenziamenti ciascuna (per esempio il Pianeta di Re Kaioh: Danni +15%, Fuoco rapido, Esperienza), che compaiono una sola volta quando ti avvicini a circa 1000 px, con il nome dell'isola annunciato.","Floating islands all along the path, in 9 kinds: King Kai's Planet, Kami's Lookout, Kame House, Korin Tower, Capsule Corp, Grand Kai's Planet, Shenron's Altar, the Nimbus Cloud and the Sacred World of the Kai. You can walk on them and each one holds 3 power-ups (for example King Kai's Planet: Damage +15%, Rapid fire, Experience), laid down just once when you come within about 1000 px, with the island's name announced."),
      ]},
      {g:T("Combattimento","Combat"),l:[
        T("Le tue armi distruggono i proiettili nemici: raggi (Kamehameha), esplosioni, aree, fendenti, catene e proiettili cancellano quelli che toccano (il Colpo di Ki continua la sua corsa dopo averne colpito uno).","Your weapons destroy enemy bullets: beams (Kamehameha), explosions, areas, slashes, chains and projectiles cancel the ones they touch (the Ki Blast keeps flying after hitting one)."),
        T("Kamehameha: il raggio base è ora celeste chiaro con un denso alone blu intenso.","Kamehameha: the base beam is now light sky blue with a dense, deep blue glow."),
        T("Potenziamenti a terra con sprite nuovi, animati e il 22% più grandi: Danni +15% (la freccia rossa), Fuoco rapido, Calamita, cura, Esperienza, Capsula e Fortuna.","Ground power-ups with new animated sprites, 22% bigger: Damage +15% (the red arrow), Rapid fire, Magnet, healing, Experience, Capsule and Luck."),
        T("Raccogliere una sfera di Esperienza fa comparire scintille, un anello e una stella che sale; il suono è un tintinnio che sale di tono a ogni sfera raccolta in serie (entro 0,75 s l'una dall'altra, fino a 14 gradini). Le sfere grandi (11 XP o più) mostrano «+N XP».","Collecting an Experience orb shows sparks, a ring and a rising star; the sound is a chime that climbs in pitch with every orb collected in a row (within 0.75 s of each other, up to 14 steps). Big orbs (11 XP or more) show «+N XP»."),
      ]},
      {g:T("Cimeli e negozio","Trinkets and shop"),l:[
        T("Negozio, Cimelio Extra: +1 slot cimelio, fino a 3 cimeli insieme (massimo 2 acquisti: 3.000 e 9.000 zenny). Con tutti gli slot occupati, un nuovo cimelio apre una finestra che mostra tutti quelli che porti e chiede quale sostituire (o se tenerli tutti); il cimelio sostituito viene venduto, quello della Borsa resta nella Borsa.","Shop, Extra Trinket: +1 trinket slot, up to 3 trinkets at once (2 purchases max: 3,000 and 9,000 zenny). With every slot taken, a new trinket opens a window that shows all the ones you carry and asks which to replace (or whether to keep them all); the replaced trinket is sold, the one from the Bag stays in the Bag."),
        T("Negozio, Lista Nera Armi: ogni acquisto (fino a 10, da 350 zenny, ×1,4 a ogni acquisto) ti dà un ban. Dal pulsante «Gestisci ban» scegli quali armi sbloccate bandire: le armi bandite non compaiono più come nuove armi tra i potenziamenti, quindi le altre escono più spesso.","Shop, Weapon Blacklist: each purchase (up to 10, from 350 zenny, ×1.4 per purchase) gives you one ban. From the «Manage bans» button you choose which unlocked weapons to ban: banned weapons no longer show up as new weapons among the upgrades, so the others come up more often."),
        T("Impostazione «Rifiuta cimeli di rarità inferiore» (Impostazioni, e anche dentro le finestre dei cimeli): con tutti gli slot occupati, un cimelio di rarità inferiore a tutti quelli che porti viene venduto subito («Rifiutato: …»); la finestra di scambio compare solo per rarità uguale o superiore.","Setting «Refuse lower-rarity trinkets» (in Settings, and also inside the trinket windows): with every slot taken, a trinket of lower rarity than all the ones you carry is sold on the spot («Refused: …»); the swap window only opens for the same rarity or better."),
        T("Se trovi un cimelio che porti già: una rarità migliore lo migliora al suo posto, altrimenti il nuovo viene venduto.","If you find a trinket you already carry: a better rarity upgrades it in place, otherwise the new one is sold."),
      ]},
      {g:T("Scelte e comandi","Choices and controls"),l:[
        T("In tutte le finestre di scelta (potenziamenti, Totem, Desiderio, scambio e scelta dei cimeli, Forziere) i tasti 1-9 selezionano l'opzione corrispondente (0 la decima) e la barra spaziatrice preme il pulsante evidenziato (nel Forziere «Raccogli»). Il numero compare sulle carte.","In every choice window (upgrades, Totem, Wish, trinket swap and pick, Chest) keys 1-9 select the matching option (0 the tenth) and the Space bar presses the highlighted button (in the Chest, «Collect»). The number is shown on the cards."),
        T("Gacha: i pulsanti ora fanno estrarre in blocco, con ×1, ×10 e ×100 per il Ticket 1× e ×1 e ×10 per il Ticket 10× (al massimo 100 estrazioni alla volta, spendendo insieme i ticket necessari). Oltre le 10 estrazioni compare un solo rullo per il risultato migliore e poi l'elenco compatto di tutto.","Gacha: the buttons now pull in bulk, with ×1, ×10 and ×100 for the 1× Ticket and ×1 and ×10 for the 10× Ticket (at most 100 pulls at a time, spending the needed tickets together). Beyond 10 pulls a single reel shows the best result, then a compact list of everything."),
      ]},
      {g:T("Fine stage e modalità Infinita","End of stage and Endless"),l:[
        T("Schermata di fine stage riprogettata: titolo compatto con una Sfera del Drago per lato (non esce più dallo schermo), a sinistra tempo, uccisioni, livello e boss con le ricompense in righe compatte e i ticket in piccoli chip, a destra il danno di ogni arma (icona, nome, livello o ★ per le evoluzioni, barra, danno e percentuale; le prime 10).","End-of-stage screen redesigned: a compact title with a Dragon Ball on each side (it no longer runs off the screen), on the left time, kills, level and bosses with the rewards in compact rows and the tickets as small chips, on the right the damage of every weapon (icon, name, level or ★ for evolutions, bar, damage and share; the top 10)."),
        T("I personaggi sbloccati non sono più elencati a fine stage: compaiono come notifica in alto a destra (5 secondi) nel momento in cui raggiungi la condizione, mentre giochi.","Unlocked characters are no longer listed at the end of a stage: they appear as a notification at the top right (5 seconds) the moment you meet the condition, while you play."),
        T("La modalità Infinita è un pulsante accanto a Riprova e Menu, al posto della scritta «completa tutti e 5 gli stage»: resta bloccato finché lo stage non viene completato in difficoltà Estrema (e si può usare solo dopo aver vinto lo stage).","Endless mode is a button next to Retry and Menu, replacing the «clear all 5 stages» text: it stays locked until the stage has been cleared on Extreme (and it is only available after winning the stage)."),
      ]},
      {g:T("Personaggi e trasformazioni","Characters and transformations"),l:[
        T("Kaioken e Ultra Istinto appartengono solo a Goku (che mantiene le sue trasformazioni canoniche). Gli altri Saiyan (Gohan, Trunks, Goten, Bardock e il resto) sostituiscono il Kaioken con «Furia Saiyan» e si fermano al Super Saiyan Blue; anche le linee di Piccolo e Nail, degli umani (Krillin, Tien, Muten e gli altri), degli Androidi e di Beerus e Whis perdono le ultime due forme «Istinto Superiore».","Kaioken and Ultra Instinct belong to Goku only (who keeps his canonical forms). The other Saiyans (Gohan, Trunks, Goten, Bardock and the rest) replace Kaioken with «Saiyan Fury» and stop at Super Saiyan Blue; the lines of Piccolo and Nail, of the humans (Krillin, Tien, Muten and the rest), of the Androids and of Beerus and Whis also lose their last two «Ultra Instinct» forms."),
        T("Vegeta: prima del Super Saiyan c'è «Orgoglio Saiyan» (colori base, con animazione di trasformazione), dal Super Saiyan al Blue tutto come prima, e il finale è «Ultra Ego (risveglio)» e «Ultra Ego» con aura viola.","Vegeta: before Super Saiyan there is «Saiyan Pride» (basic colours, with its transformation animation), from Super Saiyan to Blue everything is as before, and the finale is «Ultra Ego (Awakening)» and «Ultra Ego» with a purple aura."),
        T("Re Kaioh: il Kaioken x3/x10/x20 diventa «Gravità x10», «Gravità x100» e «Maestro Celeste». Gli obiettivi «Segno dell'Istinto» e «Perfetto» richiedono Goku; «Il fuoco dentro» richiede la prima trasformazione di qualsiasi personaggio.","King Kai: Kaioken x3/x10/x20 become «Gravity x10», «Gravity x100» and «Heavenly Master». The «Sign of Instinct» and «Perfected» achievements require Goku; «Inner Fire» requires the first transformation of any character."),
        T("Sblocco delle armi: si sblocca un'arma semplicemente vincendo uno stage con un personaggio che parte con quell'arma (in qualunque difficoltà; un secondo personaggio con la stessa arma, come la Kamehameha, non sblocca niente di nuovo). Prima serviva il livello 50 o completare lo stage in Normale o più.","Weapon unlocks: a weapon is unlocked simply by winning a stage with a character who starts with it (on any difficulty; a second character with the same weapon, like the Kamehameha, unlocks nothing new). Before, you needed level 50 or to clear the stage on Normal or higher."),
      ]},
      {g:T("Note di patch","Patch notes"),l:[
        T("Le note hanno ora un titolo, un riassunto e gruppi tematici dentro ogni sezione, con i nomi esatti usati dal gioco e i numeri prima/dopo.","The notes now have a title, a summary and themed groups inside each section, using the exact names the game shows and before/after numbers."),
      ]},
    ],
    fix:[
      T("Schermata di fine stage: la scritta «Stage completato» usciva dallo schermo; ora il titolo si adatta alla larghezza e va su due righe quando ha due parole.","End-of-stage screen: the «Stage clear» title ran off the screen; it now fits the width and splits into two lines when it has two words."),
      T("Fine stage: i ticket trovati e i cimeli venduti sono compattati in piccoli chip e le righe di sblocco sono state tolte (vedi le notifiche).","End of stage: the tickets found and the trinkets sold are condensed into small chips and the unlock lines have been removed (see the notifications)."),
      T("Il corpo del raggio Kamehameha era più sottile dell'area che colpiva: ora è più spesso (0,62× la larghezza del raggio, prima 0,42×).","The Kamehameha beam's body was thinner than the area it hit: it is now thicker (0.62× the beam width, it was 0.42×)."),
    ],
    bal:[
      {g:T("Ritmo della partita","Pacing"),l:[
        T("Meno nemici: il ritmo di comparsa a fine stage scende da 12× a 8,5× (da 1+11·x a 0,85·(1+9·x)) e il tetto di nemici sullo schermo è il 78% di prima. In modalità Facile il moltiplicatore di comparsa passa da 0,8 a 0,7; in modalità x2 i nemici compaiono un ulteriore 15% più lentamente e tutti gli eventi arrivano a intervalli ×1,5.","Fewer enemies: the end-of-stage spawn rate drops from 12× to 8.5× (from 1+11·x to 0.85·(1+9·x)) and the on-screen enemy cap is 78% of what it was. On Easy the spawn multiplier goes from 0.8 to 0.7; in x2 mode enemies spawn a further 15% slower and every event comes at ×1.5 intervals."),
        T("Orde: la prima arriva a 150 s (prima 130 s), poi ogni 1,35× più tardi. Branchi: il primo a 75 s (prima 40 s), poi ogni 65 s (prima 40 s).","Hordes: the first at 150 s (it was 130 s), then 1.35× further apart. Packs: the first at 75 s (it was 40 s), then every 65 s (it was 40 s)."),
        T("Ondate: ora la prima arriva a 150-190 s (prima 52-68 s) e le successive ogni 110-160 s di calma (prima 38-52 s); durano sempre 15 secondi ma con più nemici: ritmo ×2,6 (prima ×1,75) e tetto ×1,5 (prima ×1,2).","Waves: the first now arrives at 150-190 s (it was 52-68 s) and the following ones after 110-160 s of calm (it was 38-52 s); they still last 15 seconds but bring more enemies: rate ×2.6 (it was ×1.75) and cap ×1.5 (it was ×1.2)."),
        T("Eventi speciali: l'Ondata di Kamikaze arriva la prima volta tra 180 e 260 s (prima 90-150 s), poi ogni 260-380 s (prima 150-240 s); l'Ondata di Tiratori tra 170 e 230 s (prima 60-100 s), poi ogni 240-340 s (prima 130-200 s). Nello stage 1 non compaiono più.","Special events: the Kamikaze Wave arrives the first time between 180 and 260 s (it was 90-150 s), then every 260-380 s (it was 150-240 s); the Gunner Wave between 170 and 230 s (it was 60-100 s), then every 240-340 s (it was 130-200 s). In stage 1 they no longer appear."),
        T("Oggetti sulla mappa: i potenziamenti casuali a terra compaiono la prima volta a 45-70 s (prima 30-45 s) e poi ogni 65-105 s (prima 45-75 s); le Borse di zenny sono il 36% di quelli (prima 45%). Gli eventi «Qualcosa è apparso sulla mappa» il primo a 120-170 s (prima 70-100 s), poi ogni 130-200 s (prima 80-130 s); il cumulo di monete a terra è stato rimosso da questi eventi.","Map objects: random ground power-ups first appear at 45-70 s (it was 30-45 s) and then every 65-105 s (it was 45-75 s); Zenny bags are 36% of them (it was 45%). The «Something appeared on the map» events the first at 120-170 s (it was 70-100 s), then every 130-200 s (it was 80-130 s); the pile of coins on the ground has been removed from these events."),
        T("I nemici che finiscono fuori dallo schermo (oltre 1,3 raggi di vista, prima 1,45) non spariscono: ricompaiono davanti a te, dal lato verso cui stai andando.","Enemies that end up off the screen (beyond 1.3 view radii, it was 1.45) do not vanish: they reappear in front of you, on the side you are heading to."),
      ]},
      {g:T("Difficoltà","Difficulty"),l:[
        T("Ogni 90 secondi i nemici nuovi crescono molto meno. Normale: Salute +1% (prima +10%), Danno +1% (prima +2%), XP +5% invariato. Estrema: Salute +2% (prima +15%), Danno +1% (prima +5%), Armatura +5% (prima +15%), XP +8% invariato.","Every 90 seconds new enemies grow much less. Normal: HP +1% (it was +10%), damage +1% (it was +2%), XP +5% unchanged. Extreme: HP +2% (it was +15%), damage +1% (it was +5%), armor +5% (it was +15%), XP +8% unchanged."),
        T("Cavernicolo Gigante (Isola di Muten): il suo colpo ad area sotto i piedi carica 0,5 secondi in più prima di esplodere (da 0,85-1,11 s a 1,35-1,61 s).","Giant Caveman (Roshi's Island): its area strike under your feet charges 0.5 seconds longer before it explodes (from 0.85-1.11 s to 1.35-1.61 s)."),
      ]},
      {g:T("Fuoco nemico","Enemy fire"),l:[
        T("Una salva dei nemici tiratori ha il 33% di proiettili in meno (×0,67, arrotondato, minimo 1) e l'attesa tra una salva e l'altra è ×1,8 (×2,6 sulla Via del Serpente).","An enemy shooter's volley has 33% fewer bullets (×0.67, rounded, at least 1) and the wait between volleys is ×1.8 (×2.6 on Snake Way)."),
        T("Tutti i tiratori condividono una riserva di colpi: 12 (8 sulla Via del Serpente) che si ricarica di 6 al secondo (3,4 sulla Via del Serpente); se è vuota il nemico riprova dopo circa mezzo secondo. I proiettili delle abilità costano mezzo colpo. Proiettili nemici sullo schermo: al massimo 90 (prima 230).","All shooters share a pool of shots: 12 (8 on Snake Way) that refills at 6 per second (3.4 on Snake Way); when it is empty the enemy tries again after about half a second. Skill bullets cost half a shot. Enemy bullets on the screen: 90 at most (it was 230)."),
        T("Via del Serpente: Serpe Sputafuoco, Stregone Oni, Spirito Fiammeggiante e Re Spettro compaiono la metà (peso 2, prima 4).","Snake Way: Fire-Spitting Snake, Oni Wizard, Flame Spirit and Wraith King spawn half as often (weight 2, it was 4)."),
      ]},
      {g:T("Armi","Weapons"),l:[
        T("Colpo di Ki: le due evoluzioni fanno il 50% di danno in meno.","Ki Blast: both evolutions deal 50% less damage."),
        T("Kamehameha, durata del raggio: base 0,95 / 0,88 / 0,80 / 0,72 / 0,64 s ai livelli 1-5 (prima 0,6 s a ogni livello); prima evoluzione da 0,80 s a 0,68 s e seconda da 0,78 s a 0,62 s (−0,03 e −0,04 s per livello; prima 0,8 s fissi).","Kamehameha, beam duration: base 0.95 / 0.88 / 0.80 / 0.72 / 0.64 s at levels 1-5 (it was 0.6 s at every level); first evolution from 0.80 s to 0.68 s and second from 0.78 s to 0.62 s (−0.03 and −0.04 s per level; it was a fixed 0.8 s)."),
        T("Kamehameha, larghezza del raggio (area colpita e grafica): base ×1,2 (prima ×1), prima evoluzione ×2,6 (prima ×1,8), seconda ×3,1 (prima ×2,1).","Kamehameha, width (hit area and art): base ×1.2 (it was ×1), first evolution ×2.6 (it was ×1.8), second ×3.1 (it was ×2.1)."),
      ]},
      {g:T("Economia","Economy"),l:[
        T("Tutti gli zenny guadagnati in partita sono il 20% in meno: monete da 4 a 32 (prima 5-40), Borsa di zenny da 20 a 1040 con 800 al minuto 30 (prima 25-1300 con 1000), Élite 20 (prima 25) e boss 48 (prima 60), entrambi moltiplicati per la difficoltà dello stage, bonus del primo completamento 160 per stage (prima 200), Desiderio «fortuna» 240 (prima 300), zenny di consolazione dei Forzieri (40 → 32, 60 → 48) e valore dei cimeli venduti.","All zenny earned in a run is 20% less: coins from 4 to 32 (it was 5-40), Zenny bag from 20 to 1040 with 800 at minute 30 (it was 25-1300 with 1000), Elites 20 (it was 25) and bosses 48 (it was 60), both multiplied by the stage's difficulty, first-clear bonus 160 per stage (it was 200), «fortune» Wish 240 (it was 300), the Chests' consolation zenny (40 → 32, 60 → 48) and the value of sold trinkets."),
        T("Gacha, cimeli doppioni: ora danno Comune 64, Raro 144, Epico 320, Leggendario 640 e Mitico 1280 zenny (prima 80, 180, 400, 800, 1600).","Gacha, duplicate trinkets: they now give Common 64, Rare 144, Epic 320, Legendary 640 and Mythic 1280 zenny (it was 80, 180, 400, 800, 1600)."),
      ]},
    ]},
  {id:'2026-10-16d',date:'2026-10-16',
    new:[
      T("Gacha (nuovo pulsante nel menu principale): spendi i ticket trovati in partita per estrarre cimeli da portare con te. Ci sono tre tipi di ticket: Ticket 1× (1 estrazione), Ticket 10× (10 estrazioni) e Ticket 10× Fortunato (10 estrazioni con probabilità più alte). Ogni estrazione sceglie prima la rarità e poi uno dei cimeli di quella rarità, quindi aggiungere cimeli al gioco non rende i Mitici più rari.","Gacha (new button on the main menu): spend the tickets you find in runs to pull trinkets you can bring into your runs. There are three kinds of ticket: 1× Ticket (1 pull), 10× Ticket (10 pulls) and 10× Lucky Ticket (10 pulls with better odds). Each pull rolls the rarity first and then one of the trinkets of that rarity, so adding trinkets to the game never makes Mythics rarer."),
      T("Probabilità con i ticket normali: Comune 72%, Raro 20%, Epico 6%, Leggendario 1,5%, Mitico 0,5%. Con il Ticket 10× Fortunato: Comune 45%, Raro 32%, Epico 15%, Leggendario 6%, Mitico 2%. Le stesse probabilità, e quanti cimeli esistono per ogni rarità, sono scritte nella sezione «Probabilità e cimeli disponibili» in fondo alla schermata Gacha.","Odds with normal tickets: Common 72%, Rare 20%, Epic 6%, Legendary 1.5%, Mythic 0.5%. With the 10× Lucky Ticket: Common 45%, Rare 32%, Epic 15%, Legendary 6%, Mythic 2%. The same odds, and how many trinkets exist for each rarity, are listed under \"Odds and available trinkets\" at the bottom of the Gacha screen."),
      T("Estrazione animata: per ogni cimelio gira una colonna di Sfere del Drago che si ferma sulla sfera della rarità ottenuta (1 stella = Comune, 2 = Raro, 3 = Epico, 5 = Leggendario, 7 = Mitico): più stelle, più scintille e suoni più alti. Con un Leggendario compare la scritta dorata «LEGGENDARIO!»; con un Mitico lampo di luce, raggi, schermo che trema, scritta «MITICO!» e il suono del jackpot. Con 10 estrazioni i cimeli appaiono uno dopo l'altro con effetto pop-in e suono. Il pulsante «Salta» mostra subito tutto.","Animated pull: for every trinket a column of Dragon Balls spins and stops on the ball of the rarity you got (1 star = Common, 2 = Rare, 3 = Epic, 5 = Legendary, 7 = Mythic): more stars, more sparks and higher sounds. A Legendary shows the golden \"LEGENDARY!\" lettering; a Mythic gets a flash of light, rays, a shaking screen, the \"MYTHIC!\" lettering and the jackpot sound. With 10 pulls the trinkets pop in one after the other with a sound for each. The \"Skip\" button shows everything at once."),
      T("Cimeli doppioni: se hai già quel cimelio con quella rarità l'estrazione porta la scritta DUPLICATO e ti dà il suo valore di mercato di Zeno-sama in zenny (Comune 80, Raro 180, Epico 400, Leggendario 800, Mitico 1600). I cimeli nuovi portano la scritta NUOVO e finiscono subito nella Borsa dei cimeli.","Duplicate trinkets: if you already own that trinket at that rarity the pull is marked DUPLICATE and gives you its Zeno-sama market value in zenny (Common 80, Rare 180, Epic 400, Legendary 800, Mythic 1600). New trinkets are marked NEW and go straight into the Trinket bag."),
      T("Borsa dei cimeli (pulsante nel Gacha e nella selezione del personaggio): elenca tutti i cimeli ottenuti con data di ottenimento e valore di mercato. Filtri per rarità, barra di ricerca per nome o effetto (per esempio «critico» o «salute») e ordinamento per più recenti, meno recenti, rarità o nome.","Trinket bag (button in the Gacha and in the character screen): lists every trinket you have obtained with the date you got it and its market value. Filters by rarity, a search bar by name or effect (for example \"crit\" or \"HP\") and sorting by newest, oldest, rarity or name."),
      T("Slot Cimelio nella selezione del personaggio (a destra dello sprite del personaggio): clicca il + per scegliere dalla Borsa un cimelio da portare in partita, uno solo per partita. Parte con te fin dal primo secondo, con la rarità con cui l'hai ottenuto, e non conta come cimelio trovato per gli obiettivi. Se in partita lo sostituisci con un altro, quello della Borsa resta tuo.","Trinket slot in the character screen (to the right of the character sprite): click the + to pick a trinket from the Bag to bring into the run, just one per run. It starts with you from the first second, at the rarity you obtained it, and does not count as a found trinket for the achievements. If you swap it for another one during the run, the one in the Bag stays yours."),
      T("Cimeli trovati in partita: non si tengono più, vengono venduti. Quando ne sostituisci uno trovato in partita, quando rifiuti quello nuovo e a fine partita (quello che porti addosso) ricevi zenny pari al valore di mercato di Zeno-sama (che sale del 30% per ogni livello di difficoltà dello stage) più un bonus: Comune +20, Raro +50, Epico +150, Leggendario +400, Mitico +1000. Nel primo stage fanno 100, 230, 550, 1200 e 2600 zenny. Non succede nel negozio di Zeno-sama (se non compri non vendi) né con il cimelio della Borsa.","Trinkets found in a run are no longer kept, they are sold. When you replace a trinket found in the run, when you decline the new one and at the end of the run (the one you are carrying) you receive zenny equal to the Zeno-sama market value (which grows 30% for every stage difficulty level) plus a bonus: Common +20, Rare +50, Epic +150, Legendary +400, Mythic +1000. In the first stage that is 100, 230, 550, 1200 and 2600 zenny. It does not happen in Zeno-sama's shop (if you do not buy, you do not sell) or with the trinket from the Bag."),
      T("8 nuovi cimeli con sole statistiche, per allargare il pool del Gacha: Guscio di Muten Roshi, Gi da Allenamento Pesante, Pesi da Allenamento, Tessera Capsule Corp., Medaglia del Torneo, Maschera di Jackie Chun, Pergamena della Tartaruga e Cintura del Campione. Come gli altri cimeli a statistiche esistono a tutte le rarità: i valori sono minimi nei Comuni e arrivano al massimo (per esempio +20% di danno) nei Mitici. In tutto il pool conta 29 cimeli, con 22-25 possibili per ogni rarità.","8 new stat-only trinkets, to widen the Gacha pool: Master Roshi's Shell, Heavy Training Gi, Training Weights, Capsule Corp. Card, Tournament Medal, Jackie Chun's Mask, Turtle Scroll and Champion's Belt. Like the other stat trinkets they exist at every rarity: values are tiny on Commons and reach their maximum (for example +20% damage) on Mythics. In total the pool holds 29 trinkets, with 22-25 possible at each rarity."),
      T("Come si trovano i ticket in partita: ogni Élite sconfitto lascia un Ticket 1×; ogni boss ha il 20% di lasciare un Ticket 10×; il desiderio «10 Ticket» (quarta scelta di Shenron con le 7 Sfere del Drago) dà un Ticket 10×. Un annuncio compare quando ne trovi uno, un contatore «Ticket: N estrazioni» compare sul lato destro dell'interfaccia e i ticket vengono salvati a fine partita (anche se perdi), elencati nella schermata finale.","How to find tickets in a run: every Elite you defeat drops a 1× Ticket; every boss has a 20% chance to drop a 10× Ticket; the \"10 Tickets\" wish (the fourth choice of Shenron with the 7 Dragon Balls) gives a 10× Ticket. An announcement shows when you find one, a \"Tickets: N pulls\" counter shows on the right side of the interface, and tickets are saved when the run ends (even if you lose) and listed on the end screen."),
      T("Super Sfere del Drago: negli ultimi 3 stage (Dimensione di Bu, Regno degli Dei, Torneo del Potere) le Sfere del Drago normali non compaiono più. Al loro posto, nel 55% delle partite, tra il 28% e il 55% della durata compare una Super Sfera gigante dal bagliore dorato a 520-700 px da te, con la freccia dorata ai bordi dello schermo. È sorvegliata: quando ti avvicini a meno di 340 px arriva un anello di 16 nemici (più 3 per livello di difficoltà dello stage) con +30% di vita. Ne esistono 7 (1-7 stelle), non ne compare mai una che hai già e restano salvate anche tra una partita e l'altra.","Super Dragon Balls: in the last 3 stages (Buu's Dimension, Realm of the Gods, Tournament of Power) the normal Dragon Balls no longer appear. Instead, in 55% of the runs, between 28% and 55% of the run time a giant Super Ball with a golden glow appears 520-700 px away, with the golden arrow at the screen edge. It is guarded: when you get within 340 px a ring of 16 enemies (plus 3 per stage difficulty level) with +30% HP closes in. There are 7 (1-7 stars), one you already own never appears again, and they stay saved between runs."),
      T("Super Shenron: appena hai tutte e 7 le Super Sfere compare, come prima carta del menu degli stage, lo scenario speciale «Super Shenron». Le 7 Super Sfere si consumano per scegliere tra un Ticket 10× Fortunato (ti porta al Gacha) oppure un personaggio bloccato a tua scelta gratis, senza spendere zenny (ti porta alla selezione del personaggio, dove premi «Ottieni gratis» sul personaggio che vuoi). Lo scenario scompare quando le Super Sfere sono state usate.","Super Shenron: as soon as you hold all 7 Super Balls the special \"Super Shenron\" scenario shows up as the first card of the stage menu. The 7 Super Balls are used up to choose between a 10× Lucky Ticket (takes you to the Gacha) or a locked character of your choice for free, without spending zenny (takes you to the character screen, where you press \"Get it free\" on the character you want). The scenario disappears once the Super Balls have been used."),
      T("Modalità Test: le estrazioni del Gacha sono gratuite e illimitate; i cimeli ottenuti spariscono quando disattivi la modalità, come gli acquisti del negozio.","Test mode: Gacha pulls are free and unlimited; the trinkets you get disappear when you turn the mode off, like shop purchases.")
    ],
    fix:[],
    bal:[
      T("Desiderio delle Sfere del Drago: ora ci sono quattro scelte, la nuova è «10 Ticket» (un Ticket 10× per il Gacha). Revive, Potere e Fortuna non cambiano.","Dragon Ball wish: there are now four choices, the new one is \"10 Tickets\" (a 10× Ticket for the Gacha). Second life, Power and Fortune are unchanged."),
      T("Nelle partite degli stage 9, 10 e 11 non cadono più né la Sfera del Drago garantita né quella con lo 0,07% di probabilità dai nemici: contano solo le Super Sfere.","In stages 9, 10 and 11 neither the guaranteed Dragon Ball nor the 0.07% drop from enemies appears any more: only the Super Balls count.")
    ]},
  {id:'2026-10-16c',date:'2026-10-16',
    new:[
      T("Borsa di zenny: i mucchietti di monete che compaiono ogni tanto sulla mappa (in media uno ogni 2 minuti circa, di più con la Fortuna) sono ora una Borsa di zenny con il valore scritto sopra. Il valore dipende dal momento in cui compare: 25 zenny all'inizio, circa 335 al minuto 10, 500 al minuto 15 e 1000 al minuto 30. Resta sulla mappa 90 secondi, una freccia ai bordi dello schermo la indica e viene attratta dal magnete come le monete. I bonus agli zenny (Avidità nel negozio, Totem della Ricchezza, Jackpot...) si applicano a fine partita sul totale raccolto.","Zenny bag: the piles of coins that appear on the map every now and then (on average one about every 2 minutes, more often with Luck) are now a Zenny bag with its value written above it. The value depends on the moment it appears: 25 zenny at the start, about 335 at minute 10, 500 at minute 15 and 1000 at minute 30. It stays on the map for 90 seconds, an arrow at the screen edge points to it and the magnet pulls it in like coins. Zenny bonuses (Greed in the shop, Totem of Wealth, Jackpot...) are applied at the end of the run on the total collected.")
    ],
    fix:[],
    bal:[
      T("Monete dei nemici: il valore di ogni moneta lasciata a terra (lasciata dai nemici o trovata come bottino sulla mappa, comprese quelle di Bubbles) ora cresce con il tempo, da 5 zenny a inizio partita a 40 al minuto 30 (circa 17 al minuto 10, 23 al minuto 15), e non va mai oltre 40. Prima partiva da 5 e arrivava a 20 al minuto 30. La frequenza con cui cadono non cambia, quindi il tetto evita che con molti nemici sullo schermo diventi un modo facile di farmare zenny.","Enemy coins: the value of every loose coin (dropped by enemies or found as loot on the map, Bubbles' coins included) now grows with time, from 5 zenny at the start of a run to 40 at minute 30 (about 17 at minute 10, 23 at minute 15), and never goes past 40. Before it started at 5 and reached 20 at minute 30. How often they drop is unchanged, so the cap stops a screen full of enemies from becoming an easy way to farm zenny."),
      T("Negozio: «Rimborsa tutto» restituisce ora il 100% degli zenny spesi (prima il 90%) e il pulsante non mostra più la percentuale.","Shop: \"Refund all\" now gives back 100% of the zenny spent (before: 90%) and the button no longer shows a percentage."),
      T("Dende (Compagno): cura il 30% della Salute massima (prima 7%) con Ricarica 30 secondi (prima 42).","Dende (Companion): restores 30% of max HP (before: 7%) with a 30 second cooldown (before: 42)."),
      T("Mini Shenron (Compagno): Ricarica 40 secondi (prima 55); le gemme di esperienza vengono attratte entro 400 px (prima 300) e dà un bonus di XP pari al 5% del livello (prima 3%).","Mini Shenron (Companion): 40 second cooldown (before: 55); XP gems are pulled in within 400 px (before: 300) and it gives an XP bonus equal to 5% of a level (before: 3%)."),
      T("Mini Droide (Compagno): Ricarica 40 secondi (prima 55); invulnerabilità di 1,5 secondi (prima 0,9).","Mini Droid (Companion): 40 second cooldown (before: 55); 1.5 seconds of invulnerability (before: 0.9)."),
      T("Bubbles (Compagno): Ricarica 36 secondi (prima 50); Fortuna +5% per 50 secondi (prima +3% per 40); lascia a terra 3 monete (prima 2), ognuna con il valore di una moneta dei nemici in quel momento della partita.","Bubbles (Companion): 36 second cooldown (before: 50); Luck +5% for 50 seconds (before: +3% for 40); drops 3 coins (before: 2), each worth the same as an enemy coin at that point of the run."),
      T("Mini Bu (Compagno): Ricarica 28 secondi (prima 38); stordisce i nemici entro 210 px (prima 170) per 1 secondo (prima 0,6), i boss per 0,4 secondi (prima 0,2).","Mini Buu (Companion): 28 second cooldown (before: 38); stuns enemies within 210 px (before: 170) for 1 second (before: 0.6) and bosses for 0.4 seconds (before: 0.2)."),
      T("Saibaman (Compagno): Ricarica 22 secondi (prima 30); l'esplosione infligge 12 danni + 0,8 per livello (prima 7 + 0,55) in un raggio di 160 px (prima 130).","Saibaman (Companion): 22 second cooldown (before: 30); the explosion deals 12 damage + 0.8 per level (before: 7 + 0.55) in a 160 px radius (before: 130).")
    ]},
  {id:'2026-10-16b',date:'2026-10-16',
    new:[
      T("Ritmo a ondate: di norma ogni 1-2 minuti arriva un'Ondata di 15 secondi con +75% di nemici in arrivo (e il tetto di nemici sullo schermo +20%), annunciata dal banner \"ONDATA!\". Segue un Respiro di 12 secondi (banner \"RESPIRO!\"): i nuovi nemici sono il 70% in meno, attorno a te cade una pioggia di 10-16 gemme di esperienza (in tutto circa il 9% di un livello) e le gemme dei nemici sconfitti valgono +50%. L'Ondata non parte durante i boss, a meno di 22 secondi da un'orda o da un boss in arrivo (25 secondi), durante le ondate di Kamikaze e di Tiratori e negli ultimi istanti della partita; se arriva un boss durante un'Ondata, questa finisce subito.","Wave rhythm: usually every 1-2 minutes a 15 second Surge arrives with +75% incoming enemies (and the on-screen enemy cap +20%), announced by the \"SURGE!\" banner. A 12 second Breather follows (\"BREATHER!\" banner): new enemies are reduced by 70%, a shower of 10-16 experience gems falls around you (about 9% of a level in total) and gems from defeated enemies are worth +50%. A Surge never starts during boss fights, within 22 seconds of a horde or 25 seconds of an incoming boss, during Kamikaze and Gunner waves, or in the last moments of a run; if a boss appears during a Surge, it ends at once."),
      T("Nemici Élite: da 2 a 6 per partita secondo la durata (circa uno ogni 3,5 minuti, tra un boss e l'altro, mai a meno di 28 secondi da un boss). Sono una versione dorata e più grande (+35%) di uno dei nemici più forti dello stage, con 9 volte la vita (+30% per ogni Élite già comparso), +45% di danni, +1 di Armatura (più 0,6 per livello di difficoltà dello stage), 10% più lenti, respingimento ridotto dell'80% ed Esperienza ×6. Una stella dorata sulla barra di avanzamento mostra quando arrivano; non compaiono durante un'Ondata o un boss. Sconfiggerli lascia sempre un Forziere con un potenziamento (o un'evoluzione) più un oggetto garantito, oltre a zenny e 4 gemme di esperienza.","Elite enemies: 2 to 6 per run depending on its length (about one every 3.5 minutes, between bosses, never within 28 seconds of a boss). They are a golden, bigger (+35%) version of one of the toughest enemies of the stage, with 9 times the HP (+30% for every Elite already spawned), +45% damage, +1 Armor (plus 0.6 per stage difficulty level), 10% slower, 80% less knockback and ×6 Experience. A golden star on the progress bar shows when they arrive; they do not appear during a Surge or a boss. Defeating one always leaves a Chest with an upgrade (or an evolution) plus a guaranteed trinket, along with zenny and 4 experience gems."),
      T("Nuova opzione «Effetti ridotti» in Impostazioni > Video: -60% di particelle, metà dei fulmini, niente scariche elettriche, colonne di luce, fiamme del Kaioken e raggi rotanti delle Sfere del Drago; bagliori al 60%, lampi di schermo al 30%, tremolio dello schermo ridotto a circa un terzo e particelle d'ambiente dimezzate. Gli anelli d'urto restano perché indicano cosa sta succedendo.","New option \"Reduced effects\" in Settings > Video: -60% particles, half the lightning bolts, no electric arcs, light pillars, Kaioken flames or turning rays on the Dragon Balls; glows at 60%, screen flashes at 30%, screen shake cut to about a third and ambient particles halved. Shock rings stay because they show what is happening."),
      T("Nuovo slider «Opacità degli effetti» in Impostazioni > Video, da 0% a 100% (predefinito 100%): regola l'opacità di armi, proiettili, raggi, aure (trasformazioni, Kaioken, Berserk), cariche e particelle del giocatore; a 0% sono invisibili. Non cambia lo sprite del personaggio, gli attacchi e le zone di pericolo dei nemici né l'interfaccia.","New \"Effect opacity\" slider in Settings > Video, from 0% to 100% (default 100%): sets the opacity of the player's weapons, projectiles, beams, auras (transformations, Kaioken, Berserk), charges and particles; at 0% they are invisible. It does not change the character sprite, enemy attacks and danger zones, or the interface."),
      T("Menu principale: titolo più grande (fino a 980 px di larghezza) e più in alto; il badge W.I.P. sta ora in basso a destra del titolo.","Main menu: a bigger title (up to 980 px wide) placed higher up; the W.I.P. badge now sits at the bottom right of the title.")
    ],
    fix:[],
    bal:[
      T("Sfera del Drago garantita: ogni 100-270 secondi (28% della durata della partita, 168 secondi in una partita da 10 minuti; la prima dopo il 75% di questo intervallo) ne compare una a 280-420 px da te. Mai due insieme, mai durante un boss né nell'ultimo minuto. Resta 150 secondi e la freccia ai bordi dello schermo indica dove. Resta anche lo 0,07% di probabilità di trovarne una da un nemico sconfitto.","Guaranteed Dragon Ball: every 100-270 seconds (28% of the run length, 168 seconds in a 10 minute run; the first after 75% of that interval) one appears 280-420 px from you. Never two at once, never during a boss fight or in the last minute. It stays for 150 seconds and the arrow at the screen edge shows where. The 0.07% chance of finding one from a defeated enemy remains.")
    ]},
  {id:'2026-10-16',date:'2026-10-16',
    new:[
      T("Aggiornamento automatico: quando esce una nuova versione compare un avviso con un conto alla rovescia di 10 secondi. La partita in corso viene terminata con tutte le monete guadagnate e la pagina si ricarica da sola.","Automatic updates: when a new version is released a notice appears with a 10 second countdown. The run in progress ends with every coin you earned and the page reloads by itself."),
      T("Note di aggiornamento: il tasto 📜 in alto a destra nel menu principale elenca tutte le versioni, con la data.","Patch notes: the 📜 button at the top right of the main menu lists every release, with its date."),
      T("Le abilità dei personaggi crescono con le trasformazioni: a metà della linea ottengono un nuovo bonus passivo, nella forma finale un effetto potenziato (onde enormi, raggi doppi, scudi più lunghi...).","Character abilities grow with transformations: halfway along the line they gain a new passive bonus, and in the final form an empowered effect (huge waves, double beams, longer shields...)."),
      T("La barra di avanzamento della partita mostra di nuovo i traguardi: teschio rosso per i boss, piccoli teschi bianchi per le orde, il drago Shenron per il boss finale.","The run progress bar shows its milestones again: a red skull for bosses, small white skulls for hordes, the Shenron dragon for the final boss."),
      T("Zeno-sama rimbalza nel suo negozio e spiega gli oggetti con una nuvoletta quando ti avvicini, così non li compri per sbaglio. Hai fino a 1 minuto per scegliere.","Zeno-sama bounces around his shop and explains each item in a speech bubble when you get close, so you do not buy anything by accident. You have up to 1 minute to choose."),
      T("Obiettivi: filtro per nascondere quelli ottenuti, barra di ricerca, ordinamento per i più vicini al completamento, barra di progresso su ognuno e molti nuovi obiettivi creativi.","Achievements: a filter to hide the ones you already have, a search bar, sorting by closest to completion, a progress bar on each one and many new creative achievements."),
      T("Grimorio e Glossario si aprono dalla selezione del personaggio (in alto a destra).","The Grimoire and the Glossary now open from the character select screen (top right)."),
      T("Sfere del Drago ridisegnate: sette sprite (da 1 a 7 stelle) che rimbalzano sul terreno con bagliori, raggi, colonna di luce e onda d'urto a ogni rimbalzo. Ogni sfera ha un numero di stelle diverso e il contatore in basso a destra mostra quali hai già.","Dragon Balls redrawn: seven sprites (1 to 7 stars) that bounce on the ground with glows, rays, a pillar of light and a shock wave at every landing. Every ball has a different number of stars and the counter at the bottom right shows which ones you already have."),
      T("Suono dedicato quando raccogli una Sfera del Drago.","A dedicated sound when you pick up a Dragon Ball."),
      T("Serie di uccisioni: un contatore in alto a destra conta i nemici sconfitti di fila; ai traguardi (25, 50, 100, 200...) ricevi un po' di esperienza. Quattro nuovi obiettivi dedicati.","Kill streak: a counter at the top right counts enemies defeated in a row; at the milestones (25, 50, 100, 200...) you get a little experience. Four new achievements."),
      T("Nuovo badge W.I.P. animato nel menu principale.","New animated W.I.P. badge on the main menu."),
      T("Nuovi stage Via del Serpente e Inferno, con Freezer e Cell che evolvono durante lo scontro.","New stages Snake Way and Hell, with Freezer and Cell evolving during the fight."),
      T("Attacchi speciali dei nemici, segreti da scoprire, Shop di Zeno-sama, rarità dei cimeli, scariche elettriche e aura del Kaioken.","Special enemy attacks, secrets to discover, Zeno-sama's Shop, trinket rarities, electric discharges and the Kaioken aura.")
    ],
    fix:[
      T("Gli sprite dei personaggi non hanno più linee che attraversano gli occhi.","Character sprites no longer have lines running across the eyes."),
      T("Tolto il testo sotto la scelta della difficoltà: la spiegazione della modalità x2 si legge passando il mouse sul pulsante.","Removed the text under the difficulty choice: the x2 mode explanation is shown when you hover the button.")
    ],
    bal:[
      T("Sfere del Drago: raggio di raccolta molto più piccolo e nessuna attrazione, devi passarci sopra. Le frecce ai bordi dello schermo indicano dove sono.","Dragon Balls: a much smaller pick-up radius and no attraction, you have to walk over them. The arrows at the screen edge show where they are."),
      T("Ricompense degli obiettivi molto più alte (per esempio Cacciatore 200, Sterminatore 500, completare uno stage 1000 monete). Chi li ha già ottenuti non riceve la differenza.","Achievement rewards are much higher (for example Hunter 200, Exterminator 500, clearing a stage 1000 coins). Achievements you already unlocked do not pay the difference."),
      T("Ricarica delle abilità più corta e in calo a ogni livello (fino a 10 secondi in meno al livello massimo).","Ability cooldowns are shorter and shrink with every level (up to 10 seconds less at the maximum level)."),
      T("Berserk di Broly: +80% di danni e +5 di armatura mentre è attivo (+8 nella forma finale).","Broly's Berserk: +80% damage and +5 armor while it lasts (+8 in the final form)."),
      T("Prezzi di sblocco dei personaggi ricalcolati in base ad abilità, statistiche e forza nell'anime: i più deboli costano meno, i più forti di più.","Character unlock prices recalculated from abilities, stats and strength in the anime: the weakest cost less, the strongest cost more."),
      T("Nemici più equilibrati nel tempo: ogni 1:30 +10% vita e +2% danni (prima +20% e +4%), in cambio rilasciano +5% esperienza. In modalità Estrema: +15% vita, +5% danni, +15% armatura e +8% esperienza.","Enemies scale more evenly: every 1:30 they get +10% HP and +2% damage (before: +20% and +4%) and drop +5% more experience. In Extreme mode: +15% HP, +5% damage, +15% armor and +8% experience.")
    ]},
  {id:'2026-10-15',date:'2026-10-15',
    new:[
      T("Account e salvataggi cloud: accedi per ritrovare i tuoi progressi su ogni dispositivo.","Accounts and cloud saves: log in to find your progress on every device.")
    ],fix:[],bal:[]}
];
/* the date of a release, written the way the player's language writes dates */
function patchDate(p,lang){
  try{return new Date(p.date+'T12:00:00').toLocaleDateString(lang||'it',{day:'numeric',month:'long',year:'numeric'});}catch(e){return p.date;}
}
